               else

                  ittty(itnm) = ittp
                  ittnm(itnm) = 1
                  rttdl(itnm) = 0.d0
                  rttmi(itnm) = 0.d0
                  rttma(itnm) = 0.d0

                  call moddas_reallocate_dbl(
     &                    itlmax, itnm, 2, ittrg, das_ittrg)
                  itsmn(itnm) = itsmn(itnm) + 2

                  das_ittrg(ittrg(itnm)  ) = -1.d+30
                  das_ittrg(ittrg(itnm)+1) =  1.d+30

                  call moddas_reallocate_dbl(
     &                    3, icurrent_gmsh, 2, iaddress_gmsh, gmsh)
                  gmsh(iaddress_gmsh(icurrent_gmsh)  ) = -1.d+30
                  gmsh(iaddress_gmsh(icurrent_gmsh)+1) =  1.d+30
                  iaddress_gmsh(2) = iaddress_gmsh(3)
                  icurrent_gmsh = 2

               end if

*-----------------------------------------------------------------------
*     ne or nt should be one
*-----------------------------------------------------------------------

               if( itenm(itnm) .gt. 1 .and.
     &             ittnm(itnm) .gt. 1 ) goto 935

*-----------------------------------------------------------------------
*        transformation
*-----------------------------------------------------------------------

                     itmtr(itnm,1) = igkst
                     itmtr(itnm,2) = ktrs
                     itmtr(itnm,3) = idtt
                     itmtr(itnm,4) = 0

               if( igkst .gt. 1 ) then

                  do k = 1, 13

                     rtmtr(itnm,k) = vtrs(k)

                  end do

               end if

*-----------------------------------------------------------------------
*        reg echo length
*-----------------------------------------------------------------------

                  iterl(itnm) = iechrl

*-----------------------------------------------------------------------
*        unit
*-----------------------------------------------------------------------

                  itunt(itnm) = iunt

*-----------------------------------------------------------------------
*        2d-type
*-----------------------------------------------------------------------

                  ittwo(itnm) = idtyp

*-----------------------------------------------------------------------
*        factor
*-----------------------------------------------------------------------

                  rtfac(itnm) = rfact

*-----------------------------------------------------------------------
*        volmat  ( unit = 4 -> vol = 1.0 then volmat = 0 )
*-----------------------------------------------------------------------

                  itvm(itnm) = matvol

                  if( iunt .eq. 4 .or. iunt .eq. 14 ) itvm(itnm) = 0

*-----------------------------------------------------------------------
*        epsout
*-----------------------------------------------------------------------

                  iteps(itnm) = ieps

*-----------------------------------------------------------------------
*        resolution
*-----------------------------------------------------------------------

                  itres(itnm) = max( 1, ireso )

*-----------------------------------------------------------------------
*        width
*-----------------------------------------------------------------------

                  rtwid(itnm) = width

*-----------------------------------------------------------------------
*        counter
*-----------------------------------------------------------------------

               do i = 1, 9

                  itcnt(i,itnm) = icount(i)
                  itcnth(i,itnm) = icounth(i) !frtati 2021/04/06

               end do

*-----------------------------------------------------------------------
*        counter weight
*-----------------------------------------------------------------------

                  ichnum(itnm) = ichnumtmp
                  chbias(itnm) = chbiastmp
                  ictnum(itnm) = ictnumtmp
                  ctbias(itnm) = ctbiastmp

!                  if(ictnumtmp.eq.0) then
!                   ictidx(itnm)=1
!                  else
!                   ictidx(itnm)=2
!                  endif

                  if(ichnumtmp.ne.0.or.ictnumtmp.ne.0) then
                   mftal(itnm) = 4 ! when chwei/ctwei is defined, 4 memory is necessary to be used
                  else
                   mftal(itnm) = 2 ! default value of tally memory size
                  endif

                  ictidx(itnm)=mftal(itnm)/2  ! both counter and history counter uses two memories

*-----------------------------------------------------------------------
*        axis
*-----------------------------------------------------------------------

                  itaxn(itnm) = inaxi

               do i = 1, inaxi

                  itaxs(itnm,i) = iaxis(i)

               end do

*-----------------------------------------------------------------------
*        infog
*-----------------------------------------------------------------------

                  itger(itnm) = infog

*-----------------------------------------------------------------------
*        stdcut
*-----------------------------------------------------------------------
                  rtstd(itnm) = stdcut

*-----------------------------------------------------------------------
*        maxangel
*-----------------------------------------------------------------------
                  itmxang(itnm) = imxang


*-----------------------------------------------------------------------
*        samepage
*-----------------------------------------------------------------------
                  itpgn(itnm) = inpgi

               do i = 1, inpgi

                  itpgs(itnm,i) = ipgis(i)

               end do

*-----------------------------------------------------------------------
*        file
*-----------------------------------------------------------------------

                  itfln(itnm) = infil

               do i = 1, infil

                  itfll(itnm,i) = lfile(i)

                  ctfln(itnm,i)(1:lfile(i)) = ifile(i)(1:lfile(i))

                  do k = lfile(i) + 1, 100

                     ctfln(itnm,i)(k:k) = ' '

                  end do

               end do

*-----------------------------------------------------------------------
*       restart file
*-----------------------------------------------------------------------

               call summary_param_resfile(itnm,irfflg,lrfile,irfile)

*-----------------------------------------------------------------------
*        multiplier
*-----------------------------------------------------------------------

                  itmlp(itnm) = jmul

         if( jmul .gt. 0 ) then

                  itmst(itnm) = kmst(1)

                  if( itmst(itnm) .gt. 1 ) goto 933

                  do j = 1, kmst(1)

                     itmnt(itnm,j) = kimst(1,j)

                  end do

            do k = 1, jmul

                  if( kmst(k) .ne. kmst(1) ) goto 969

                  do j = 1, kmst(1)

                     if( kimst(k,j) .ne. itmnt(itnm,j) ) goto 968

                  end do

                  itmln(itnm,k) = ktln(k)
                  itmli(itnm,k) = ktli(k)
                  rtmme(itnm,k) = dkmax(k)
                  itmpn(itnm,k) = knpat(k)

               do j = 1, knpat(k)

                  itmpt(itnm,k,j,1) = kptyp(k,j)
                  itmpt(itnm,k,j,2) = kpnkf(k,j)

               end do

                  ltli = 13 * ktln(k)

                  itsmn(itnm) = itsmn(itnm)
     &                        + ( ltli + mod(ltli,2) ) / 2
     &                        + ktls(k)

                  itmto(itnm,k,:) = imtinf(:) ! frtati 2023/12/07

            end do

         end if

*-----------------------------------------------------------------------
*        normalization parameters, T.Sato 2024/05/28
*-----------------------------------------------------------------------
                  pedest(itnm) = pedestal
                  normwwg(itnm) = norme
                  wwmax(itnm) = wwmaxtmp
                  ichplane(itnm)= ichplanetmp

*-----------------------------------------------------------------------
*        low-energy bias factor, T.Sato 2025/01/04
*-----------------------------------------------------------------------

         elowthre(itnm)=ethretmp
         elowbias(itnm)=ebiastmp
         if(ethretmp.ne.0) then ! check input parameter consistency when elowthre is defined
          if(itenm(itnm).ne.1.or.ittnm(itnm).ne.1) goto 928 ! ne = nt = 1
         endif
*-----------------------------------------------------------------------

      return

*-----------------------------------------------------------------------
*     errors
*-----------------------------------------------------------------------

  928    m_err = 'elowthre in [t-wwg] can be used only for ne = nt = 1'
         ErrCha = ''
         ErrID = 'L:4721/R:twwg/F:tallsm2.f'
         goto 999

  929    m_err = 'chplane should be xy, yx, xz, zx, yz, zy, or all'
         ErrCha = ''
         ErrID = 'L:4726/R:twwg/F:tallsm2.f'
         goto 999

  930    m_err = 'pedestal should be between 0 and 1'
         ErrCha = ''
         ErrID = 'L:4731/R:twwg/F:tallsm2.f'
         goto 999

  931    m_err = 'ctwei can be defined only once'
         ErrCha = ''
         ErrID = 'L:4736/R:twwg/F:tallsm2.f'
         goto 999
  932    m_err = 'chwei can be defined only once'
         ErrCha = ''
         ErrID = 'L:4740/R:twwg/F:tallsm2.f'
         goto 999

  933    m_err = 'multiplier set should be one in tally '//tname
         ErrCha = ''
         ErrID = 'L:4745/R:twwg/F:tallsm2.f'
         goto 999

  934    m_err = 'emin should be zero in tally '//tname
         ErrCha = ''
         ErrID = 'L:4750/R:twwg/F:tallsm2.f'
         goto 999

  935    m_err = 'ne or nt shoud be one in tally '//tname
         ErrCha = ''
         ErrID = 'L:4755/R:twwg/F:tallsm2.f'
         goto 999

  937    m_err = 'axis should be wwg, reg,eng,t,xy,yz,zx,x,y,z'
     &           //' in tally '//tname
         ErrCha = ''
         ErrID = 'L:4761/R:twwg/F:tallsm2.f'

  938    m_err = 'unit should be 1 in tally '//tname
         ErrCha = ''
         ErrID = 'L:4765/R:twwg/F:tallsm2.f'
         goto 999

  939    m_err = 'angle mesh cannot be used in tally '//tname
         ErrCha = ''
         ErrID = 'L:4770/R:twwg/F:tallsm2.f'
         goto 999

  940    m_err = 'mesh=reg, xyz should be chosen in tally '//tname
         ErrCha = ''
         ErrID = 'L:4775/R:twwg/F:tallsm2.f'
         goto 999

*-----------------------------------------------------------------------

  950    write(dkam,'(i9)') mdas
         m_err = 'Total tally storage number exceeds mdas ='//dkam
         ErrCha = ''
         ErrID = 'L:4783/R:twwg/F:tallsm2.f'
         goto 999

  968    m_err = 'mset number is inconsistent.'//tname
         ErrCha = ''
         ErrID = 'L:4788/R:twwg/F:tallsm2.f'
         goto 999

  969    m_err = 'number of mset should be the same.'//tname
         ErrCha = ''
         ErrID = 'L:4793/R:twwg/F:tallsm2.f'
         goto 999

  970    m_err = 'def of multiplier should be less than 7 '//tname
         ErrCha = ''
         ErrID = 'L:4798/R:twwg/F:tallsm2.f'
         goto 999

  971    m_err = 'number of multiplier is negative'//tname
         ErrCha = ''
         ErrID = 'L:4803/R:twwg/F:tallsm2.f'
         goto 999

  978    m_err = 'counter should be from -9999 to 9999'
         ErrCha = ''
         ErrID = 'L:4808/R:twwg/F:tallsm2.f'
         goto 999

  979    m_err = 'Description of material parameter is wrong in tally '
     &            //tname
         ErrCha = ''
         ErrID = 'L:4814/R:twwg/F:tallsm2.f'
         goto 999

  983    m_err = '2D-type should be 1-7 in tally '//tname
         ErrCha = ''
         ErrID = 'L:4819/R:twwg/F:tallsm2.f'
         goto 999

  985    m_err = 'Unit is Lethargy but energy mesh points are negative'
         ErrCha = ''
         ErrID = 'L:4824/R:twwg/F:tallsm2.f'
         goto 999

  986    write(dkam,'(i5)') itlmax
         m_err = 'Total tally number exceeds itlmax = '//dkam
         ErrCha = ''
         ErrID = 'L:4830/R:twwg/F:tallsm2.f'
         goto 999

  987    m_err = 'Unknown parameter in tally '//tname
         ErrCha = ''
         ErrID = 'L:4835/R:twwg/F:tallsm2.f'
         goto 999

  988    m_err = 'Unit should be 1,2,3,4,11,12,13,14 in tally '//tname
         ErrCha = ''
         ErrID = 'L:4840/R:twwg/F:tallsm2.f'
         goto 999

  989    m_err = 'Double definition of the parameter in tally '//tname
         ErrCha = ''
         ErrID = 'L:4845/R:twwg/F:tallsm2.f'
         goto 999

  990    m_err = 'Too many file name in tally '//tname
         ErrCha = ''
         ErrID = 'L:4850/R:twwg/F:tallsm2.f'
         goto 999

  991    m_err = 'Too many axis in tally '//tname
         ErrCha = ''
         ErrID = 'L:4855/R:twwg/F:tallsm2.f'
         goto 999

  992    m_err = 'Unknown axis name in tally '//tname
         ErrCha = ''
         ErrID = 'L:4860/R:twwg/F:tallsm2.f'
         goto 999

  993    m_err = 'In this line, [ ; ] cannot be used.'
         ErrCha = ''
         ErrID = 'L:4865/R:twwg/F:tallsm2.f'
         goto 999

  994    m_err = 'Name of particle is wrong in tally '//tname
         ErrCha = ''
         ErrID = 'L:4870/R:twwg/F:tallsm2.f'
         goto 999

cfrtati 2021/10/05 6 -> mxpart
  995    m_err = 'Number of particles is larger than mxpart in '//tname
         ErrCha = ''
         ErrID = 'L:4876/R:twwg/F:tallsm2.f'
         goto 999

  996    m_err = 'Description of mesh is wrong in tally '//tname
         ErrCha = ''
         ErrID = 'L:4881/R:twwg/F:tallsm2.f'
         goto 999

  997    m_err = 'Description of parameter is wrong in tally '//tname
         ErrCha = ''
         ErrID = 'L:4886/R:twwg/F:tallsm2.f'
         goto 999

  998    m_err = 'Unknown mesh parameter in tally '//tname
         ErrCha = ''
         ErrID = 'L:4891/R:twwg/F:tallsm2.f'
         goto 999

 1045    m_err = 'Too many samepage in tally '//tname
         ErrCha = ''
         ErrID = 'L:4896/R:twwg/F:tallsm2.f'
         goto 999

 1046    m_err = 'samepage should be wwg, reg,eng,t,xy,yz,zx,x,y,z'
     &           //' in tally '//tname
         ErrCha = ''
         ErrID = 'L:4902/R:twwg/F:tallsm2.f'
         goto 999

*-----------------------------------------------------------------------

  999 continue

         l_err = ill(jsn)
         k_err = jsn
         ierr  = 1

*-----------------------------------------------------------------------

      return
      end

************************************************************************
*                                                                      *
      subroutine tpoint(jsn,jsi,dsin,idsi,ill,ilf,
     &                  jpn,chin,chlw,chcm,i1,i2,i3,i4,ierr)
*                                                                      *
*       read [t-point] section of input files                          *
*       modified by K.Niita on 2015/03/09                              *
*                                                                      *
************************************************************************
      use sangelmod, only: itsanf
      use anatallymod, only: nanatalRead
      use partmod ! frtati 2021/10/05
      use moddas
      use moddas_mesh

      implicit real*8 (a-h,o-z)

      parameter(icsu=36) ! nais 2023/01/06

      include 'param.inc'
      include 'param01.inc'
      include 'err.inc'

*-----------------------------------------------------------------------

      common /tall00/ itnm, ital(itlmax), itals(itlmax), italm(itlmax)
      common /tall01/ itmsh(itlmax), itunt(itlmax), itspc(itlmax),
     &                itout(itlmax), ittwo(itlmax)

      common /tall07/ itety(itlmax), itenm(itlmax), iterg(itlmax),
     &                rtemi(itlmax), rtema(itlmax), rtedl(itlmax)


      common /tall10/ itaxn(itlmax), itaxs(itlmax,6)
      common /tall11/ itfln(itlmax), itfll(itlmax,6), ctfln(itlmax,6)
      character ctfln*100

      common /tall14/ ittll(itlmax), ittle(itlmax)
      character ittle*80

      common /tall15/ itanl(itlmax), itang(itlmax)
      character itang*200

      common /tall27/ itaxl(itlmax), itaxt(itlmax),
     &                itayl(itlmax), itayt(itlmax),
     &                itazl(itlmax), itazt(itlmax)
      character itaxt*200, itayt*200, itazt*200

      common /tall19/ itsmn(itlmax), itstm(itlmax)

      common /tall20/ ittty(itlmax), ittnm(itlmax), ittrg(itlmax),
     &                rttmi(itlmax), rttma(itlmax), rttdl(itlmax)
      common /tall21/ rtfac(itlmax)

      common /tall35/ iteps(itlmax)
      common /tall37/ itcnt(9,itlmax)

      common /tall45/ itmlp(itlmax), itmln(itlmax,6), itmst(itlmax),
     &                itmli(itlmax,6), rtmme(itlmax,6), itmnt(itlmax,6),
     &                itmpn(itlmax,6), itmpt(itlmax,6,6,2)

      common /tall46/ itmtr(itlmax,4), rtmtr(itlmax,13)

!OBINATA: for resfile
      common /tall59/ irfll(itlmax), crfln(itlmax), itrff(itlmax)
      character crfln*100
      character irfile*100

      common /tall62/ itpon(itlmax), rtpon(itlmax,20,4)

      common /tall67/ itstd(itlmax), rtstd(itlmax)

      common /paraj/  mstz(300), parz(300) ! T.Miura 2020/07/31

*-----------------------------------------------------------------------
      common /tall78/ itism(itlmax), itist(10,itlmax), itjst(10,itlmax),
     &                itkst(10,itlmax), itstt(itlmax), itsdd(itlmax)

      parameter ( npanatal = 12 ) ! S.H. 2020.3.27
      dimension ist_nm(npanatal), isd_nm(npanatal,kvlmax),
     &     jst_nm(npanatal), kst_nm(npanatal)

      common /tall82/ itcnth(9,itlmax)
      dimension icounth(9)
cfrtati 2023/12/07
      common /tall84/ itmto(itlmax,6,4)

! 20230106 nais samepage
      common /tall90/ itpgn(itlmax), itpgs(itlmax,6)

      common /tall91/ itextstat(itlmax), mftal(itlmax) ! S.H. extstat 2024.3.18
      common /tall93/ tprodenmn(itlmax), tprodenmx(itlmax),
     &     nbtproden(itlmax), itprodenchk(itlmax) !S.H. extstat 2024.4.28

c$$$      dimension idas(1)
      dimension idas(mdas*2) !2022.12.1 S.H. temporary for fbounds-check
      equivalence ( das, idas )


*-----------------------------------------------------------------------

      character m_err*200
      common /error/ m_err, l_err, k_err

*-----------------------------------------------------------------------

      character title*80
      character angelp*200
      character cxtxt*200
      character cytxt*200
      character cztxt*200

*-----------------------------------------------------------------------

      dimension lschn(icsu), ischn(icsu)
      character schan(icsu)*8


      data ( schan(i), i = 1, icsu ) /
     &    'point   ','part    ','e-type  ','unit    ','axis    ',
     &    'file    ','title   ','factor  ','x-txt   ','y-txt   ',
     &    'epsout  ','ctmin(1)','ctmax(1)','ctmin(2)','ctmax(2)',
     &    'ctmin(3)','ctmax(3)','multipli','t-type  ','resfile ',
     &    'angel   ','ring    ','stdcut  ','sangel  ','chmin(1)',
     &    'chmax(1)','chmin(2)','chmax(2)','chmin(3)','chmax(3)',
     &    'maxangel','samepage','iextstat','prodenmn','prodenmx',
     &    'nbproden'/

      data ( lschn(i), i = 1, icsu ) /
     &     5,         4,         6,         4,         4,
     &     4,         5,         6,         5,         5,
     &     6,         8,         8,         8,         8,
     &     8,         8,         8,         6,         7,
     &     5,         4,         6,         6,         8,
     &     8,         8,         8,         8,         8,
     &     8,         8,         8,         8,         8,
     &     8/

*-----------------------------------------------------------------------

cfrtati 2021/10/05 6 -> mxpart
      dimension iptyp(mxpart), ipnkf(mxpart)
      dimension imtyp(mxpart,mxpart), imnkf(mxpart,mxpart)
      dimension jstyp(mxpart), jnkf0(mxpart)
      dimension icount(9)

      common /subtra/ isubt, ipsub(mxpart)  ! kitamura22/03/31

      dimension iaxis(6)
      character ifile(6)*100
      dimension lfile(6)

      dimension ipgis(6)   ! samepage



*-----------------------------------------------------------------------

      character chin*200, chlw*200, chcm*200
      character chlc*200

      character dsin(0:9)*200
      dimension idsi(0:9)

      dimension ill(0:9), ilf(0:9)

      character dkam*9

      character tname*9
      data      tname /'[t-point]'/

      integer isumtalRead
*-----------------------------------------------------------------------

      dimension jptyp(6), jpnkf(6)
      dimension kptyp(6,6), kpnkf(6,6)
      dimension ktln(6), ktli(6), ktls(6), kmst(6), knpat(6)
      dimension dkmax(6)
      dimension imst(6), kimst(6,6)
      dimension imtinf(4) ! frtati 2023/12/07

*-----------------------------------------------------------------------

      dimension stpon(20,4)
      dimension irsq(10)

*-----------------------------------------------------------------------

            ierr  = 0

            nrsq  = 0
            npont = -1
            itpnt = -1
            mtcn  = 0

            irsq(1) = 1
            irsq(2) = 2
            irsq(3) = 3
            irsq(4) = 4

         do i = 5, 10

            irsq(i) = 0

         end do

            iunt  = 1
            inpat = 0
            inaxi = 0
            infil = 0
            jmul  = 0

            langel = 0

            itsanf = 0

            lxtxt  = 0
            lytxt  = 0
            ieps   = 0
            ittp   = 0
            lrfile = 0 !OBINATA
            irfflg = 0 !OBINATA
            imxang = 0 ! frtati 2021/10/05

            icount(1) = 0
            icount(2) = 0
            icount(3) = 0
            icount(4) = -9999
            icount(5) =  9999
            icount(6) = -9999
            icount(7) =  9999
            icount(8) = -9999
            icount(9) =  9999
            icounth(1) = 0
            icounth(2) = 0
            icounth(3) = 0
            icounth(4) = -9999
            icounth(5) =  9999
            icounth(6) = -9999
            icounth(7) =  9999
            icounth(8) = -9999
            icounth(9) =  9999

            rfact = 1.0

         do i = 1, icsu

            ischn(i) = 0

         end do

            isumtalRead = 0

         inpgi = 0   ! samepage

            stdcut = -1.0

            istbat = 0
         do i = 1, npanatal
            ist_nm(i) = 0
            jst_nm(i) = 0
         end do

         do i = 1, 6
            kmst(i) = 0
         end do

         iextstat = 0 ! S.H. extstat 2024.3.18
         prodenmn = 1d-2 ! S.H. extstat 2024.4.2
         prodenmx = 1d2
         nbproden = 100
         iprodenchk = 0

C S.H. (2020.12.21)
*-----------------------------------------------------------------------
*     warning messages
*-----------------------------------------------------------------------

         if ( mstz(59) .ge. 1 ) then
            write(*,'(''Warning: event generator mode '',
     &                ''should not be used when [t-point] is set'')')
         end if

         if ( mstz(85) .ge. 1
     &           .or. parz(142) .gt. parz(12)
     &           .or. parz(143) .gt. parz(13) ) then
            write(*,'(''Warning: electrons or positrons should not '',
     &                ''be transported when [t-point] is set,'',
     &       /''better to set negs=-1 or emin(12,13) = dmax(12,13)'')')
         end if

         if ( parz(131) .gt. parz(1) ) then
            write(*,'(''Warning: proton nuclear data library '',
     &                ''should not be used when [t-point] is set,'')')
         end if

         if ( parz(145) .gt. parz(15) ) then
            write(*,'(''Warning: deutron nuclear data library '',
     &                ''should not be used when [t-point] is set,'')')
         end if

         if ( parz(146) .gt. parz(16) ) then
            write(*,'(''Warning: triton nuclear data library '',
     &                ''should not be used when [t-point] is set,'')')
         end if

         if ( parz(147) .gt. parz(17) ) then
            write(*,'(''Warning: He-3 nuclear data library '',
     &                ''should not be used when [t-point] is set,'')')
         end if

         if ( parz(148) .gt. parz(18) ) then
            write(*,'(''Warning: alpha nuclear data library '',
     &                ''should not be used when [t-point] is set,'')')
         end if

         if ( parz(149) .gt. parz(19) ) then
            write(*,'(''Warning: heavy-ion nuclear data library '',
     &                ''should not be used when [t-point] is set,'')')
         end if

         if ( parz(203) .gt. 1d-3 ) then
            write(*,'(''Warning: photo-nuclear data library '',
     &                ''should not be used when [t-point] is set,'')')
         end if

*-----------------------------------------------------------------------
*     read one line from jsi
*-----------------------------------------------------------------------

  140 continue

            call readl(jsn,jsi,dsin,idsi,ill,ilf,'#!$',
     &                 jpn,chin,chlw,chcm,i1,i2,i3,i4,iskip,ierr)

               if( ierr .ne. 0 ) return
               if( jpn  .eq. 3 ) goto 800

               if( iskip .ne. 0 ) goto 140

  150 continue

               if( ierr .ne. 0 ) return
               if( jpn  .eq. 3 ) goto 800

*-----------------------------------------------------------------------
*        end of the section
*-----------------------------------------------------------------------

            if( chlw(i1:i1) .eq. '[' ) then

               jpn = 1
               goto 800

            end if

*-----------------------------------------------------------------------
*        identify the parameters
*-----------------------------------------------------------------------

            icl = i1

*-----------------------------------------------------------------------
