               ic = jnumc(chlw,ic,i3)
               goto 112

  111       continue

            if( mrsq .gt. 0 ) then

                  ipox = 0
                  ipoa = 0
                  ipod = 0
                  ipor = 0

               do k = 1, mrsq
                  if( irsq(k) .eq. 1 ) ipox = ipox + 1
                  if( irsq(k) .eq. 2 ) ipoa = ipoa + 1
                  if( irsq(k) .eq. 3 ) ipod = ipod + 1
                  if( irsq(k) .eq. 4 ) ipor = ipor + 1
               end do

                  if( ipox .ne. 1 .or. ipoa .ne. 1 .or.
     &                ipod .ne. 1 .or. ipor .ne. 1 ) goto 998

                  nrsq = mrsq

