                  ic2 = inumc(chlw,ic,i3,']') + 1

               else if( chlw(ic:ic) .eq. '{' ) then

                  ic2 = inumc(chlw,ic,i3,'}') + 1

               else if( chlw(ic:ic) .eq. '(' ) then

                  ic2 = knump(chlw,ic,i3) + 1

               else

                  ic2 = inumc(chlw,ic,i3,' ')

               end if

            else if( irsq(k) .eq. 1 ) then

               if( chlw(ic:ic) .eq. 'x' ) then

