                  icurrent_gmsh = 2

                  call moddas_reallocate_dbl(
     &                    itlmax, itnm, 2, itarg, das_itarg)
                  itsmn(itnm) = itsmn(itnm) + 2

                  gmsh(istag-1+1) = 0.0
                  gmsh(istag-1+2) = 360.0
                  das_itarg(itarg(itnm)-1+1) = 0.0
                  das_itarg(itarg(itnm)-1+2) = 360.0

               end if

                  itaty(itnm) = iatp
                  itanm(itnm) = ina
                  rtadl(itnm) = adel
                  rtami(itnm) = amin
                  rtama(itnm) = amax

*-----------------------------------------------------------------------
*        time mesh
*-----------------------------------------------------------------------

               if( ittp .ne. 0 ) then

                  ittty(itnm) = ittp
                  ittnm(itnm) = int
                  rttdl(itnm) = tdel
                  rttmi(itnm) = tmin
                  rttma(itnm) = tmax

                  call moddas_reallocate_dbl(
     &                    itlmax, itnm, int+1, ittrg, das_ittrg)
                  das_ittrg(ittrg(itnm):ittrg(itnm)+int)
     &                     = gmsh(isttg:isttg+int)
                  itsmn(itnm) = itsmn(itnm) + int + 1

               else

                  ittty(itnm) = ittp
                  ittnm(itnm) = 1
                  rttdl(itnm) = 0.d0
                  rttmi(itnm) = 0.d0
                  rttma(itnm) = 0.d0

                  call moddas_reallocate_dbl(
     &                    itlmax, itnm, 2, ittrg, das_ittrg)
                  itsmn(itnm) = itsmn(itnm) + 2

                  das_ittrg(ittrg(itnm)  ) = -1.d+30
                  das_ittrg(ittrg(itnm)+1) =  1.d+30

                  call moddas_reallocate_dbl(
     &                    3, icurrent_gmsh, 2, iaddress_gmsh, gmsh)
                  gmsh(iaddress_gmsh(icurrent_gmsh)  ) = -1.d+30
                  gmsh(iaddress_gmsh(icurrent_gmsh)+1) =  1.d+30
                  iaddress_gmsh(2) = iaddress_gmsh(3)
                  icurrent_gmsh = 2

               end if

*-----------------------------------------------------------------------
*        transformation
*-----------------------------------------------------------------------

                     itmtr(itnm,1) = igkst
                     itmtr(itnm,2) = ktrs
                     itmtr(itnm,3) = idtt
                     itmtr(itnm,4) = 0

               if( igkst .gt. 1 ) then

                  do k = 1, 13

                     rtmtr(itnm,k) = vtrs(k)

                  end do

               end if

*-----------------------------------------------------------------------
*        reg echo length
*-----------------------------------------------------------------------

                  iterl(itnm) = iechrl

*-----------------------------------------------------------------------
*        unit
*-----------------------------------------------------------------------

                  itunt(itnm) = iunt

*-----------------------------------------------------------------------
*        2d-type
*-----------------------------------------------------------------------

                  ittwo(itnm) = idtyp

*-----------------------------------------------------------------------
*        factor
*-----------------------------------------------------------------------

                  rtfac(itnm) = rfact

*-----------------------------------------------------------------------
*        volmat  ( unit = 4 -> vol = 1.0 then volmat = 0 )
*-----------------------------------------------------------------------

                  itvm(itnm) = matvol

                  if( iunt .eq. 4 .or. iunt .eq. 14 ) itvm(itnm) = 0

*-----------------------------------------------------------------------
*        epsout
*-----------------------------------------------------------------------

                  iteps(itnm) = ieps

*-----------------------------------------------------------------------
*        bmpout
*-----------------------------------------------------------------------

                  itbmp(itnm) = ibmp

*-----------------------------------------------------------------------
*        vtkout
*-----------------------------------------------------------------------

                  itvtk(itnm) = ivtk

*-----------------------------------------------------------------------
*        vtkfmt
*-----------------------------------------------------------------------

                  itvtkfmt(itnm) = ivtkfmt

*-----------------------------------------------------------------------
*        resolution
*-----------------------------------------------------------------------

                  itres(itnm) = max( 1, ireso )

*-----------------------------------------------------------------------
*        width
*-----------------------------------------------------------------------

                  rtwid(itnm) = width

*-----------------------------------------------------------------------
*        counter
*-----------------------------------------------------------------------

               do i = 1, 9

                  itcnt(i,itnm) = icount(i)
                  itcnth(i,itnm) = icounth(i) !frtati 2021/03/05

               end do

*-----------------------------------------------------------------------
*        axis
*-----------------------------------------------------------------------

                  itaxn(itnm) = inaxi

               do i = 1, inaxi

                  itaxs(itnm,i) = iaxis(i)

               end do

*-----------------------------------------------------------------------
*        infog
*-----------------------------------------------------------------------

                  itger(itnm) = infog

*-----------------------------------------------------------------------
*        stdcut
*-----------------------------------------------------------------------
                  rtstd(itnm) = stdcut

*-----------------------------------------------------------------------
*        foamout
*-----------------------------------------------------------------------
                  itfoam(itnm) = ifoam

*-----------------------------------------------------------------------
*        maxangel
*-----------------------------------------------------------------------
                  itmxang(itnm) = imxang

*-----------------------------------------------------------------------
*        samepage
*-----------------------------------------------------------------------
                  itpgn(itnm) = inpgi

               do i = 1, inpgi

                  itpgs(itnm,i) = ipgis(i)

               end do

c S.H. extstat 2024.4.2
*-----------------------------------------------------------------------
*        prodenmn, prodenmx, nbproden for probability density function
*-----------------------------------------------------------------------

               tprodenmn(itnm) = prodenmn
               tprodenmx(itnm) = prodenmx
               nbtproden(itnm) = nbproden
               itprodenchk(itnm) = iprodenchk
c S.H. extstat 2024.4.2

c S.H. extstat 2024.3.18
*-----------------------------------------------------------------------
*        iextstat
*-----------------------------------------------------------------------

               itextstat(itnm) = iextstat
               if ( iextstat .eq. 0 ) then
                  mftal(itnm) = 2
               else if ( iextstat .eq. 1 ) then
                  mftal(itnm) = 5
               else if ( iextstat .eq. 2 ) then
                  mftal(itnm) = 8 + nbtproden(itnm)
               else
                  mftal(itnm) = 2
               end if
c S.H. extstat 2024.3.18

*-----------------------------------------------------------------------
*        file
*-----------------------------------------------------------------------

                  itfln(itnm) = infil

               do i = 1, infil

                  itfll(itnm,i) = lfile(i)

                  ctfln(itnm,i)(1:lfile(i)) = ifile(i)(1:lfile(i))

                  do k = lfile(i) + 1, 100

                     ctfln(itnm,i)(k:k) = ' '

                  end do

               end do

*-----------------------------------------------------------------------
*       restart file
*-----------------------------------------------------------------------
               call summary_param_resfile(itnm,irfflg,lrfile,irfile)

*-----------------------------------------------------------------------
*        multiplier
*-----------------------------------------------------------------------

                  itmlp(itnm) = jmul
                  ijmul = 1

         if( jmul .gt. 0 ) then

                  ijmul = jmul

                  itmst(itnm) = kmst(1)

                  do j = 1, kmst(1)

                     itmnt(itnm,j) = kimst(1,j)

                  end do

            do k = 1, jmul

                  if( kmst(k) .ne. kmst(1) ) goto 969

                  do j = 1, kmst(1)

                     if( kimst(k,j) .ne. itmnt(itnm,j) ) goto 968

                  end do

                  itmln(itnm,k) = ktln(k)
                  itmli(itnm,k) = ktli(k)
                  rtmme(itnm,k) = dkmax(k)
                  itmpn(itnm,k) = knpat(k)

               do j = 1, knpat(k)

                  itmpt(itnm,k,j,1) = kptyp(k,j)
                  itmpt(itnm,k,j,2) = kpnkf(k,j)

               end do

                  ltli = 13 * ktln(k)

                  itsmn(itnm) = itsmn(itnm)
     &                        + ( ltli + mod(ltli,2) ) / 2
     &                        + ktls(k)

                  itmto(itnm,k,:) = imtinf(:) ! frtati 2023/12/07

            end do

         end if

*-----------------------------------------------------------------------
*     summary for anatally
*-----------------------------------------------------------------------

         if ( mstz(26) .ne. 3 ) istbat = 0 ! S.H. 2021.8.31
         if( istbat .eq. 0 ) then

                  itism(itnm) = istbat

         else if( istbat .gt. 0 ) then

            if( imesh .eq. 1 ) then
               if( ist_nm(1) .gt. 1 ) then
                  if( ist_nm(1) .gt. ntrn ) goto 967
               else if( ist_nm(1) .le. 0 ) then
                     ist_nm(1) = ntrn
                  do j = 1, ntrn
                     isd_nm(1,j) = j
                  end do
               end if
                     ist_nm(2) = 1
                     isd_nm(2,1) = 1
                     ist_nm(3) = 1
                     isd_nm(3,1) = 1
                     ist_nm(4) = 1
                     isd_nm(4,1) = 1
                     ist_nm(5) = 1
                     isd_nm(5,1) = 1
            else if( imesh .eq. 2 ) then
               if( ist_nm(4) .gt. 1 ) then
                  if( ist_nm(1) .gt. inz ) goto 967
               else if( ist_nm(4) .le. 0 ) then
                     ist_nm(4) = inz
                  do j = 1, inz
                     isd_nm(4,j) = j
                  end do
               end if
               if( ist_nm(5) .gt. 1 ) then
                  if( ist_nm(5) .gt. inr ) goto 967
               else if( ist_nm(5) .le. 0 ) then
                     ist_nm(5) = inr
                  do j = 1, inz
                     isd_nm(5,j) = j
                  end do
               end if
                     ist_nm(1) = 1
                     isd_nm(1,1) = 1
                     ist_nm(2) = 1
                     isd_nm(2,1) = 1
                     ist_nm(3) = 1
                     isd_nm(3,1) = 1
            else if( imesh .eq. 3 ) then
               if( ist_nm(2) .gt. 1 ) then
                  if( ist_nm(2) .gt. inx ) goto 967
               else if( ist_nm(2) .le. 0 ) then
                     ist_nm(2) = inx
                  do j = 1, inx
                     isd_nm(2,j) = j
                  end do
               end if
               if( ist_nm(3) .gt. 1 ) then
                  if( ist_nm(3) .gt. iny ) goto 967
               else if( ist_nm(3) .le. 0 ) then
                     ist_nm(3) = iny
                  do j = 1, iny
                     isd_nm(3,j) = j
                  end do
               end if
               if( ist_nm(4) .gt. 1 ) then
                  if( ist_nm(4) .gt. inz ) goto 967
               else if( ist_nm(4) .le. 0 ) then
                     ist_nm(4) = inz
                  do j = 1, inz
                     isd_nm(4,j) = j
                  end do
               end if
                     ist_nm(1) = 1
                     isd_nm(1,1) = 1
                     ist_nm(5) = 1
                     isd_nm(5,1) = 1
            end if

*-----------------------------------------------------------------------

               if( ist_nm(6) .gt. 1 ) then
                  if( ist_nm(6) .gt. ine ) goto 967
               else if( ist_nm(6) .le. 0 ) then
                     ist_nm(6) = ine
                  do j = 1, ine
                     isd_nm(6,j) = j
                  end do
               end if

               if( ist_nm(7) .gt. 1 ) then
                  if( ist_nm(7) .gt. ittnm(itnm) ) goto 967
               else if( ist_nm(7) .le. 0 ) then
                     ist_nm(7) = ittnm(itnm)
                  do j = 1, ittnm(itnm)
                     isd_nm(7,j) = j
                  end do
               end if

               if( ist_nm(8) .gt. 1 ) then
                  if( ist_nm(8) .gt. ina ) goto 967
               else if( ist_nm(8) .le. 0 ) then
                     ist_nm(8) = ina
                  do j = 1, ina
                     isd_nm(8,j) = j
                  end do
               end if

               if( ist_nm(9) .gt. 1 ) then
                  if( ist_nm(9) .gt. itpan(itnm) ) goto 967
               else if( ist_nm(9) .le. 0 ) then
                     ist_nm(9) = itpan(itnm)
                  do j = 1, itpan(itnm)
                     isd_nm(9,j) = j
                  end do
               end if

               if( ist_nm(10) .gt. 1 ) then
                  if( ist_nm(10) .gt. kmst(1) ) goto 967
               else if( ist_nm(10) .le. 0 ) then
                     if( kmst(1) .le. 0 ) then
                        ist_nm(10) = 1
                     else
                        ist_nm(10) = kmst(1)
                     end if
                  do j = 1, ist_nm(10)
                     isd_nm(10,j) = j
                  end do
               end if

*-----------------------------------------------------------------------

                iall = 1
            do i = 1, 10
                iall = iall * ist_nm(i)
            end do

                istbat = iall

            if( istbat .gt. kvlmax ) goto 966

*-----------------------------------------------------------------------

                jst_nm(1)  = 1
                jst_nm(2)  = jst_nm(1) + ist_nm(1)
                jst_nm(3)  = jst_nm(2) + ist_nm(2)
                jst_nm(4)  = jst_nm(3) + ist_nm(3)
                jst_nm(5)  = jst_nm(4) + ist_nm(4)
                jst_nm(6)  = jst_nm(5) + ist_nm(5)
                jst_nm(7)  = jst_nm(6) + ist_nm(6)
                jst_nm(8)  = jst_nm(7) + ist_nm(7)
                jst_nm(9)  = jst_nm(8) + ist_nm(8)
                jst_nm(10) = jst_nm(9) + ist_nm(9)
                jst_al     = jst_nm(10) + ist_nm(10)

*-----------------------------------------------------------------------

                  istbmm = ( mmmax - 1 ) * 2 + 1
                  mmmax = mmmax + ( jst_al + mod(jst_al,2) ) / 2 + 2
                  if( mmmax .gt. mdas ) goto 950

                  itstt(itnm) = istbmm
                  itsmn(itnm) = itsmn(itnm)
     &                        + ( jst_al + mod(jst_al,2) ) / 2

                  itism(itnm) = istbat

            do i = 1, 10
                  itist(i,itnm) = ist_nm(i)
                  itjst(i,itnm) = jst_nm(i)
                  itkst(i,itnm) = kst_nm(i)
            end do

            do i = 1, 10
               do k = 1, itist(i,itnm)
                  idas( itstt(itnm) + itjst(i,itnm) + k ) = isd_nm(i,k)
               end do
            end do

         end if

*-----------------------------------------------------------------------

      return

*-----------------------------------------------------------------------
*     errors
*-----------------------------------------------------------------------

  950    write(dkam,'(i9)') mdas
         m_err = 'Total tally storage number exceeds mdas ='//dkam
         ErrCha = ''
         ErrID = 'L:18104/R:ttrack/F:tallsm2.f'
         goto 999

  966    m_err = 'total # of points exceeds kvlmax in anatally.'//tname
         ErrCha = ''
         ErrID = 'L:18109/R:ttrack/F:tallsm2.f'
         goto 999

  967    m_err = 'something wrong in anatally parameters.'//tname
         ErrCha = ''
         ErrID = 'L:18114/R:ttrack/F:tallsm2.f'
         goto 999

  968    m_err = 'mset number is inconsistent.'//tname
         ErrCha = ''
         ErrID = 'L:18119/R:ttrack/F:tallsm2.f'
         goto 999

  969    m_err = 'number of mset should be the same.'//tname
         ErrCha = ''
         ErrID = 'L:18124/R:ttrack/F:tallsm2.f'
         goto 999

  970    m_err = 'def of multiplier should be less than 7 '//tname
         ErrCha = ''
         ErrID = 'L:18129/R:ttrack/F:tallsm2.f'
         goto 999

  971    m_err = 'number of multiplier is negative'//tname
         ErrCha = ''
         ErrID = 'L:18134/R:ttrack/F:tallsm2.f'
         goto 999

  978    m_err = 'counter should be from -9999 to 9999'
         ErrCha = ''
         ErrID = 'L:18139/R:ttrack/F:tallsm2.f'
         goto 999

  979    m_err = 'Description of material parameter is wrong in tally '
     &            //tname
         ErrCha = ''
         ErrID = 'L:18145/R:ttrack/F:tallsm2.f'
         goto 999

  983    m_err = '2D-type should be 1-7 in tally '//tname
         ErrCha = ''
         ErrID = 'L:18150/R:ttrack/F:tallsm2.f'
         goto 999

  985    m_err = 'Unit is Lethargy but energy mesh points are negative'
         ErrCha = ''
         ErrID = 'L:18155/R:ttrack/F:tallsm2.f'
         goto 999

  986    write(dkam,'(i5)') itlmax
         m_err = 'Total tally number exceeds itlmax = '//dkam
         ErrCha = ''
         ErrID = 'L:18161/R:ttrack/F:tallsm2.f'
         goto 999

  987    m_err = 'Unknown parameter in tally '//tname
         ErrCha = ''
         ErrID = 'L:18166/R:ttrack/F:tallsm2.f'
         goto 999

  988    m_err = 'Unit should be 1,2,3,4,11,12,13,14 in tally '//tname
         ErrCha = ''
         ErrID = 'L:18171/R:ttrack/F:tallsm2.f'
         goto 999

  989    m_err = 'Double definition of the parameter in tally '//tname
         ErrCha = ''
         ErrID = 'L:18176/R:ttrack/F:tallsm2.f'
         goto 999

  990    m_err = 'Too many file name in tally '//tname
         ErrCha = ''
         ErrID = 'L:18181/R:ttrack/F:tallsm2.f'
         goto 999

  991    m_err = 'Too many axis in tally '//tname
         ErrCha = ''
         ErrID = 'L:18186/R:ttrack/F:tallsm2.f'
         goto 999

  992    m_err = 'Unknown axis name in tally '//tname
         ErrCha = ''
         ErrID = 'L:18191/R:ttrack/F:tallsm2.f'
         goto 999

  993    m_err = 'In this line, [ ; ] cannot be used.'
         ErrCha = ''
         ErrID = 'L:18196/R:ttrack/F:tallsm2.f'
         goto 999

  994    m_err = 'Name of particle is wrong in tally '//tname
         ErrCha = ''
         ErrID = 'L:18201/R:ttrack/F:tallsm2.f'
         goto 999

cfrtati 2021/10/05 6 -> mxpart
  995    m_err = 'Number of particles is larger than mxpart in '//tname
         ErrCha = ''
         ErrID = 'L:18207/R:ttrack/F:tallsm2.f'
         goto 999

  996    m_err = 'Description of mesh is wrong in tally '//tname
         ErrCha = ''
         ErrID = 'L:18212/R:ttrack/F:tallsm2.f'
         goto 999

  997    m_err = 'Description of parameter is wrong in tally '//tname
         ErrCha = ''
         ErrID = 'L:18217/R:ttrack/F:tallsm2.f'
         goto 999

  998    m_err = 'Unknown mesh parameter in tally '//tname
         ErrCha = ''
         ErrID = 'L:18222/R:ttrack/F:tallsm2.f'
         goto 999

 1045    m_err = 'Too many samepage in tally '//tname
         ErrCha = ''
         ErrID = 'L:18227/R:ttrack/F:tallsm2.f'
         goto 999

 1046    m_err = 'samepage should be wwg, reg,eng,t,xy,yz,zx,x,y,z'
     &           //' in tally '//tname
         ErrCha = ''
         ErrID = 'L:18233/R:ttrack/F:tallsm2.f'
         goto 999

*-----------------------------------------------------------------------

  999 continue

         l_err = ill(jsn)
         k_err = jsn
         ierr  = 1

*-----------------------------------------------------------------------

      return
      end


************************************************************************
*                                                                      *
      subroutine tadjnt(jsn,jsi,dsin,idsi,ill,ilf,
     &                  jpn,chin,chlw,chcm,i1,i2,i3,i4,ierr)
*                                                                      *
*       read [t-adjoint] section of input files                        *
*       modified by K.Niita on 2016/01/22                              *
*                                                                      *
************************************************************************
      use sangelmod, only: itsanf
      use partmod ! frtati 2021/10/05
      use moddas
      use moddas_mesh
      use moddas_region
      use moddas_tally

      implicit real*8 (a-h,o-z)

      include 'param.inc'
      include 'param01.inc'
      include 'err.inc'

*-----------------------------------------------------------------------

      common /tall00/ itnm, ital(itlmax), itals(itlmax), italm(itlmax)
      common /tall01/ itmsh(itlmax), itunt(itlmax), itspc(itlmax),
     &                itout(itlmax), ittwo(itlmax)

      common /tall02/ itrgn(itlmax), itrgm(itlmax), itreg(itlmax)
      common /tall25/ itrnv(itlmax), itriv(itlmax), itrrv(itlmax)

      common /tall03/ itrty(itlmax), itrnm(itlmax), itrrg(itlmax),
     &                rtrmi(itlmax), rtrma(itlmax), rtrdl(itlmax)
      common /tall04/ itxty(itlmax), itxnm(itlmax), itxrg(itlmax),
     &                rtxmi(itlmax), rtxma(itlmax), rtxdl(itlmax)
      common /tall05/ ityty(itlmax), itynm(itlmax), ityrg(itlmax),
     &                rtymi(itlmax), rtyma(itlmax), rtydl(itlmax)
      common /tall06/ itzty(itlmax), itznm(itlmax), itzrg(itlmax),
     &                rtzmi(itlmax), rtzma(itlmax), rtzdl(itlmax)
      common /tall07/ itety(itlmax), itenm(itlmax), iterg(itlmax),
     &                rtemi(itlmax), rtema(itlmax), rtedl(itlmax)

      common /tall08/ rtrx0(itlmax), rtry0(itlmax)

      common /tall10/ itaxn(itlmax), itaxs(itlmax,6)
      common /tall11/ itfln(itlmax), itfll(itlmax,6), ctfln(itlmax,6)
      character ctfln*100

      common /tall14/ ittll(itlmax), ittle(itlmax)
      character ittle*80

      common /tall15/ itanl(itlmax), itang(itlmax)
      character itang*200

      common /tall27/ itaxl(itlmax), itaxt(itlmax),
     &                itayl(itlmax), itayt(itlmax),
     &                itazl(itlmax), itazt(itlmax)
      character itaxt*200, itayt*200, itazt*200

      common /tall19/ itsmn(itlmax), itstm(itlmax)

      common /tall20/ ittty(itlmax), ittnm(itlmax), ittrg(itlmax),
     &                rttmi(itlmax), rttma(itlmax), rttdl(itlmax)
      common /tall21/ rtfac(itlmax)
      common /tall22/ itmcn(itlmax), itmtn(itlmax), itmtt(itlmax)

      common /tall23/ itaty(itlmax), itanm(itlmax), itarg(itlmax),
     &                rtami(itlmax), rtama(itlmax), rtadl(itlmax)

      common /tall28/ itgsh(itlmax)
      common /tall29/ itrsh(itlmax)
      common /tall31/ iterl(itlmax)
      common /tall34/ itvm(itlmax)
      common /tall35/ iteps(itlmax)
      common /tall37/ itcnt(9,itlmax)

      common /tall38/ itres(itlmax)
      common /tall39/ rtwid(itlmax)

      common /tall45/ itmlp(itlmax), itmln(itlmax,6), itmst(itlmax),
     &                itmli(itlmax,6), rtmme(itlmax,6), itmnt(itlmax,6),
     &                itmpn(itlmax,6), itmpt(itlmax,6,6,2)
      common /tall46/ itmtr(itlmax,4), rtmtr(itlmax,13)

      common /tall49/ itglt(itlmax)

!OBINATA: for resfile
      common /tall59/ irfll(itlmax), crfln(itlmax), itrff(itlmax)
      character crfln*100
      character irfile*100

      common /tall60/ itger(itlmax)

      common /tall66/ itadm(itlmax), rtade(itlmax), rtadw(itlmax)

      common /tall67/ itstd(itlmax), rtstd(itlmax)

      common /tall82/ itcnth(9,itlmax)
      dimension icounth(9)
cfrtati 2023/12/07
      common /tall84/ itmto(itlmax,6,4)

      dimension idas(1)
      equivalence ( das, idas )


*-----------------------------------------------------------------------

      character m_err*200
      common /error/ m_err, l_err, k_err

*-----------------------------------------------------------------------

      character title*80
      character angelp*200
      character cxtxt*200
      character cytxt*200
      character cztxt*200

*-----------------------------------------------------------------------

      dimension lschn(46), ischn(46)
      character schan(46)*8

      data icsu / 46 /

      data ( schan(i), i = 1, 46 ) /
     &    'mesh    ','part    ','e-type  ','unit    ','axis    ',
     &    'file    ','title   ','angel   ','2d-type ','factor  ',
     &    'x-txt   ','y-txt   ','z-txt   ','gshow   ','rshow   ',
     &    'iechrl  ','material','volmat  ','epsout  ','ctmin(1)',
     &    'ctmax(1)','ctmin(2)','ctmax(2)','ctmin(3)','ctmax(3)',
     &    'resol   ','width   ','multipli','t-type  ','trcl    ',
     &    '*trcl   ','gslat   ','resfile ','ginfo   ','a-type  ',
     &    'e-smin  ','e-smax  ','m-source','stdcut  ','sangel  ',
     &    'chmin(1)','chmax(1)','chmin(2)','chmax(2)','chmin(3)',
     &    'chmax(3)'/

      data ( lschn(i), i = 1, 46 ) /
     &     4,         4,         6,         4,         4,
     &     4,         5,         5,         7,         6,
     &     5,         5,         5,         5,         5,
     &     6,         8,         6,         6,         8,
     &     8,         8,         8,         8,         8,
     &     5,         5,         8,         6,         4,
     &     5,         5,         7,         5,         6,
     &     6,         6,         8,         6,         6,
     &     8,         8,         8,         8,         8,
     &     8/

*-----------------------------------------------------------------------

cfrtati 2021/10/05 6 -> mxpart
      dimension iptyp(mxpart), ipnkf(mxpart)
      dimension imtyp(mxpart,mxpart), imnkf(mxpart,mxpart)
      dimension jstyp(mxpart), jnkf0(mxpart)
      dimension icount(9)

      dimension iaxis(6)
      character ifile(6)*100
      dimension lfile(6)


*-----------------------------------------------------------------------

      character chin*200, chlw*200, chcm*200
      character chlc*200

      character dsin(0:9)*200
      dimension idsi(0:9)

      dimension ill(0:9), ilf(0:9)

      character dkam*9

      character tname*11
      data      tname /'[t-adjoint]'/

      logical deqn4

      integer isumtalRead

*-----------------------------------------------------------------------

      dimension jptyp(6), jpnkf(6)
      dimension kptyp(6,6), kpnkf(6,6)
      dimension ktln(6), ktli(6), ktls(6), kmst(6), knpat(6)
      dimension dkmax(6)
      dimension imst(6), kimst(6,6)
      dimension vtrs(13)
      dimension imtinf(4) ! frtati 2023/12/07

*-----------------------------------------------------------------------

            ierr  = 0

            iunt  = 1
            imate = 0
            jmate = 1
            inpat = 0
            inaxi = 0
            infil = 0
            idtyp = 3
            jmul  = 0

            langel = 0
            itsanf = 0
            lxtxt  = 0
            lytxt  = 0
            lztxt  = 0
            lgshow = 0
            lrshow = 0
            iechrl = 72
            matvol = 9
            ieps   = 0
            ittp   = 0
            igkst  = 0
            idtt   = 0
            ktrs   = 0
            igslt  = -1
            lrfile = 0 !OBINATA
            irfflg = 0 !OBINATA

            iatp   = 0
            jatp   = 0

            amin = 0.0
            amax = 0.0
            adel = 0.0

            icount(1) = 0
            icount(2) = 0
            icount(3) = 0
            icount(4) = -9999
            icount(5) =  9999
            icount(6) = -9999
            icount(7) =  9999
            icount(8) = -9999
            icount(9) =  9999
            icounth(1) = 0
            icounth(2) = 0
            icounth(3) = 0
            icounth(4) = -9999
            icounth(5) =  9999
            icounth(6) = -9999
            icounth(7) =  9999
            icounth(8) = -9999
            icounth(9) =  9999

            rfact = 1.0

            ireso = 1
            width = 0.5

         do i = 1, icsu

            ischn(i) = 0

         end do

            infog = 0

       isumtalRead = 0

            esmin = 0.58
            esmax = 0.62
            msors = 1

            stdcut = -1.0

*-----------------------------------------------------------------------
*     read one line from jsi
*-----------------------------------------------------------------------

  140 continue

            call readl(jsn,jsi,dsin,idsi,ill,ilf,'#!$',
     &                 jpn,chin,chlw,chcm,i1,i2,i3,i4,iskip,ierr)

               if( ierr .ne. 0 ) return
               if( jpn  .eq. 3 ) goto 800

               if( iskip .ne. 0 ) goto 140

  150 continue

               if( ierr .ne. 0 ) return
               if( jpn  .eq. 3 ) goto 800

*-----------------------------------------------------------------------
*        end of the section
*-----------------------------------------------------------------------

            if( chlw(i1:i1) .eq. '[' ) then

               jpn = 1
               goto 800

            end if

*-----------------------------------------------------------------------
*        identify the parameters
*-----------------------------------------------------------------------

            icl = i1

!-----------------------------------------------------------------------
!        sumtally sub section
!-----------------------------------------------------------------------
      if ( chlw .eq. 'sumtally start' ) then
       isumtalRead = 1
       call read_sumtal(jsn,jsi,dsin,idsi,ill,ilf,
     &                 jpn,chin,chlw,chcm,i1,i2,i3,i4,iskip,ierr)
       go to 140
      end if
!-----------------------------------------------------------------------

  200    continue

            chlc = chlw
            call chcomp(chlc,icl,i3,i5)

         do i = 1, icsu

            il = icl + lschn(i) - 1

            if( chlc(icl:il) .eq. schan(i)(1:lschn(i)) ) goto 100

         end do

               goto 987

*-----------------------------------------------------------------------
*        read value of parameters
*-----------------------------------------------------------------------

  100    continue

               ipm = i

               ischn( ipm ) = ischn( ipm ) + 1

            if( ipm .ne.  5 .and. ipm .ne. 6 .and.
     &          ipm .ne.  2 .and. ipm .ne. 28 .and.
     &          ipm .ne. 33 .and.
     &          ischn( ipm ) .gt. 1 ) goto 989

               ic = inumc(chlw,il+1,i3,'=') + 1
               ic = jnumc(chlw,ic,i3)

               if( ic .gt. i3 ) goto 997

               icl = inumc(chlw,ic,i3,';') - 1

*-----------------------------------------------------------------------
*        mesh = region, r-z, or xyz
*-----------------------------------------------------------------------

         if( ipm .eq. 1 ) then

            if( chlw(ic:ic+2) .eq. 'reg' ) then

               imesh = 1

            else if( chlw(ic:ic+2) .eq. 'r-z' ) then

               imesh = 2

            else if( chlw(ic:ic+2) .eq. 'xyz' ) then

               imesh = 3

            else

               goto 998

            end if

            if( chlw(icl+1:icl+1) .eq. ';' ) goto 993

            if( imesh .eq. 1 ) then

               call moddas_allocate_int(
     &                 MAX_NUM_ITREG, idas_itreg_temporary)

               ndsm = 1
               call tregion(1,jsn,jsi,dsin,idsi,ill,ilf,
     &                      jpn,chin,chlw,chcm,i1,i2,i3,i4,ierr,
     &                      ntrn,mtrn,ndsm,nvol,ivl,irvl,0
     &                      ,MAX_NUM_ITREG,idas_itreg_temporary)

               if( mtrn > MAX_NUM_ITREG ) then
                  write(ErrCha,'(a,a,i5,a,a,i5,a)')
     &                 'sub.tadjnt@tallsm2.f'
     &                    //' ?dimension over idas_itreg_temporary?'
     &                    //' mtrn > MAX_NUM_ITREG'
     &                 ,' (mtrn=',mtrn,')'
     &                 ,' (MAX_NUM_ITREG@moddas.f=',MAX_NUM_ITREG,')'
                  ErrID = 'L:18648/R:tadjnt/F:tallsm2.f'
                  call ErrWrite(ErrID,ErrCha)
               endif

                  if( ierr .ne. 0 ) return
                  if( jpn  .eq. 3 ) goto 800
                  if( ntrn .lt. -1 ) goto 996

            else if( imesh .eq. 2 ) then

               call trzmesh(jsn,jsi,dsin,idsi,ill,ilf,
     &                      jpn,chin,chlw,chcm,i1,i2,i3,i4,ierr,
     &                      rzx0,rzy0,
     &                      irtp,inr,rmin,rmax,rdel,istrg,
     &                      iztp,inz,zmin,zmax,zdel,istzg)

                  if( ierr .ne. 0 ) return
                  if( jpn  .eq. 3 ) goto 800
                  if( irtp .lt. 0 ) goto 996
                  if( iztp .lt. 0 ) goto 996

            else if( imesh .eq. 3 ) then

               call txymesh(jsn,jsi,dsin,idsi,ill,ilf,
     &                      jpn,chin,chlw,chcm,i1,i2,i3,i4,ierr,
     &                      ixtp,inx,xmin,xmax,xdel,istxg,
     &                      iytp,iny,ymin,ymax,ydel,istyg,
     &                      iztp,inz,zmin,zmax,zdel,istzg)

                  if( ierr .ne. 0 ) return
                  if( jpn  .eq. 3 ) goto 800
                  if( ixtp .lt. 0 ) goto 996
                  if( iytp .lt. 0 ) goto 996
                  if( iztp .lt. 0 ) goto 996

            end if

                  goto 150

*-----------------------------------------------------------------------
*        particle name
*-----------------------------------------------------------------------

         else if( ipm .eq. 2 ) then

                  goto 967

*-----------------------------------------------------------------------
*        material
*-----------------------------------------------------------------------

         else if( ipm .eq. 17 ) then

            if( chlw(ic:ic+2) .eq. 'all' ) then

                  imate = 0

            else if( deqn4( chlw(ic:ic) ) ) then

               call onum(chlw,ic,icl,cvvv,ierr)

               if( ierr .ne. 0 ) goto 979

                  imate = nint( cvvv )

               if( imate .lt. 0 ) then

                  imate = -imate
                  jmate = -1

               end if

               if( imate .eq. 0 ) goto 979

                  nsmte = itmtt(itnm+1)
                  call moddas_reallocate_int(
     &                    itlmax, itnm+1, imate, itmtt, ismte)
                  if( mmmax .gt. mdas ) goto 950

  151                call readl(jsn,jsi,dsin,idsi,ill,ilf,'#!$',
     &                    jpn,chin,chlw,chcm,i1,i2,i3,i4,iskip,ierr)

                        if( ierr .ne. 0 ) return
                        if( jpn  .eq. 3 ) goto 979

                        if( iskip .ne. 0 ) goto 151

                  ic = i1

               do k = 1, imate

                  if( ic .gt. i3 ) then

  152                call readl(jsn,jsi,dsin,idsi,ill,ilf,'#!$',
     &                    jpn,chin,chlw,chcm,i1,i2,i3,i4,iskip,ierr)

                     if( ierr .ne. 0 ) return
                     if( jpn  .eq. 3 ) goto 979

                     if( iskip .ne. 0 ) goto 152

                     ic = i1

                  end if

                     ic = jnumc(chlw,ic,i3)

                     call snum(chlw,ic,i3,ic2,cvvv,ierr)

                     if( ierr .ne. 0 ) goto 979

                     matei = nint( cvvv )

                     ic = ic2

                     ismte(nsmte-1+k) = matei

               end do

            else

               goto 979

            end if

*-----------------------------------------------------------------------
*        energy mesh
*-----------------------------------------------------------------------

         else if( ipm .eq. 3 ) then

               call onum(chlw,ic,icl,cvvv,ierr)

               if( ierr .ne. 0 ) goto 997

               if( chlw(icl+1:icl+1) .eq. ';' ) goto 993

               ietp = nint( cvvv )

               call getmsh(jsn,jsi,dsin,idsi,ill,ilf,
     &                     jpn,chin,chlw,chcm,i1,i2,i3,i4,ierr,
     &                     'e',ietp,ine,emin,emax,edel,isteg)

               if( ierr .ne. 0 ) return

               goto 150

*-----------------------------------------------------------------------
*        time mesh
*-----------------------------------------------------------------------

         else if( ipm .eq. 29 ) then

               call onum(chlw,ic,icl,cvvv,ierr)

               if( ierr .ne. 0 ) goto 997

               if( chlw(icl+1:icl+1) .eq. ';' ) goto 993

               ittp = nint( cvvv )

               call getmsh(jsn,jsi,dsin,idsi,ill,ilf,
     &                     jpn,chin,chlw,chcm,i1,i2,i3,i4,ierr,
     &                     't',ittp,int,tmin,tmax,tdel,isttg)

               if( ierr .ne. 0 ) return

               goto 150

*-----------------------------------------------------------------------
*        angle mesh
*-----------------------------------------------------------------------

         else if( ipm .eq. 35 ) then

               call onum(chlw,ic,icl,cvvv,ierr)

               if( ierr .ne. 0 ) goto 997

               if( chlw(icl+1:icl+1) .eq. ';' ) goto 993

               iatp = nint( cvvv )
               jatp = abs( iatp )

               call getmsh(jsn,jsi,dsin,idsi,ill,ilf,
     &                     jpn,chin,chlw,chcm,i1,i2,i3,i4,ierr,
     &                     'a',jatp,ina,amin,amax,adel,istag)

               if( ierr .ne. 0 ) return

               goto 150

*-----------------------------------------------------------------------
*        transform
*-----------------------------------------------------------------------

         else if( ipm .eq. 30 .or. ipm .eq. 31 ) then

                  if( ipm .eq. 31 ) ktrs = 1

               call ttrans(jsn,jsi,dsin,idsi,ill,ilf,
     &                     jpn,chin,chlw,chcm,i1,i2,i3,i4,ierr,
     &                     ic,ktrs,igkst,idtt,vtrs)

               if( ierr .ne. 0 ) return

               goto 150

*-----------------------------------------------------------------------
*        unit
*-----------------------------------------------------------------------

         else if( ipm .eq. 4 ) then

               call onum(chlw,ic,icl,cvvv,ierr)

               if( ierr .ne. 0 ) goto 997

               iunt = nint( cvvv )

               if( iunt .lt. 1 .or.
     &           ( iunt .gt. 5 .and. iunt .lt. 11 ) .or.
     &             iunt .gt. 14 ) goto 988

               icl = jnumc(chlw,icl+2,i3)

               if( icl .le. i3 ) goto 200

*-----------------------------------------------------------------------
*        axis
*-----------------------------------------------------------------------

         else if( ipm .eq. 5 ) then

  600       inaxi = inaxi + 1

            if( inaxi .gt. 6 ) goto 991

            if( chlw(ic:ic+2) .eq. 'eng' ) then

               iaxis(inaxi) = 1
               ic =jnumc(chlw,ic+4,icl)

            else if( chlw(ic:ic+2) .eq. 'reg' ) then

               iaxis(inaxi) = 2
               ic =jnumc(chlw,ic+4,icl)

            else if( chlw(ic:ic+2) .eq. 'rad' ) then

               iaxis(inaxi) = 12
               ic =jnumc(chlw,ic+4,icl)

            else if( chlw(ic:ic+2) .eq. 'deg' ) then

               iaxis(inaxi) = 13
               ic =jnumc(chlw,ic+4,icl)

            else if( chlw(ic:ic+1) .eq. 'xy' .or.
     &               chlw(ic:ic+1) .eq. 'yx' ) then

               iaxis(inaxi) = 7
               ic =jnumc(chlw,ic+3,icl)

            else if( chlw(ic:ic+1) .eq. 'yz' .or.
     &               chlw(ic:ic+1) .eq. 'zy' ) then

               iaxis(inaxi) = 8
               ic =jnumc(chlw,ic+3,icl)

            else if( chlw(ic:ic+1) .eq. 'zx' .or.
     &               chlw(ic:ic+1) .eq. 'xz' ) then

               iaxis(inaxi) = 9
               ic =jnumc(chlw,ic+3,icl)

            else if( chlw(ic:ic+1) .eq. 'rz' .or.
     &               chlw(ic:ic+1) .eq. 'zr' ) then

               iaxis(inaxi) = 10
               ic =jnumc(chlw,ic+3,icl)

            else if( chlw(ic:ic) .eq. 'x' ) then

               iaxis(inaxi) = 3
               ic =jnumc(chlw,ic+2,icl)

            else if( chlw(ic:ic) .eq. 'y' ) then

               iaxis(inaxi) = 4
               ic =jnumc(chlw,ic+2,icl)

            else if( chlw(ic:ic) .eq. 'z' ) then

               iaxis(inaxi) = 5
               ic =jnumc(chlw,ic+2,icl)

            else if( chlw(ic:ic) .eq. 'r' ) then

               iaxis(inaxi) = 6
               ic =jnumc(chlw,ic+2,icl)

            else if( chlw(ic:ic) .eq. 't' ) then

               iaxis(inaxi) = 11
               ic =jnumc(chlw,ic+2,icl)

            else

               goto 992

            end if

               if( ic .le. icl ) goto 600

               icl = jnumc(chlw,icl+2,i3)

               if( icl .le. i3 ) goto 200

*-----------------------------------------------------------------------
*        file name
*-----------------------------------------------------------------------

         else if( ipm .eq. 6 ) then

  700          infil = infil + 1

               if( infil .gt. 6 ) goto 990

               icf = min( inumc(chlw,ic,icl,' ') - 1, icl )

               lfile(infil) = icf - ic + 1
               ifile(infil)(1:icf-ic+1) = chin(ic:icf)

               ic = jnumc(chlw,icf+2,icl)

               if( ic .le. icl ) goto 700

               icl = jnumc(chlw,icl+2,i3)

               if( icl .le. i3 ) goto 200

*-----------------------------------------------------------------------
*        restart file name
*-----------------------------------------------------------------------

         else if( ipm .eq. 33 ) then

               call found_param_resfile(itnm,
     &                                  irfflg,ic,icl,chlw,chin,
     &                                  lrfile, irfile)

*-----------------------------------------------------------------------
*        title
*-----------------------------------------------------------------------

         else if( ipm .eq. 7 ) then

               ict = min( ic + 79, i2 )

               title = chin(ic:ict)

               titll = ict - ic + 1

*-----------------------------------------------------------------------
*        angel parameters
*-----------------------------------------------------------------------

         else if( ipm .eq. 8 ) then

               ict = min( ic + 199, i3 )

               angelp = chin(ic:ict)

               langel = ict - ic + 1
!-----------------------------------------------------------------------
!        sangel parameters
!-----------------------------------------------------------------------

         else if( ipm .eq. 40 ) then

            itsanf = itsanf + 1

            call read_sangel(jsn,jsi,dsin,idsi,ill,ilf,
     &                       jpn,chin,chlw,chcm,i1,i2,i3,i4,iskip,ierr
     &                      ,ic ,icl ,tname)
            if( ierr .ne. 0 ) return


*-----------------------------------------------------------------------
*        x-txt
*-----------------------------------------------------------------------

         else if( ipm .eq. 11 ) then

               ict = min( ic + 199, i2 )

               cxtxt = chin(ic:ict)

               lxtxt = ict - ic + 1

*-----------------------------------------------------------------------
*        y-txt
*-----------------------------------------------------------------------

         else if( ipm .eq. 12 ) then

               ict = min( ic + 199, i2 )

               cytxt = chin(ic:ict)

               lytxt = ict - ic + 1

*-----------------------------------------------------------------------
*        z-txt
*-----------------------------------------------------------------------

         else if( ipm .eq. 13 ) then

               ict = min( ic + 199, i2 )

               cztxt = chin(ic:ict)

               lztxt = ict - ic + 1

*-----------------------------------------------------------------------
*        gshow
*-----------------------------------------------------------------------

         else if( ipm .eq. 14 ) then

               call onum(chlw,ic,icl,cvvv,ierr)

               if( ierr .ne. 0 ) goto 997

               lgshow = nint( cvvv )

               icl = jnumc(chlw,icl+2,i3)

               if( icl .le. i3 ) goto 200

*-----------------------------------------------------------------------
*        gslat
*-----------------------------------------------------------------------

         else if( ipm .eq. 32 ) then

               call onum(chlw,ic,icl,cvvv,ierr)

               if( ierr .ne. 0 ) goto 997

               igslt = nint( cvvv )

               icl = jnumc(chlw,icl+2,i3)

               if( icl .le. i3 ) goto 200

*-----------------------------------------------------------------------
*        rshow
*-----------------------------------------------------------------------

         else if( ipm .eq. 15 ) then

               call onum(chlw,ic,icl,cvvv,ierr)

               if( ierr .ne. 0 ) goto 997

               lrshow = nint( cvvv )

               if( lrshow .le. 0 ) then

                  lrshow = 0

                  icl = jnumc(chlw,icl+2,i3)
                  if( icl .le. i3 ) goto 200

               end if

               if( chlw(icl+1:icl+1) .eq. ';' ) goto 993

               call txymesh(jsn,jsi,dsin,idsi,ill,ilf,
     &                      jpn,chin,chlw,chcm,i1,i2,i3,i4,ierr,
     &                      ixtp,inx,xmin,xmax,xdel,istxg,
     &                      iytp,iny,ymin,ymax,ydel,istyg,
     &                      iztp,inz,zmin,zmax,zdel,istzg)

                  if( ierr .ne. 0 ) return
                  if( jpn  .eq. 3 ) goto 800
                  if( ixtp .lt. 0 ) goto 996
                  if( iytp .lt. 0 ) goto 996
                  if( iztp .lt. 0 ) goto 996

                  goto 150

*-----------------------------------------------------------------------
*        reg echo length
*-----------------------------------------------------------------------

         else if( ipm .eq. 16 ) then

               call onum(chlw,ic,icl,cvvv,ierr)

               if( ierr .ne. 0 ) goto 997

               iechrl = nint( cvvv )

               if( iechrl .lt. 40 ) goto 997

               icl = jnumc(chlw,icl+2,i3)

               if( icl .le. i3 ) goto 200

*-----------------------------------------------------------------------
*        2d-type
*-----------------------------------------------------------------------

         else if( ipm .eq. 9 ) then

               call onum(chlw,ic,icl,cvvv,ierr)

               if( ierr .ne. 0 ) goto 997

               idtyp = nint( cvvv )

               if( idtyp .lt. 1 .or. idtyp .gt. 7 ) goto 983

               icl = jnumc(chlw,icl+2,i3)

               if( icl .le. i3 ) goto 200

*-----------------------------------------------------------------------
*        factor
*-----------------------------------------------------------------------

         else if( ipm .eq. 10 ) then

               call onum(chlw,ic,icl,cvvv,ierr)

               if( ierr .ne. 0 ) goto 997

               rfact = cvvv

               icl = jnumc(chlw,icl+2,i3)

               if( icl .le. i3 ) goto 200

*-----------------------------------------------------------------------
*        volmat
*-----------------------------------------------------------------------

         else if( ipm .eq. 18 ) then

               call onum(chlw,ic,icl,cvvv,ierr)

               if( ierr .ne. 0 ) goto 997

               matvol = nint( cvvv )

               icl = jnumc(chlw,icl+2,i3)

               if( icl .le. i3 ) goto 200

*-----------------------------------------------------------------------
*        epsout
*-----------------------------------------------------------------------

         else if( ipm .eq. 19 ) then

               call onum(chlw,ic,icl,cvvv,ierr)

               if( ierr .ne. 0 ) goto 997

               ieps = nint( cvvv )

               icl = jnumc(chlw,icl+2,i3)

               if( icl .le. i3 ) goto 200

*-----------------------------------------------------------------------
*        resolution
*-----------------------------------------------------------------------

         else if( ipm .eq. 26 ) then

               call onum(chlw,ic,icl,cvvv,ierr)

               if( ierr .ne. 0 ) goto 997

               ireso = nint( cvvv )

               icl = jnumc(chlw,icl+2,i3)

               if( icl .le. i3 ) goto 200

*-----------------------------------------------------------------------
*        width
*-----------------------------------------------------------------------

         else if( ipm .eq. 27 ) then

               call onum(chlw,ic,icl,cvvv,ierr)

               if( ierr .ne. 0 ) goto 997

               width = cvvv

               icl = jnumc(chlw,icl+2,i3)

               if( icl .le. i3 ) goto 200

*-----------------------------------------------------------------------
*        counter
*-----------------------------------------------------------------------

         else if( ipm .ge. 20 .and. ipm .le. 25 ) then

               call onum(chlw,ic,icl,cvvv,ierr)

               if( ierr .ne. 0 ) goto 997

               icount((ipm-20+2)/2) = 1
               icount( ipm-20+4)    = nint( cvvv )

               if( abs( nint(cvvv) ) .gt. 9999 ) goto 978

               icl = jnumc(chlw,icl+2,i3)

               if( icl .le. i3 ) goto 200

*-----------------------------------------------------------------------
*        multiplier
*-----------------------------------------------------------------------

         else if( ipm .eq. 28 ) then

               jmul = jmul + 1

               if( jmul .gt. 6 ) goto 970

            if( chlw(ic:ic+2) .eq. 'all' ) then

               jtln = 1
               jtal = 1

            else

               call onum(chlw,ic,icl,cvvv,ierr)

               if( ierr .ne. 0 ) goto 997

               jtln = nint( cvvv )
               jtal = 0

               if( jtln .lt. 0 ) goto 971

            end if

cfrtati 2023/12/07 imtinf added
               call tmultipl(jsn,jsi,dsin,idsi,ill,ilf,
     &                      jpn,chin,chlw,chcm,i1,i2,i3,i4,ierr,
     &                      jtln,jtal,jnpat,jptyp,jpnkf,dlmax,
     &                      jtli,jtls,mmst,imst,imtinf)

                  if( ierr .ne. 0 ) return

                  ktln(jmul)  = jtln
                  ktli(jmul)  = jtli
                  ktls(jmul)  = jtls
                  kmst(jmul)  = mmst
                  dkmax(jmul) = dlmax

                  knpat(jmul) = jnpat

               do j = 1, mmst

                  kimst(jmul,j) = imst(j)

               end do

               do j = 1, jnpat

                  kptyp(jmul,j) = jptyp(j)
                  kpnkf(jmul,j) = jpnkf(j)

               end do

                  if( jpn  .eq. 3 ) goto 800

               goto 150

*-----------------------------------------------------------------------
*        infog
*-----------------------------------------------------------------------

         else if( ipm .eq. 34 ) then

               call onum(chlw,ic,icl,cvvv,ierr)

               if( ierr .ne. 0 ) goto 997

               infog = nint( cvvv )

               icl = jnumc(chlw,icl+2,i3)

               if( icl .le. i3 ) goto 200

*-----------------------------------------------------------------------
*        stdcut
*-----------------------------------------------------------------------

         else if( ipm .eq. 39 ) then

               call onum(chlw,ic,icl,cvvv,ierr)

               if( ierr .ne. 0 ) goto 997

               stdcut = cvvv

               icl = jnumc(chlw,icl+2,i3)

               if( icl .le. i3 ) goto 200

*-----------------------------------------------------------------------
*        e-smin
*-----------------------------------------------------------------------

         else if( ipm .eq. 36 ) then

               call onum(chlw,ic,icl,cvvv,ierr)

               if( ierr .ne. 0 ) goto 997

               esmin = cvvv

               icl = jnumc(chlw,icl+2,i3)

               if( icl .le. i3 ) goto 200

*-----------------------------------------------------------------------
*        e-smax
*-----------------------------------------------------------------------

         else if( ipm .eq. 37 ) then

               call onum(chlw,ic,icl,cvvv,ierr)

               if( ierr .ne. 0 ) goto 997

               esmax = cvvv

               icl = jnumc(chlw,icl+2,i3)

               if( icl .le. i3 ) goto 200

*-----------------------------------------------------------------------
*        m-source
*-----------------------------------------------------------------------

         else if( ipm .eq. 38 ) then

               call onum(chlw,ic,icl,cvvv,ierr)

               if( ierr .ne. 0 ) goto 997

               msors = nint( cvvv )

               icl = jnumc(chlw,icl+2,i3)

               if( icl .le. i3 ) goto 200

*-----------------------------------------------------------------------
*        history counter
*-----------------------------------------------------------------------
         else if( ipm .ge. 41 .and. ipm .le. 46 ) then

               call onum(chlw,ic,icl,cvvv,ierr)

               if( ierr .ne. 0 ) goto 997

               icounth((ipm-41+2)/2) = 1
               icounth( ipm-41+4)    = nint( cvvv )

               if( abs( nint(cvvv) ) .gt. 9999 ) goto 978

               icl = jnumc(chlw,icl+2,i3)

               if( icl .le. i3 ) goto 200

*-----------------------------------------------------------------------

         end if

            goto 140

*-----------------------------------------------------------------------
*     check
*-----------------------------------------------------------------------

  800 continue

      if( ischn(7) .eq. 0 ) then

         if( imesh .eq. 1 ) then

            title = '[t-adjoint] in region mesh'
            titll = 26

         else if( imesh .eq. 2 ) then

            title = '[t-adjoint] in r-z mesh'
            titll = 23

         else if( imesh .eq. 3 ) then

            title = '[t-adjoint] in xyz mesh'
            titll = 23

         end if

      end if

      if( ischn(1) .eq. 0 ) then

         m_err = 'Mesh is not defined in tally '//tname
         ErrCha = ''
         ErrID = 'L:19473/R:tadjnt/F:tallsm2.f'
         goto 999

      else if( ischn(3) .eq. 0 ) then

         m_err = 'E-type is not defined in tally '//tname
         ErrCha = ''
         ErrID = 'L:19480/R:tadjnt/F:tallsm2.f'
         goto 999

      else if( inaxi .eq. 0 ) then

         m_err = 'Axis is not defined in tally '//tname
         ErrCha = ''
         ErrID = 'L:19487/R:tadjnt/F:tallsm2.f'
         goto 999

      else if( infil .eq. 0 ) then

         m_err = 'File is not defined in tally '//tname
         ErrCha = ''
         ErrID = 'L:19494/R:tadjnt/F:tallsm2.f'
         goto 999

      else if( inaxi .ne. infil ) then

         m_err = 'Number of Axis and File is different in tally '//tname
         ErrCha = ''
         ErrID = 'L:19501/R:tadjnt/F:tallsm2.f'
         goto 999

      else if( ischn(29) .eq. 0 .and. iunt .gt. 10 ) then

         m_err = 'T-type is not defined in tally '//tname
         ErrCha = ''
         ErrID = 'L:19508/R:tadjnt/F:tallsm2.f'
         goto 999

      else if( iatp .gt. 0 .and.
     &       ( amin .lt. 0.0 .or. amax .gt. 2*3.1416 ) ) then

         m_err = 'rad mesh should be 0 < rad < 2*pi in tally '//tname
         ErrCha = ''
         ErrID = 'L:19516/R:tadjnt/F:tallsm2.f'
         goto 999

      else if( iatp .lt. 0 .and.
     &       ( amin .lt. 0.0 .or. amax .gt. 360.0 ) ) then

         m_err = 'the mesh should be 0 < the < 360 in tally '//tname
         ErrCha = ''
         ErrID = 'L:19524/R:tadjnt/F:tallsm2.f'
         goto 999

      else if( jatp .eq. 3 .or. jatp .eq. 4 .or. jatp .eq. 5 ) then

         m_err = 'Angle mesh type should be 1, 2 in tally '//tname
         ErrCha = ''
         ErrID = 'L:19531/R:tadjnt/F:tallsm2.f'
         goto 999

      else if( itsanf > 1 ) then

         m_err = 'Double definition of sangel is found in tally '//tname
         ErrCha = ''
         ErrID = 'L:19538/R:tadjnt/F:tallsm2.f'
         goto 999

      end if

      do i = 1, inaxi

         if( lrshow .eq. 0 ) then

            if( ( iaxis(i) .eq. 7 .or. iaxis(i) .eq. 8 .or.
     &            iaxis(i) .eq. 9 ) .and. imesh .ne. 3 ) then

               m_err = 'Axis is xy, yz, or zx, '//
     &                 'but mesh is not xyz in tally '//tname
               ErrCha = ''
               ErrID = 'L:19553/R:tadjnt/F:tallsm2.f'
               goto 999

            end if

         end if

         if( iaxis(i) .eq. 11 .and. ittp .eq. 0 ) then

            m_err = 'T-type is not defined in tally '//tname
            ErrCha = ''
            ErrID = 'L:19564/R:tadjnt/F:tallsm2.f'
            goto 999

         else if( iaxis(i) .eq. 2 .and. imesh .ne. 1 ) then

            m_err = 'Axis is reg but mesh is not reg in tally '//tname
            ErrCha = ''
            ErrID = 'L:19571/R:tadjnt/F:tallsm2.f'
            goto 999

         else if( iaxis(i) .eq. 3 .and. imesh .ne. 3 ) then

            m_err = 'Axis is x but mesh is not xyz in tally '//tname
            ErrCha = ''
            ErrID = 'L:19578/R:tadjnt/F:tallsm2.f'
            goto 999

         else if( iaxis(i) .eq. 4 .and. imesh .ne. 3 ) then

            m_err = 'Axis is y but mesh is not xyz in tally '//tname
            ErrCha = ''
            ErrID = 'L:19585/R:tadjnt/F:tallsm2.f'
            goto 999

         else if( iaxis(i) .eq. 5 .and. imesh .eq. 1 ) then

            m_err = 'Axis is z but mesh is reg in tally '//tname
            ErrCha = ''
            ErrID = 'L:19592/R:tadjnt/F:tallsm2.f'
            goto 999

         else if( iaxis(i) .eq. 6 .and. imesh .ne. 2 ) then

            m_err = 'Axis is r but mesh is not r-z in tally '//tname
            ErrCha = ''
            ErrID = 'L:19599/R:tadjnt/F:tallsm2.f'
            goto 999

         else if( iaxis(i) .eq. 10 .and. imesh .ne. 2 ) then

            m_err = 'Axis is rz but mesh is not r-z in tally '//tname
            ErrCha = ''
            ErrID = 'L:19606/R:tadjnt/F:tallsm2.f'
            goto 999

         else if( iaxis(i) .eq. 10 .and.
     &           ( irtp .ne. 2 .and. irtp .ne. 4 ) ) then

            m_err = 'Axis is rz,'//
     &              ' but r mesh type is not 2 or 4 in tally '//tname
            ErrCha = ''
            ErrID = 'L:19615/R:tadjnt/F:tallsm2.f'
            goto 999

         else if( ( iaxis(i) .eq. 12 .or. iaxis(i) .eq. 13 ) .and.
     &              imesh .ne. 2 ) then

            m_err = 'Axis is rad or deg but mesh is not r-z in tally '
     &               //tname
            ErrCha = ''
            ErrID = 'L:19624/R:tadjnt/F:tallsm2.f'
            goto 999

         else if( iaxis(i) .eq. 12 .and. iatp .lt. 0 ) then

            m_err = 'Axis is rad but mesh is degree in tally '
     &               //tname
            ErrCha = ''
            ErrID = 'L:19632/R:tadjnt/F:tallsm2.f'
            goto 999

         else if( iaxis(i) .eq. 13 .and. iatp .gt. 0 ) then

            m_err = 'Axis is degree but mesh is radian in tally '
     &               //tname
            ErrCha = ''
            ErrID = 'L:19640/R:tadjnt/F:tallsm2.f'
            goto 999

         else if( iaxis(i) .eq. 10 .and.
     &           ( iztp .ne. 2 .and. iztp .ne. 4 ) ) then

            m_err = 'Axis is rz,'//
     &              ' but z mesh type is not 2 or 4 in tally '//tname
            ErrCha = ''
            ErrID = 'L:19649/R:tadjnt/F:tallsm2.f'
            goto 999

         else if( ( iaxis(i) .eq. 7 .or. iaxis(i) .eq. 9 ) .and.
     &           ( ixtp .ne. 2 .and. ixtp .ne. 4 ) ) then

            m_err = 'Axis is xy or zx,'//
     &              ' but x mesh type is not 2 or 4 in tally '//tname
            ErrCha = ''
            ErrID = 'L:19658/R:tadjnt/F:tallsm2.f'
            goto 999

         else if( ( iaxis(i) .eq. 8 .or. iaxis(i) .eq. 9 ) .and.
     &           ( iztp .ne. 2 .and. iztp .ne. 4 ) ) then

            m_err = 'Axis is yz or zx,'//
     &              ' but z mesh type is not 2 or 4 in tally '//tname
            ErrCha = ''
            ErrID = 'L:19667/R:tadjnt/F:tallsm2.f'
            goto 999

         else if( ( iaxis(i) .eq. 7 .or. iaxis(i) .eq. 8 ) .and.
     &           ( iytp .ne. 2 .and. iytp .ne. 4 ) ) then

            m_err = 'Axis is xy or yz,'//
     &              ' but y mesh type is not 2 or 4 in tally '//tname
            ErrCha = ''
            ErrID = 'L:19676/R:tadjnt/F:tallsm2.f'
            goto 999

         end if

      end do

*-----------------------------------------------------------------------
*     summary
*-----------------------------------------------------------------------

                  itnm = itnm + 1

                  if( itnm .gt. itlmax ) goto 986

                  ital( itnm ) = 19

                  itsmn(itnm) = 0
                  itstm(itnm) = 0

                  itxnm(itnm) = 0
                  itynm(itnm) = 0
                  itznm(itnm) = 0

*-----------------------------------------------------------------------
*        title
*-----------------------------------------------------------------------

                  ittll(itnm) = titll
                  ittle(itnm) = title

*-----------------------------------------------------------------------
*        angel parameter
*-----------------------------------------------------------------------

               if( langel .gt. 0 ) then

                  itanl(itnm) = langel
                  itang(itnm) = angelp

               else

                  itanl(itnm) = 0

               end if

*-----------------------------------------------------------------------
*        x-txt parameter
*-----------------------------------------------------------------------

               if( lxtxt .gt. 0 ) then

                  itaxl(itnm) = lxtxt
                  itaxt(itnm) = cxtxt

               else

                  itaxl(itnm) = 0

               end if

*-----------------------------------------------------------------------
*        y-txt parameter
*-----------------------------------------------------------------------

               if( lytxt .gt. 0 ) then

                  itayl(itnm) = lytxt
                  itayt(itnm) = cytxt

               else

                  itayl(itnm) = 0

               end if

*-----------------------------------------------------------------------
*        z-txt parameter
*-----------------------------------------------------------------------

               if( lztxt .gt. 0 ) then

                  itazl(itnm) = lztxt
                  itazt(itnm) = cztxt

               else

                  itazl(itnm) = 0

               end if

*-----------------------------------------------------------------------
*        gshow parameter
*-----------------------------------------------------------------------

               if( lgshow .gt. 0 ) then

                  itgsh(itnm) = min(5,lgshow)  ! T.Sato 2019/02/20

               else

                  itgsh(itnm) = 0

               end if

*-----------------------------------------------------------------------
*        gslat parameter
*-----------------------------------------------------------------------
                  itglt(itnm) = igslt

*-----------------------------------------------------------------------
*        rshow parameter
*-----------------------------------------------------------------------

                  itrsh(itnm) = min(4,lrshow)

*-----------------------------------------------------------------------
*        mesh
*-----------------------------------------------------------------------

                  itmsh(itnm) = imesh

         if( imesh .eq. 1 ) then

                  itrgn(itnm) = ntrn
                  itrgm(itnm) = mtrn
                  itrnv(itnm) = nvol

            if( ntrn .gt. 0 ) then

                  call moddas_reallocate_int(
     &                    itlmax, itnm, mtrn, itreg, idas_itreg)
                  idas_itreg(itreg(itnm):itreg(itnm)+mtrn-1)
     &                      = idas_itreg_temporary(1:mtrn)
                  call moddas_deallocate_int(idas_itreg_temporary)
                  itsmn(itnm) = itsmn(itnm)
     &                        + ( mtrn + mod(mtrn,2) ) / 2

            end if

            if( nvol .gt. 0 ) then

                  itriv(itnm) = ivl
                  itsmn(itnm) = itsmn(itnm)
     &                        + ( nvol + mod(nvol,2) ) / 2

                  itrrv(itnm) = irvl
                  itsmn(itnm) = itsmn(itnm) + nvol

            end if

         end if

         if( imesh .eq. 2 ) then

                  rtrx0(itnm) = rzx0
                  rtry0(itnm) = rzy0

                  itrty(itnm) = irtp
                  itrnm(itnm) = inr
                  rtrdl(itnm) = rdel
                  rtrmi(itnm) = rmin
                  rtrma(itnm) = rmax
                  call moddas_reallocate_dbl(
     &                    itlmax, itnm, inr+1, itrrg, das_itrrg)
                  das_itrrg(itrrg(itnm):itrrg(itnm)+inr)
     &                     = gmsh(istrg:istrg+inr)
                  itsmn(itnm) = itsmn(itnm) + inr + 1


                  itzty(itnm) = iztp
                  itznm(itnm) = inz
                  rtzdl(itnm) = zdel
                  rtzmi(itnm) = zmin
                  rtzma(itnm) = zmax
                  call moddas_reallocate_dbl(
     &                    itlmax, itnm, inz+1, itzrg, das_itzrg)
                  das_itzrg(itzrg(itnm):itzrg(itnm)+inz)
     &                     = gmsh(istzg:istzg+inz)
                  itsmn(itnm) = itsmn(itnm) + inz + 1

         else if( imesh .eq. 3 .or. lrshow .gt. 0 ) then

                  itxty(itnm) = ixtp
                  itxnm(itnm) = inx
                  rtxdl(itnm) = xdel
                  rtxmi(itnm) = xmin
                  rtxma(itnm) = xmax
                  call moddas_reallocate_dbl(
     &                    itlmax, itnm, inx+1, itxrg, das_itxrg)
                  das_itxrg(itxrg(itnm):itxrg(itnm)+inx)
     &                     = gmsh(istxg:istxg+inx)
                  itsmn(itnm) = itsmn(itnm) + inx + 1

                  ityty(itnm) = iytp
                  itynm(itnm) = iny
                  rtydl(itnm) = ydel
                  rtymi(itnm) = ymin
                  rtyma(itnm) = ymax
                  call moddas_reallocate_dbl(
     &                    itlmax, itnm, iny+1, ityrg, das_ityrg)
                  das_ityrg(ityrg(itnm):ityrg(itnm)+iny)
     &                     = gmsh(istyg:istyg+iny)
                  itsmn(itnm) = itsmn(itnm) + iny + 1


                  itzty(itnm) = iztp
                  itznm(itnm) = inz
                  rtzdl(itnm) = zdel
                  rtzmi(itnm) = zmin
                  rtzma(itnm) = zmax
                  call moddas_reallocate_dbl(
     &                    itlmax, itnm, inz+1, itzrg, das_itzrg)
                  das_itzrg(itzrg(itnm):itzrg(itnm)+inz)
     &                     = gmsh(istzg:istzg+inz)
                  itsmn(itnm) = itsmn(itnm) + inz + 1

         end if

*-----------------------------------------------------------------------
*        material
*-----------------------------------------------------------------------

                  itmtn(itnm) = imate
                  itmcn(itnm) = jmate

            if( imate .gt. 0 ) then

                  itsmn(itnm) = itsmn(itnm)
     &                        + ( imate + mod(imate,2) ) / 2

            end if

*-----------------------------------------------------------------------
*        energy mesh
*-----------------------------------------------------------------------

               if( ( iunt .eq. 3 .or. iunt .eq. 13 ) .and.
     &             gmsh(isteg-1+2) .le. 0.0d0 ) goto 985

               if( ( iunt .eq. 3 .or. iunt .eq. 13 ) .and.
     &             gmsh(isteg-1+1) .le. 0.0d0 ) then

                  if( ine .ge. 2 ) then

                     gmsh(isteg-1+1) =
     &                  gmsh(isteg-1+2)**2 / gmsh(isteg-1+3)

                  else

                     gmsh(isteg-1+1) = gmsh(isteg-1+2) / 1000.0

                  end if

               end if

                  itety(itnm) = ietp
                  itenm(itnm) = ine
                  rtedl(itnm) = edel
                  rtemi(itnm) = emin
                  rtema(itnm) = emax

                  call moddas_reallocate_dbl(
     &                    itlmax, itnm, ine+1, iterg, das_iterg)
                  das_iterg(iterg(itnm):iterg(itnm)+ine)
     &                     = gmsh(isteg:isteg+ine)
                  itsmn(itnm) = itsmn(itnm) + ine + 1

*-----------------------------------------------------------------------
*        angle mesh
*        and for without angle mesh
*-----------------------------------------------------------------------

               if( ischn(35) .ne. 0 ) then

                  call moddas_reallocate_dbl(
     &                    itlmax, itnm, ina+1, itarg, das_itarg)
                  das_itarg(itarg(itnm):itarg(itnm)+ina)
     &                     = gmsh(istag:istag+ina)
                  itsmn(itnm) = itsmn(itnm) + ina + 1

               else

cKN 2014/12/04 !!
                  iatp = 0
                  ina  = 1

                  istag = iaddress_gmsh(icurrent_gmsh)
                  call moddas_reallocate_dbl(
     &                    3, icurrent_gmsh, 2, iaddress_gmsh, gmsh)
                  iaddress_gmsh(2) = iaddress_gmsh(3)
                  icurrent_gmsh = 2

                  call moddas_reallocate_dbl(
     &                    itlmax, itnm, 2, itarg, das_itarg)
                  itsmn(itnm) = itsmn(itnm) + 2

                  gmsh(istag-1+1) = 0.0
                  gmsh(istag-1+2) = 360.0
                  das_itarg(itarg(itnm)-1+1) = 0.0
                  das_itarg(itarg(itnm)-1+2) = 360.0

               end if

                  itaty(itnm) = iatp
                  itanm(itnm) = ina
                  rtadl(itnm) = adel
                  rtami(itnm) = amin
                  rtama(itnm) = amax

*-----------------------------------------------------------------------
*        time mesh
*-----------------------------------------------------------------------

               if( ittp .ne. 0 ) then

                  ittty(itnm) = ittp
                  ittnm(itnm) = int
                  rttdl(itnm) = tdel
                  rttmi(itnm) = tmin
                  rttma(itnm) = tmax

                  call moddas_reallocate_dbl(
     &                    itlmax, itnm, int+1, ittrg, das_ittrg)
                  das_ittrg(ittrg(itnm):ittrg(itnm)+int)
     &                     = gmsh(isttg:isttg+int)
                  itsmn(itnm) = itsmn(itnm) + int + 1

               else

                  ittty(itnm) = ittp
                  ittnm(itnm) = 1
                  rttdl(itnm) = 0.d0
                  rttmi(itnm) = 0.d0
                  rttma(itnm) = 0.d0

                  call moddas_reallocate_dbl(
     &                    itlmax, itnm, 2, ittrg, das_ittrg)
                  itsmn(itnm) = itsmn(itnm) + 2

                  das_ittrg(ittrg(itnm)  ) = -1.d+30
                  das_ittrg(ittrg(itnm)+1) =  1.d+30

                  call moddas_reallocate_dbl(
     &                    3, icurrent_gmsh, 2, iaddress_gmsh, gmsh)
                  gmsh(iaddress_gmsh(icurrent_gmsh)  ) = -1.d+30
                  gmsh(iaddress_gmsh(icurrent_gmsh)+1) =  1.d+30
                  iaddress_gmsh(2) = iaddress_gmsh(3)
                  icurrent_gmsh = 2

               end if

*-----------------------------------------------------------------------
*        transformation
*-----------------------------------------------------------------------

                     itmtr(itnm,1) = igkst
                     itmtr(itnm,2) = ktrs
                     itmtr(itnm,3) = idtt
                     itmtr(itnm,4) = 0

               if( igkst .gt. 1 ) then

                  do k = 1, 13

                     rtmtr(itnm,k) = vtrs(k)

                  end do

               end if

*-----------------------------------------------------------------------
*        reg echo length
*-----------------------------------------------------------------------

                  iterl(itnm) = iechrl

*-----------------------------------------------------------------------
*        unit
*-----------------------------------------------------------------------

                  itunt(itnm) = iunt

*-----------------------------------------------------------------------
*        2d-type
*-----------------------------------------------------------------------

                  ittwo(itnm) = idtyp

*-----------------------------------------------------------------------
*        factor
*-----------------------------------------------------------------------

                  rtfac(itnm) = rfact

*-----------------------------------------------------------------------
*        volmat  ( unit = 4 -> vol = 1.0 then volmat = 0 )
*-----------------------------------------------------------------------

                  itvm(itnm) = matvol

                  if( iunt .eq. 4 .or. iunt .eq. 14 ) itvm(itnm) = 0

*-----------------------------------------------------------------------
*        epsout
*-----------------------------------------------------------------------

                  iteps(itnm) = ieps

*-----------------------------------------------------------------------
*        resolution
*-----------------------------------------------------------------------

                  itres(itnm) = max( 1, ireso )

*-----------------------------------------------------------------------
*        width
*-----------------------------------------------------------------------

                  rtwid(itnm) = width

*-----------------------------------------------------------------------
*        e-source, e-width and m-souce
*-----------------------------------------------------------------------

                  rtade(itnm) = esmin
                  rtadw(itnm) = esmax
                  itadm(itnm) = msors

*-----------------------------------------------------------------------
*        special for multi-source written into itpan(itnm)
*-----------------------------------------------------------------------

                  itmxptt = itadm(itnm) ! frtati 2022/06/16
                  itmxgpt = 1
                  call ALLOCATE_PART_TEMP

                  itpan(itnm) = itadm(itnm)

*-----------------------------------------------------------------------
*        counter
*-----------------------------------------------------------------------

               do i = 1, 9

                  itcnt(i,itnm) = icount(i)
                  itcnth(i,itnm) = icounth(i) !frtati 2021/04/06

               end do

*-----------------------------------------------------------------------
*        axis
*-----------------------------------------------------------------------

                  itaxn(itnm) = inaxi

               do i = 1, inaxi

                  itaxs(itnm,i) = iaxis(i)

               end do

*-----------------------------------------------------------------------
*        infog
*-----------------------------------------------------------------------

                  itger(itnm) = infog

*-----------------------------------------------------------------------
*        stdcut
*-----------------------------------------------------------------------
                  rtstd(itnm) = stdcut

*-----------------------------------------------------------------------
*        file
*-----------------------------------------------------------------------

                  itfln(itnm) = infil

               do i = 1, infil

                  itfll(itnm,i) = lfile(i)

                  ctfln(itnm,i)(1:lfile(i)) = ifile(i)(1:lfile(i))

                  do k = lfile(i) + 1, 100

                     ctfln(itnm,i)(k:k) = ' '

                  end do

               end do

*-----------------------------------------------------------------------
*       restart file
*-----------------------------------------------------------------------
               call summary_param_resfile(itnm,irfflg,lrfile,irfile)

*-----------------------------------------------------------------------
*        multiplier
*-----------------------------------------------------------------------

                  itmlp(itnm) = jmul

         if( jmul .gt. 0 ) then

                  itmst(itnm) = kmst(1)

                  do j = 1, kmst(1)

                     itmnt(itnm,j) = kimst(1,j)

                  end do

            do k = 1, jmul

                  if( kmst(k) .ne. kmst(1) ) goto 969

                  do j = 1, kmst(1)

                     if( kimst(k,j) .ne. itmnt(itnm,j) ) goto 968

                  end do

                  itmln(itnm,k) = ktln(k)
                  itmli(itnm,k) = ktli(k)
                  rtmme(itnm,k) = dkmax(k)
                  itmpn(itnm,k) = knpat(k)

               do j = 1, knpat(k)

                  itmpt(itnm,k,j,1) = kptyp(k,j)
                  itmpt(itnm,k,j,2) = kpnkf(k,j)

               end do

                  ltli = 13 * ktln(k)

                  itsmn(itnm) = itsmn(itnm)
     &                        + ( ltli + mod(ltli,2) ) / 2
     &                        + ktls(k)

                  itmto(itnm,k,:) = imtinf(:) ! frtati 2023/12/07

            end do

         end if

*-----------------------------------------------------------------------

      return

*-----------------------------------------------------------------------
*     errors
*-----------------------------------------------------------------------

  950    write(dkam,'(i9)') mdas
         m_err = 'Total tally storage number exceeds mdas ='//dkam
         ErrCha = ''
         ErrID = 'L:20235/R:tadjnt/F:tallsm2.f'
         goto 999

  967    m_err = 'particle cannot be used in this tally '//tname
         ErrCha = ''
         ErrID = 'L:20240/R:tadjnt/F:tallsm2.f'
         goto 999

  968    m_err = 'mset number is inconsistent.'//tname
         ErrCha = ''
         ErrID = 'L:20245/R:tadjnt/F:tallsm2.f'
         goto 999

  969    m_err = 'number of mset should be the same.'//tname
         ErrCha = ''
         ErrID = 'L:20250/R:tadjnt/F:tallsm2.f'
         goto 999

  970    m_err = 'def of multiplier should be less than 7 '//tname
         ErrCha = ''
         ErrID = 'L:20255/R:tadjnt/F:tallsm2.f'
         goto 999

  971    m_err = 'number of multiplier is negative'//tname
         ErrCha = ''
         ErrID = 'L:20260/R:tadjnt/F:tallsm2.f'
         goto 999

  978    m_err = 'counter should be from -9999 to 9999'
         ErrCha = ''
         ErrID = 'L:20265/R:tadjnt/F:tallsm2.f'
         goto 999

  979    m_err = 'Description of material parameter is wrong in tally '
     &            //tname
         ErrCha = ''
         ErrID = 'L:20271/R:tadjnt/F:tallsm2.f'
         goto 999

  983    m_err = '2D-type should be 1-7 in tally '//tname
         ErrCha = ''
         ErrID = 'L:20276/R:tadjnt/F:tallsm2.f'
         goto 999

  985    m_err = 'Unit is Lethargy but energy mesh points are negative'
         ErrCha = ''
         ErrID = 'L:20281/R:tadjnt/F:tallsm2.f'
         goto 999

  986    write(dkam,'(i5)') itlmax
         m_err = 'Total tally number exceeds itlmax = '//dkam
         ErrCha = ''
         ErrID = 'L:20287/R:tadjnt/F:tallsm2.f'
         goto 999

  987    m_err = 'Unknown parameter in tally '//tname
         ErrCha = ''
         ErrID = 'L:20292/R:tadjnt/F:tallsm2.f'
         goto 999

  988    m_err = 'Unit should be 1,2,3,4,11,12,13,14 in tally '//tname
         ErrCha = ''
         ErrID = 'L:20297/R:tadjnt/F:tallsm2.f'
         goto 999

  989    m_err = 'Double definition of the parameter in tally '//tname
         ErrCha = ''
         ErrID = 'L:20302/R:tadjnt/F:tallsm2.f'
         goto 999

  990    m_err = 'Too many file name in tally '//tname
         ErrCha = ''
         ErrID = 'L:20307/R:tadjnt/F:tallsm2.f'
         goto 999

  991    m_err = 'Too many axis in tally '//tname
         ErrCha = ''
         ErrID = 'L:20312/R:tadjnt/F:tallsm2.f'
         goto 999

  992    m_err = 'Unknown axis name in tally '//tname
         ErrCha = ''
         ErrID = 'L:20317/R:tadjnt/F:tallsm2.f'
         goto 999

  993    m_err = 'In this line, [ ; ] cannot be used.'
         ErrCha = ''
         ErrID = 'L:20322/R:tadjnt/F:tallsm2.f'
         goto 999

  994    m_err = 'Name of particle is wrong in tally '//tname
         ErrCha = ''
         ErrID = 'L:20327/R:tadjnt/F:tallsm2.f'
         goto 999

  995    m_err = 'Number of particles is larger than 6 in tally '//tname
         ErrCha = ''
         ErrID = 'L:20332/R:tadjnt/F:tallsm2.f'
         goto 999

  996    m_err = 'Description of mesh is wrong in tally '//tname
         ErrCha = ''
         ErrID = 'L:20337/R:tadjnt/F:tallsm2.f'
         goto 999

  997    m_err = 'Description of parameter is wrong in tally '//tname
         ErrCha = ''
         ErrID = 'L:20342/R:tadjnt/F:tallsm2.f'
         goto 999

  998    m_err = 'Unknown mesh parameter in tally '//tname
         ErrCha = ''
         ErrID = 'L:20347/R:tadjnt/F:tallsm2.f'
         goto 999

*-----------------------------------------------------------------------

  999 continue

         l_err = ill(jsn)
         k_err = jsn
         ierr  = 1

*-----------------------------------------------------------------------

      return
      end


************************************************************************
*                                                                      *
      subroutine tcross(jsn,jsi,dsin,idsi,ill,ilf,
     &                  jpn,chin,chlw,chcm,i1,i2,i3,i4,ierr)
*                                                                      *
*       read [t-cross] section of input files                          *
*       modified by K.Niita on 2005/11/23                              *
*                                                                      *
************************************************************************
      use sangelmod, only: itsanf
      use anatallymod, only: nanatalRead
      use partmod ! frtati 2021/10/05
      use moddas
      use moddas_mesh
      use moddas_region

      implicit real*8 (a-h,o-z)

      parameter(icsu=47) ! nais 2023/01/06

      include 'param.inc'
      include 'param01.inc' ! frtati 2021/10/05
      include 'err.inc'

*-----------------------------------------------------------------------

      common /tall00/ itnm, ital(itlmax), itals(itlmax), italm(itlmax)
      common /tall01/ itmsh(itlmax), itunt(itlmax), itspc(itlmax),
     &                itout(itlmax), ittwo(itlmax)

      common /tall03/ itrty(itlmax), itrnm(itlmax), itrrg(itlmax),
     &                rtrmi(itlmax), rtrma(itlmax), rtrdl(itlmax)
      common /tall04/ itxty(itlmax), itxnm(itlmax), itxrg(itlmax),
     &                rtxmi(itlmax), rtxma(itlmax), rtxdl(itlmax)
      common /tall05/ ityty(itlmax), itynm(itlmax), ityrg(itlmax),
     &                rtymi(itlmax), rtyma(itlmax), rtydl(itlmax)
      common /tall06/ itzty(itlmax), itznm(itlmax), itzrg(itlmax),
     &                rtzmi(itlmax), rtzma(itlmax), rtzdl(itlmax)
      common /tall07/ itety(itlmax), itenm(itlmax), iterg(itlmax),
     &                rtemi(itlmax), rtema(itlmax), rtedl(itlmax)

      common /tall23/ itaty(itlmax), itanm(itlmax), itarg(itlmax),
     &                rtami(itlmax), rtama(itlmax), rtadl(itlmax)

      common /tall08/ rtrx0(itlmax), rtry0(itlmax)

      common /tall10/ itaxn(itlmax), itaxs(itlmax,6)
      common /tall11/ itfln(itlmax), itfll(itlmax,6), ctfln(itlmax,6)
      character ctfln*100

      common /tall13/ itrcn(itlmax), itrcr(itlmax), itrca(itlmax)
      common /tall26/ itrcs(itlmax), itrcc(itlmax), itrss(itlmax)

      common /tall14/ ittll(itlmax), ittle(itlmax)
      character ittle*80

      common /tall15/ itanl(itlmax), itang(itlmax)
      character itang*200

      common /tall27/ itaxl(itlmax), itaxt(itlmax),
     &                itayl(itlmax), itayt(itlmax),
     &                itazl(itlmax), itazt(itlmax)
      character itaxt*200, itayt*200, itazt*200

      common /tall19/ itsmn(itlmax), itstm(itlmax)
      common /tall20/ ittty(itlmax), ittnm(itlmax), ittrg(itlmax),
     &                rttmi(itlmax), rttma(itlmax), rttdl(itlmax)
      common /tall21/ rtfac(itlmax)
      common /tall28/ itgsh(itlmax)
      common /tall35/ iteps(itlmax)
      common /tall37/ itcnt(9,itlmax)

      common /tall38/ itres(itlmax)
      common /tall39/ rtwid(itlmax)

*-----------------------------------------------------------------------
      common /tall45/ itmlp(itlmax), itmln(itlmax,6), itmst(itlmax),
     &                itmli(itlmax,6), rtmme(itlmax,6), itmnt(itlmax,6),
     &                itmpn(itlmax,6), itmpt(itlmax,6,6,2)

*-----------------------------------------------------------------------

      common /tall46/ itmtr(itlmax,4), rtmtr(itlmax,13)

      common /tall48/ itmdp(itlmax,0:30), itmdf(itlmax)
      common /tall49/ itglt(itlmax)

!OBINATA: for resfile
      common /tall59/ irfll(itlmax), crfln(itlmax), itrff(itlmax)
      character crfln*100
      character irfile*100

      common /tall60/ itger(itlmax)

      common /tall67/ itstd(itlmax), rtstd(itlmax)

      common /paraj/  mstz(300), parz(300) ! S.H. 2022.1.21

      common /tall73/ itenclo(itlmax), itangform(itlmax)

      common /tall82/ itcnth(9,itlmax)
      dimension icounth(9)
cfrtati 2023/12/07
      common /tall84/ itmto(itlmax,6,4)

      common /tall50/ itlmt(itlmax), ite2l(itlmax)   ! CCSE 2022.08.31

! 20230106 nais samepage
      common /tall90/ itpgn(itlmax), itpgs(itlmax,6)

      dimension idas(1)
      equivalence ( das, idas )

      common/nzerocom/nzerocheck ! T.Sato 2018/3/6, allow nz = 0 for [t-cross]

*-----------------------------------------------------------------------

      character m_err*200
      common /error/ m_err, l_err, k_err

*-----------------------------------------------------------------------

      character title*80
      character angelp*200
      character cxtxt*200
      character cytxt*200
      character cztxt*200

*-----------------------------------------------------------------------
CCSE added for LET parameter, 44 -> 46 (2022.08.31) >>>>>

      dimension lschn(icsu), ischn(icsu)
      character schan(icsu)*8

      data ( schan(i), i = 1, icsu ) /
     &    'mesh    ','part    ','e-type  ','unit    ','axis    ',
     &    'file    ','title   ','angel   ','output  ','2d-type ',
     &    'factor  ','a-type  ','x-txt   ','y-txt   ','z-txt   ',
     &    'gshow   ','epsout  ','ctmin(1)','ctmax(1)','ctmin(2)',
     &    'ctmax(2)','ctmin(3)','ctmax(3)','resol   ','width   ',
     &    't-type  ','trcl    ','*trcl   ','dump    ','gslat   ',
     &    'resfile ','ginfo   ','multipli','stdcut  ','sangel  ',
     &    'enclos  ','iangform','chmin(1)','chmax(1)','chmin(2)',
     &    'chmax(2)','chmin(3)','chmax(3)','maxangel','letmat  ',
     &    'eng2let ','samepage'/

      data ( lschn(i), i = 1, icsu ) /
     &     4,         4,         6,         4,         4,
     &     4,         5,         5,         6,         7,
     &     6,         6,         5,         5,         5,
     &     5,         6,         8,         8,         8,
     &     8,         8,         8,         5,         5,
     &     6,         4,         5,         4,         5,
     &     7,         5,         8,         6,         6,
     &     6,         8,         8,         8,         8,
     &     8,         8,         8,         8,         6,
     &     7,         8/

*-----------------------------------------------------------------------

cfrtati 2021/10/05 6 -> mxpart
      dimension iptyp(mxpart), ipnkf(mxpart)
      dimension imtyp(mxpart,mxpart), imnkf(mxpart,mxpart)
      dimension jstyp(mxpart), jnkf0(mxpart)

      common /subtra/ isubt, ipsub(mxpart)  ! kitamura22/03/31

      dimension iaxis(6)
      character ifile(6)*100
      dimension lfile(6)

      dimension ipgis(6)   ! samepage nais 2023/01/06


*-----------------------------------------------------------------------

      character chin*200, chlw*200, chcm*200
      character chlc*200

      character dsin(0:9)*200
      dimension idsi(0:9)

      dimension ill(0:9), ilf(0:9)

      character dkam*9

      character tname*9
      data      tname /'[t-cross]'/

      dimension icount(9)
      dimension vtrs(13)

      dimension jdump(30)

*-----------------------------------------------------------------------

      dimension jptyp(6), jpnkf(6)
      dimension kptyp(6,6), kpnkf(6,6)
      dimension ktln(6), ktli(6), ktls(6), kmst(6), knpat(6)
      dimension dkmax(6)
      dimension imst(6), kimst(6,6)
      dimension imtinf(4) ! frtati 2023/12/07

*-----------------------------------------------------------------------

      integer isumtalRead

*-----------------------------------------------------------------------

            ierr  = 0

            iunt  = 1
            imate = 0
            jmate = 1
            iout  = 1
            inpat = 0
            inaxi = 0
            infil = 0
            idtyp = 3   ! S.Abe 2018/10/18, 2 -> 3
            jmul  = 0

            langel = 0
            itsanf = 0
            lxtxt  = 0
            lytxt  = 0
            lztxt  = 0
            lgshow = 0
            ieps   = 0
            ietp   = 0
            ittp   = 0
            iatp   = 0
            jatp   = 0
            igkst  = 0
            idtt   = 0
            ktrs   = 0
            idump  = 0
            igslt  = -1
            letmat = 0  ! CCSE 2022/08/31
            ieng2let= 0 ! CCSE 2022/08/31 Flag to convert energy to LET
            lrfile = 0 !OBINATA
            irfflg = 0 !OBINATA
            imxang = 0 ! frtati 2021/10/05

            amin = 0.0
            amax = 0.0
            adel = 0.0 !FURUTA

            icount(1) = 0
            icount(2) = 0
            icount(3) = 0
            icount(4) = -9999
            icount(5) =  9999
            icount(6) = -9999
            icount(7) =  9999
            icount(8) = -9999
            icount(9) =  9999
            icounth(1) = 0
            icounth(2) = 0
            icounth(3) = 0
            icounth(4) = -9999
            icounth(5) =  9999
            icounth(6) = -9999
            icounth(7) =  9999
            icounth(8) = -9999
            icounth(9) =  9999

            ireso = 1
            width = 0.5

            rfact = 1.0

         do i = 1, icsu

            ischn(i) = 0

         end do

         do i = 1, 30
            jdump(i) = 0
         end do

            infog = 0

         inpgi = 0   ! samepage 2023/01/06

       isumtalRead = 0
            istbat = 0 ! S.H. 2022.3.10

            stdcut = -1.0

            ienclo = 0   ! S.Abe 2018/10/18

            iangform = 0   ! S.Abe 2019/11/26

! T.Sato 2021/05/05 to avoid uninitialization error for omni data
            edel=0.0
            emin=0.0
            emax=0.0

*-----------------------------------------------------------------------
*     read one line from jsi
*-----------------------------------------------------------------------

  140 continue

            call readl(jsn,jsi,dsin,idsi,ill,ilf,'#!$',
     &                 jpn,chin,chlw,chcm,i1,i2,i3,i4,iskip,ierr)

               if( ierr .ne. 0 ) return
               if( jpn  .eq. 3 ) goto 800

               if( iskip .ne. 0 ) goto 140

  150 continue

               if( ierr .ne. 0 ) return
               if( jpn  .eq. 3 ) goto 800

*-----------------------------------------------------------------------
*        end of the section
*-----------------------------------------------------------------------

            if( chlw(i1:i1) .eq. '[' ) then

               jpn = 1
               goto 800

            end if

*-----------------------------------------------------------------------
*        identify the parameters
*-----------------------------------------------------------------------

            icl = i1

!-----------------------------------------------------------------------
!        sumtally sub section
!-----------------------------------------------------------------------
      if ( chlw(i1:i3) .eq. 'sumtally start' ) then
       isumtalRead = 1
       call read_sumtal(jsn,jsi,dsin,idsi,ill,ilf,
     &                 jpn,chin,chlw,chcm,i1,i2,i3,i4,iskip,ierr)
       if( ierr .ne. 0 ) return
       if( jpn == 3 ) goto 800   ! 'q:'
       if( jpn == 1 ) goto 800   ! end of the section
       go to 140
      end if

*-----------------------------------------------------------------------
*        anatally
*-----------------------------------------------------------------------

      if ( chlw(i1:i3) .eq. 'anatally start' ) then

         if (  mstz(1) .eq. 17 ) then
            nanatalRead(1+itnm) = 1
            call readl(jsn,jsi,dsin,idsi,ill,ilf,'#!$',
     &           jpn,chin,chlw,chcm,i1,i2,i3,i4,iskip,ierr)
            if ( chlw(i1:i3) .ne. 'anatally end' ) then
               ierr = 1
            end if
         else

            istbat = 1

            call stbatm(jsn,jsi,dsin,idsi,ill,ilf,
     &                  jpn,chin,chlw,chcm,i1,i2,i3,i4,ierr,
     &                  ist_nm,isd_nm,kst_nm)

            if( ierr .ne. 0 ) return
            if( jpn == 3 ) goto 800   ! 'q:'
            if( jpn == 1 ) goto 800   ! end of the section

         end if ! S.H. (2020.2.25)
            goto 140

      end if

*-----------------------------------------------------------------------

  200    continue

            chlc = chlw
            call chcomp(chlc,icl,i3,i5)

         do i = 1, icsu

            il = icl + lschn(i) - 1

            if( chlc(icl:il) .eq. schan(i)(1:lschn(i)) ) goto 100

         end do

               goto 987

*-----------------------------------------------------------------------
*        read value of parameters
*-----------------------------------------------------------------------

  100    continue

               ipm = i

               ischn( ipm ) = ischn( ipm ) + 1

            if( ipm .ne. 5 .and. ipm .ne. 6 .and.
     &          ipm .ne. 2 .and. ipm .ne. 31 .and.
     &          ipm .ne. 33 .and.
     &          ischn( ipm ) .gt. 1 ) goto 989

               ic = inumc(chlw,il+1,i3,'=') + 1
               ic = jnumc(chlw,ic,i3)

               if( ic .gt. i3 ) goto 997

               icl = inumc(chlw,ic,i3,';') - 1

*-----------------------------------------------------------------------
*        mesh = region,  r-z, xyz
*-----------------------------------------------------------------------

         if( ipm .eq. 1 ) then

            if( chlw(ic:ic+2) .eq. 'reg' ) then

               imesh = 1

            else if( chlw(ic:ic+2) .eq. 'r-z' ) then

               imesh = 2

            else if( chlw(ic:ic+2) .eq. 'xyz' ) then

               imesh = 3

            else

               goto 998

            end if

            if( chlw(icl+1:icl+1) .eq. ';' ) goto 993

            if( imesh .eq. 1 ) then

               call moddas_allocate_int(MAX_NUM_NTCR, idas_ntcr)
               call moddas_allocate_dbl(MAX_NUM_KTCR, das_ktcr)

               call tcrsreg(jsn,jsi,dsin,idsi,ill,ilf,
     &                      jpn,chin,chlw,chcm,i1,i2,i3,i4,ierr,
     &                      ntcn,ntcr,ktcr,iseq,mtcr,mmcr
     &                      ,MAX_NUM_NTCR,MAX_NUM_KTCR
     &                      ,idas_ntcr,das_ktcr)

               if( mtcr > MAX_NUM_NTCR ) then
                  write(ErrCha,'(a,a,i5,a,a,i5,a)')
     &                 'sub.tcross@tallsm2.f'
     &                    //' ?dimension over idas_ntcr?'
     &                    //' mtcr > MAX_NUM_NTCR'
     &                 ,' (mtcr=',mtcr,')'
     &                 ,' (MAX_NUM_NTCR@moddas.f=',MAX_NUM_NTCR,')'
                  ErrID = 'L:20825/R:tcross/F:tallsm2.f'
                  call ErrWrite(ErrID,ErrCha)
               endif

               if( ntcn > MAX_NUM_KTCR ) then
                  write(ErrCha,'(a,a,i5,a,a,i5,a)')
     &                 'sub.tcross@tallsm2.f'
     &                    //' ?dimension over das_ktcr?'
     &                    //' ntcn > MAX_NUM_KTCR'
     &                 ,' (ntcn=',ntcn,')'
     &                 ,' (MAX_NUM_KTCR@moddas.f=',MAX_NUM_KTCR,')'
                  ErrID = 'L:20836/R:tcross/F:tallsm2.f'
                  call ErrWrite(ErrID,ErrCha)
               endif

                  if( ierr .ne. 0 ) return
                  if( jpn  .eq. 3 ) goto 800
                  if( ntcn .eq. 0 ) goto 996

            else if( imesh .eq. 2 ) then
               nzerocheck=1  ! allow nz = 0, T.Sato 2018/3/6
               call trzmesh(jsn,jsi,dsin,idsi,ill,ilf,
     &                      jpn,chin,chlw,chcm,i1,i2,i3,i4,ierr,
     &                      rzx0,rzy0,
     &                      irtp,inr,rmin,rmax,rdel,istrg,
     &                      iztp,inz,zmin,zmax,zdel,istzg)
               nzerocheck=0 ! allow nz = 0, T.Sato 2018/3/6

                  if( ierr .ne. 0 ) return
                  if( jpn  .eq. 3 ) goto 800
                  if( irtp .lt. 0 ) goto 996
                  if( iztp .lt. 0 ) goto 996

            else if( imesh .eq. 3 ) then
               nzerocheck=1  ! allow nz = 0, T.Sato 2018/3/6
               call txymesh(jsn,jsi,dsin,idsi,ill,ilf,
     &                      jpn,chin,chlw,chcm,i1,i2,i3,i4,ierr,
     &                      ixtp,inx,xmin,xmax,xdel,istxg,
     &                      iytp,iny,ymin,ymax,ydel,istyg,
     &                      iztp,inz,zmin,zmax,zdel,istzg)
               nzerocheck=0 ! allow nz = 0, T.Sato 2018/3/6

                  if( ierr .ne. 0 ) return
                  if( jpn  .eq. 3 ) goto 800
                  if( ixtp .lt. 0 ) goto 996
                  if( iytp .lt. 0 ) goto 996
                  if( iztp .lt. 0 ) goto 996

            end if

                  goto 150

*-----------------------------------------------------------------------
*        particle name
*-----------------------------------------------------------------------

         else if( ipm .eq. 2 ) then

  400       continue

               ic = jnumc(chlw,ic,icl)

               if( ic .gt. icl ) then

                  icl = jnumc(chlw,icl+2,i3)

                  if( icl .le. i3 ) goto 200

                  goto 140

               end if

*-----------------------------------------------------------------------

            call rdpname(ic,icl,chlw,istyp,inkf0,jstyp,jnkf0,ierr)

               if( ierr .eq. 994 ) goto 994
               if( ierr .eq. 998 ) goto 997

*-----------------------------------------------------------------------

               inpat = inpat + 1

               if( inpat .gt. mxpart ) goto 995

                  iptyp(inpat) = istyp
                  ipnkf(inpat) = inkf0
                  ipsub(inpat) = isubt  ! kitamura22/03/31

               if( istyp .lt. 0 ) then

                  do i = 1, -istyp

                     imtyp(inpat,i) = jstyp(i)
                     imnkf(inpat,i) = jnkf0(i)

                  end do

               end if

               goto 400

*-----------------------------------------------------------------------
*        energy mesh
*-----------------------------------------------------------------------

         else if( ipm .eq. 3 ) then

               call onum(chlw,ic,icl,cvvv,ierr)

               if( ierr .ne. 0 ) goto 997

               if( chlw(icl+1:icl+1) .eq. ';' ) goto 993

               ietp = nint( cvvv )

               call getmsh(jsn,jsi,dsin,idsi,ill,ilf,
