*-----------------------------------------------------------------------
*        mxnuclei
*-----------------------------------------------------------------------
         else if( ipm .eq. 51 ) then

               call onum(chlw,ic,icl,cvvv,ierr)

               if( ierr .ne. 0 ) goto 997

               imxnuc = nint( cvvv )

               icl = jnumc(chlw,icl+2,i3)

               if( icl .le. i3 ) goto 200

*-----------------------------------------------------------------------
*        samepage       nais 2023/01/6
*-----------------------------------------------------------------------

         else if( ipm .eq. 52 ) then

            call setsamepage(inpgi,ipgis,ic,chlw,icl, ierr)

            if( ierr .eq. 1 ) goto 1045
            if( ierr .eq. 2 ) goto 1046

            icl = jnumc(chlw,icl+2,i3)

            if( icl .le. i3 ) goto 200

*-----------------------------------------------------------------------

         end if

            goto 140

*-----------------------------------------------------------------------
*     check
*-----------------------------------------------------------------------

  800 continue

      if( ischn(7) .eq. 0 ) then

         if( imesh .eq. 1 ) then

            title = '[t-yield] in region mesh'
            titll = 24

         else if( imesh .eq. 2 ) then

            title = '[t-yield] in r-z mesh'
            titll = 21

         else if( imesh .eq. 3 ) then

            title = '[t-yield] in xyz mesh'
            titll = 21

         else if( imesh .eq. 4 ) then
            title = '[t-yield] in tetra mesh'
            titll = 23

         end if

      end if

      if( ischn(1) .eq. 0 ) then

         m_err = 'Mesh is not defined in tally '//tname
         ErrCha = ''
         ErrID = 'L:24532/R:tyield/F:tallsm2.f'
         goto 999

      else if( inaxi .eq. 0 ) then

         m_err = 'Axis is not defined in tally '//tname
         ErrCha = ''
         ErrID = 'L:24539/R:tyield/F:tallsm2.f'
         goto 999

      else if( infil .eq. 0 ) then

         m_err = 'File is not defined in tally '//tname
         ErrCha = ''
         ErrID = 'L:24546/R:tyield/F:tallsm2.f'
         goto 999

      else if( inaxi .ne. infil ) then

         m_err = 'Number of Axis and File is different in tally '//tname
         ErrCha = ''
         ErrID = 'L:24553/R:tyield/F:tallsm2.f'
         goto 999

      else if( itsanf > 1 ) then

         m_err = 'Double definition of sangel is found in tally '//tname
         ErrCha = ''
         ErrID = 'L:24560/R:tyield/F:tallsm2.f'
         goto 999

      end if

      do i = 1, inaxi

         if( lrshow .eq. 0 ) then

            if( ( iaxis(i) .eq. 9 .or. iaxis(i) .eq. 10 .or.
     &            iaxis(i) .eq. 11 ) .and. imesh .ne. 3 ) then

               m_err = 'Axis is xy, yz, or zx, '//
     &                 'but mesh is not xyz in tally '//tname
               ErrCha = ''
               ErrID = 'L:24575/R:tyield/F:tallsm2.f'
               goto 999

            end if

         end if

         if( iaxis(i) .eq. 2 .and. imesh .ne. 1 ) then

            m_err = 'Axis is reg but mesh is not reg in tally '//tname
            ErrCha = ''
            ErrID = 'L:24586/R:tyield/F:tallsm2.f'
            goto 999

         else if( iaxis(i) .eq. 14 .and. imesh .ne. 4 ) then
            m_err = 'Axis is tet but mesh is not tet in tally '//tname
            ErrCha = ''
            ErrID = 'L:24592/R:tyield/F:tallsm2.f'
            goto 999

         else if( iaxis(i).eq.13.and.(imesh.ne.1.and.imesh.ne.4)) then

            m_err = 'Axis is dchain but mesh is not reg in tally '
     &              //tname
            ErrCha = ''
            ErrID = 'L:24600/R:tyield/F:tallsm2.f'
            goto 999

         else if( iaxis(i) .eq. 13 .and. iunt .ne. 1 ) then

            m_err = 'Axis is dchain but unit is not 1 in tally '
     &              //tname
            ErrCha = ''
            ErrID = 'L:24608/R:tyield/F:tallsm2.f'
            goto 999

         else if( iaxis(i) .eq. 3 .and. imesh .ne. 3 ) then

            m_err = 'Axis is x but mesh is not xyz in tally '//tname
            ErrCha = ''
            ErrID = 'L:24615/R:tyield/F:tallsm2.f'
            goto 999

         else if( iaxis(i) .eq. 4 .and. imesh .ne. 3 ) then

            m_err = 'Axis is y but mesh is not xyz in tally '//tname
            ErrCha = ''
            ErrID = 'L:24622/R:tyield/F:tallsm2.f'
            goto 999

         else if( iaxis(i) .eq. 5 .and. imesh .eq. 1 ) then

            m_err = 'Axis is z but mesh is reg in tally '//tname
            ErrCha = ''
            ErrID = 'L:24629/R:tyield/F:tallsm2.f'
            goto 999

         else if( iaxis(i) .eq. 6 .and. imesh .ne. 2 ) then

            m_err = 'Axis is r but mesh is not r-z in tally '//tname
            ErrCha = ''
            ErrID = 'L:24636/R:tyield/F:tallsm2.f'
            goto 999

         else if( ( iaxis(i) .eq. 7 .or. iaxis(i) .eq. 8 ) .and.
     &              inucl .gt. 0 ) then

            m_err = 'Axis is charge or chart'//
     &              ' but nucleus is restricted in tally '//tname
            ErrCha = ''
            ErrID = 'L:24645/R:tyield/F:tallsm2.f'
            goto 999

         else if( ( iaxis(i) .eq. 1 .or. iaxis(i) .eq. 13 ) .and.
     &              imasi .gt. 0 ) then

            m_err = 'Axis is dchain or mass,'//
     &              ' but isotope is restricted in tally '//tname
            ErrCha = ''
            ErrID = 'L:24654/R:tyield/F:tallsm2.f'
            goto 999

         else if( iaxis(i) .eq. 12 .and. imesh .ne. 2 ) then

            m_err = 'Axis is rz,'//
     &              ' but mesh is not r-z in tally '//tname
            ErrCha = ''
            ErrID = 'L:24662/R:tyield/F:tallsm2.f'
            goto 999

         else if( iaxis(i) .eq. 12 .and.
     &           ( irtp .ne. 2 .and. irtp .ne. 4 ) ) then

            m_err = 'Axis is rz,'//
     &              ' but r mesh type is not 2 or 4 in tally '//tname
            ErrCha = ''
            ErrID = 'L:24671/R:tyield/F:tallsm2.f'
            goto 999

         else if( iaxis(i) .eq. 12 .and.
     &           ( iztp .ne. 2 .and. iztp .ne. 4 ) ) then

            m_err = 'Axis is rz,'//
     &              ' but z mesh type is not 2 or 4 in tally '//tname
            ErrCha = ''
            ErrID = 'L:24680/R:tyield/F:tallsm2.f'
            goto 999

         else if( ( iaxis(i) .eq. 9 .or. iaxis(i) .eq. 11 ) .and.
     &           ( ixtp .ne. 2 .and. ixtp .ne. 4 ) ) then

            m_err = 'Axis is xy or zx,'//
     &              ' but x mesh type is not 2 or 4 in tally '//tname
            ErrCha = ''
            ErrID = 'L:24689/R:tyield/F:tallsm2.f'
            goto 999

         else if( ( iaxis(i) .eq. 10 .or. iaxis(i) .eq. 11 ) .and.
     &           ( iztp .ne. 2 .and. iztp .ne. 4 ) ) then

            m_err = 'Axis is yz or zx,'//
     &              ' but z mesh type is not 2 or 4 in tally '//tname
            ErrCha = ''
            ErrID = 'L:24698/R:tyield/F:tallsm2.f'
            goto 999

         else if( ( iaxis(i) .eq. 10 .or. iaxis(i) .eq. 9 ) .and.
     &           ( iytp .ne. 2 .and. iytp .ne. 4 ) ) then

            m_err = 'Axis is xy or yz,'//
     &              ' but y mesh type is not 2 or 4 in tally '//tname
            ErrCha = ''
            ErrID = 'L:24707/R:tyield/F:tallsm2.f'
            goto 999

         else if( iaxis(i) .eq. 1 .and. inucl .gt. 1 ) then

            do k = 1, inucl
               do j = k + 1, inucl

                  if( isnuc(nnucl-1+k)/1000 .eq.
     &                isnuc(nnucl-1+j)/1000 ) then

                     m_err = 'Axis is mass,'//
     &               ' and there is the same nucleus in tally '//tname
                     ErrCha = ''
                     ErrID = 'L:24721/R:tyield/F:tallsm2.f'
                     goto 999

                  end if

               end do
            end do

