                  itmsh(itnm) = imesh

         if( imesh .eq. 1 ) then

                  itrgn(itnm) = ntrn
                  itrgm(itnm) = mtrn
                  itrnv(itnm) = nvol

            if( ntrn .gt. 0 ) then

                  call moddas_reallocate_int(
     &                    itlmax, itnm, mtrn, itreg, idas_itreg)
                  idas_itreg(itreg(itnm):itreg(itnm)+mtrn-1)
     &                      = idas_itreg_temporary(1:mtrn)
                  call moddas_deallocate_int(idas_itreg_temporary)
                  itsmn(itnm) = itsmn(itnm)
     &                        + ( mtrn + mod(mtrn,2) ) / 2

            end if

            if( nvol .gt. 0 ) then

                  itriv(itnm) = ivl
                  itsmn(itnm) = itsmn(itnm)
     &                        + ( nvol + mod(nvol,2) ) / 2

                  itrrv(itnm) = irvl
                  itsmn(itnm) = itsmn(itnm) + nvol

            end if

         else if( imesh .eq. 4 ) then

                  itrgn(itnm) = ntrn
                  itrgm(itnm) = mtrn
                  itrnv(itnm) = 0

            if( ntrn .gt. 0 ) then

                  call moddas_reallocate_int(
     &                    itlmax, itnm, mtrn, itreg, idas_itreg)
                  idas_itreg(itreg(itnm):itreg(itnm)+mtrn-1)
     &                      = idas_itreg_temporary(1:mtrn)

            end if

