*-----------------------------------------------------------------------
                  do i = 1, inaxi ! frtati 2022/04/20
                    if( iaxis(i).eq.8 .or. iaxis(i).eq.13 ) then
                      if( imxnuc.eq.-1 ) then ! frtati 2022/03/25
                        itnzn(itnm) = 3000 ! default value
                      else if( imxnuc.gt.0 ) then
                        itnzn(itnm) = imxnuc + 1
                      else
                        itnzn(itnm) = 0
                      end if
                    else
                      itnzn(itnm) = 0
                    end if
                  end do

*-----------------------------------------------------------------------
*        xy, yz, zx, rz storage region
*-----------------------------------------------------------------------

                     mxyz = 1
                     mrzr = 1
                     mrzz = 1

                  do i = 1, inaxi

                     if( iaxis(i) .eq. 9 ) then

                        if( inx .gt. mxyz ) mxyz = inx
                        if( iny .gt. mxyz ) mxyz = iny

                     else if( iaxis(i) .eq. 10 ) then

                        if( iny .gt. mxyz ) mxyz = iny
                        if( inz .gt. mxyz ) mxyz = inz

                     else if( iaxis(i) .eq. 11 ) then

                        if( inx .gt. mxyz ) mxyz = inx
                        if( inz .gt. mxyz ) mxyz = inz

                     else if( iaxis(i) .eq. 12 ) then

                        mrzr = inr
                        mrzz = inz

                     end if

                  end do

                     itnfn(itnm) = mxyz
                     itnfr(itnm) = mrzr
                     itnfz(itnm) = mrzz

*-----------------------------------------------------------------------
*        iz, in storage region
*-----------------------------------------------------------------------

                        izz = 1
                        inn = 1

               do i = 1, inaxi

                  if( iaxis(i) .eq. 13 .or. iaxis(i) .eq. 8 ) then

                        izz = maxpt
                        inn = maxnt

                  else if( iaxis(i) .eq. 7 ) then

                        izz = maxpt

                  else if( iaxis(i) .eq. 1 ) then

                     if( inucl .eq. 0 ) then

                        if( inaxi .eq. 1 ) then

                           izz = 1
                           inn = maxpt + maxnt

                        else

                           izz = maxpt
                           inn = maxnt

                        end if

                     else if( inucl .gt. 0 ) then

                        izz = max( izz, inucl )
                        inn = maxnt

                     end if

                  else

                        izz = max( izz, inucl )

                  end if

               end do

                      if( itnzn(itnm).eq.0 ) then ! frtati 2022/02/18

                        itndz(itnm) = izz
                        itndn(itnm) = inn
                        itndm(itnm) = 2

                      else
                        itndz(itnm) = itnzn(itnm)
                        itndn(itnm) = 1
                        itndm(itnm) = 0
                      end if

*-----------------------------------------------------------------------
*        jz, jn -> kz, kn tranfer
*-----------------------------------------------------------------------

               do jz = 1, maxpt
               do jn = 1, maxnt

                        kz = izz + 1
                        kn = inn + 1

                  if( izz. eq. maxpt .and. inn .eq. maxnt ) then

                        kz = jz
                        kn = jn

                  else if( izz .eq. 1 .and.
     &                     inn .eq. maxpt + maxnt ) then

                        kz = 1
                        kn = jz + jn

                  else if( inucl .gt. 0 .and. inn .eq. maxnt ) then

                        kn = jn

                     do i = 1, inucl

                        iz = isnuc(nnucl-1+i) / 1000

                        if( jz .eq. iz ) kz = i

                     end do

                  else if( izz. eq. maxpt .and. inn .eq. 1 ) then

                        kz = jz
                        kn = 1

                  else if( inucl .gt. 0 .and. inn .eq. 1 ) then

                        kn = 1

                     do i = 1, inucl

                        iz = isnuc(nnucl-1+i) / 1000
                        ia = isnuc(nnucl-1+i) - iz * 1000

                        if( jz .eq. iz .and.
     &                    ( ( ia .eq. 0 ) .or.
     &                      ( ia .gt. 0 .and.
     &                        jn .eq. ia - iz ) ) ) then

                              kz = i

                        end if

                     end do

                  else if( izz .eq. 1 .and. inn .eq. 1 ) then

                        kz = 1
                        kn = 1

                  end if

                     ikzz(jz,jn) = kz
                     iknn(jz,jn) = kn

               end do
               end do

*-----------------------------------------------------------------------

                  maxik = maxpt * maxnt

                  itnkz(itnm) = ( mmmax - 1 ) * 2 + 1
                  mmmax = mmmax + ( maxik + mod(maxik,2) ) / 2

                  itsmn(itnm) = itsmn(itnm)
     &                        + ( maxik + mod(maxik,2) ) / 2

                  if( mmmax .gt. mdas ) goto 950

                  k = 0

               do j = 1, maxnt
               do i = 1, maxpt

                  k = k + 1

                  idas( itnkz(itnm) + k - 1 ) = ikzz(i,j)

               end do
               end do

                  itnkn(itnm) = ( mmmax - 1 ) * 2 + 1
                  mmmax = mmmax + ( maxik + mod(maxik,2) ) / 2

                  itsmn(itnm) = itsmn(itnm)
     &                        + ( maxik + mod(maxik,2) ) / 2

                  if( mmmax .gt. mdas ) goto 950

                  k = 0

               do j = 1, maxnt
               do i = 1, maxpt

                  k = k + 1

                  idas( itnkn(itnm) + k - 1 ) = iknn(i,j)

               end do
               end do

*-----------------------------------------------------------------------
*        samepage
*-----------------------------------------------------------------------
                  itpgn(itnm) = inpgi

               do i = 1, inpgi

                  itpgs(itnm,i) = ipgis(i)

               end do

*-----------------------------------------------------------------------

      return

*-----------------------------------------------------------------------
*     errors
*-----------------------------------------------------------------------

  976    m_err = 'counter should be from -9999 to 9999'
         ErrCha = ''
         ErrID = 'L:25600/R:tyield/F:tallsm2.f'
         goto 999

  950    write(dkam,'(i9)') mdas
         m_err = 'Total tally storage number exceeds mdas ='//dkam
         ErrCha = ''
         ErrID = 'L:25606/R:tyield/F:tallsm2.f'
         goto 999

  980    m_err = 'unit should be 1 or 2 in tally '//tname
         ErrCha = ''
         ErrID = 'L:25611/R:tyield/F:tallsm2.f'
         goto 999

  978    m_err = 'ndata should be 0, 1, 2 or 3 in tally '//tname
         ErrCha = ''
         ErrID = 'L:25616/R:tyield/F:tallsm2.f'
         goto 999

  979    m_err = 'Description of material parameter is wrong in tally '
     &            //tname
         ErrCha = ''
         ErrID = 'L:25622/R:tyield/F:tallsm2.f'
         goto 999

  975    m_err = '1H or Z=A cannot be specified for nucleus in tally '
     &            //tname
         ErrCha = ''
         ErrID = 'L:25628/R:tyield/F:tallsm2.f'
         goto 999

  981    m_err = 'Description of nucleus parameter is wrong in tally '
     &            //tname
         ErrCha = ''
         ErrID = 'L:25634/R:tyield/F:tallsm2.f'
         goto 999

  982    m_err = 'Description of mother parameter is wrong in tally '
     &            //tname
         ErrCha = ''
         ErrID = 'L:25640/R:tyield/F:tallsm2.f'
         goto 999

  983    m_err = '2D-type should be 1-7 in tally '//tname
         ErrCha = ''
         ErrID = 'L:25645/R:tyield/F:tallsm2.f'
         goto 999

  986    write(dkam,'(i5)') itlmax
         m_err = 'Total tally number exceeds itlmax = '//dkam
         ErrCha = ''
         ErrID = 'L:25651/R:tyield/F:tallsm2.f'
         goto 999

  987    m_err = 'Unknown parameter in tally '//tname
         ErrCha = ''
         ErrID = 'L:25656/R:tyield/F:tallsm2.f'
         goto 999

  988    m_err = 'special should be positive in tally '//tname
         ErrCha = ''
         ErrID = 'L:25661/R:tyield/F:tallsm2.f'
         goto 999

  989    m_err = 'Double definition of the parameter in tally '//tname
         ErrCha = ''
         ErrID = 'L:25666/R:tyield/F:tallsm2.f'
         goto 999

  990    m_err = 'Only one axis in '//tname
         ErrCha = ''
         ErrID = 'L:25671/R:tyield/F:tallsm2.f'
         goto 999

  991    m_err = 'Only one axis in '//tname
         ErrCha = ''
         ErrID = 'L:25676/R:tyield/F:tallsm2.f'
         goto 999

  992    m_err = 'Unknown axis name in tally '//tname
         ErrCha = ''
         ErrID = 'L:25681/R:tyield/F:tallsm2.f'
         goto 999

  993    m_err = 'In this line, [ ; ] cannot be used.'
         ErrCha = ''
         ErrID = 'L:25686/R:tyield/F:tallsm2.f'
         goto 999

  994    m_err = 'Name of particle is wrong in tally '//tname
         ErrCha = ''
         ErrID = 'L:25691/R:tyield/F:tallsm2.f'
         goto 999

cfrtati 2021/10/05 6 -> mxpart
  995    m_err = 'Number of particles is larger than mxpart in '//tname
         ErrCha = ''
         ErrID = 'L:25697/R:tyield/F:tallsm2.f'
         goto 999

  996    m_err = 'Description of mesh is wrong in tally '//tname
         ErrCha = ''
         ErrID = 'L:25702/R:tyield/F:tallsm2.f'
         goto 999

  997    m_err = 'Description of parameter is wrong in tally '//tname
         ErrCha = ''
         ErrID = 'L:25707/R:tyield/F:tallsm2.f'
         goto 999

 1045    m_err = 'Too many samepage in tally '//tname
         ErrCha = ''
         ErrID = 'L:25712/R:tyield/F:tallsm2.f'
         goto 999

 1046    m_err = 'samepage should be wwg, reg,eng,t,xy,yz,zx,x,y,z'
     &           //' in tally '//tname
         ErrCha = ''
         ErrID = 'L:25718/R:tyield/F:tallsm2.f'
         goto 999

  998    m_err = 'Unknown mesh parameter in tally '//tname
         ErrCha = ''
         ErrID = 'L:25723/R:tyield/F:tallsm2.f'
         goto 999

*-----------------------------------------------------------------------

  999 continue

         l_err = ill(jsn)
         k_err = jsn
         ierr  = 1

*-----------------------------------------------------------------------

      return
      end


************************************************************************
*                                                                      *
      subroutine theat(jsn,jsi,dsin,idsi,ill,ilf,
     &                 jpn,chin,chlw,chcm,i1,i2,i3,i4,ierr)
*                                                                      *
*       read [t-heat] section of input files                           *
*       modified by K.Niita on 2009/10/27                              *
*                                                                      *
************************************************************************
      use sangelmod, only: itsanf
      use partmod ! frtati 2021/10/05
      use moddas
      use moddas_mesh
      use moddas_region
      use moddas_tally

      implicit real*8 (a-h,o-z)

      parameter(icsu=49) ! nais 2023/01/06

      include 'param.inc'
      include 'param01.inc' ! frtati 2021/10/05
      include 'err.inc'

*-----------------------------------------------------------------------

      common /tall00/ itnm, ital(itlmax), itals(itlmax), italm(itlmax)
      common /tall01/ itmsh(itlmax), itunt(itlmax), itspc(itlmax),
     &                itout(itlmax), ittwo(itlmax)

      common /tall02/ itrgn(itlmax), itrgm(itlmax), itreg(itlmax)
      common /tall25/ itrnv(itlmax), itriv(itlmax), itrrv(itlmax)

      common /tall03/ itrty(itlmax), itrnm(itlmax), itrrg(itlmax),
     &                rtrmi(itlmax), rtrma(itlmax), rtrdl(itlmax)
      common /tall04/ itxty(itlmax), itxnm(itlmax), itxrg(itlmax),
     &                rtxmi(itlmax), rtxma(itlmax), rtxdl(itlmax)
      common /tall05/ ityty(itlmax), itynm(itlmax), ityrg(itlmax),
     &                rtymi(itlmax), rtyma(itlmax), rtydl(itlmax)
      common /tall06/ itzty(itlmax), itznm(itlmax), itzrg(itlmax),
     &                rtzmi(itlmax), rtzma(itlmax), rtzdl(itlmax)
      common /tall07/ itety(itlmax), itenm(itlmax), iterg(itlmax),
     &                rtemi(itlmax), rtema(itlmax), rtedl(itlmax)

      common /tall08/ rtrx0(itlmax), rtry0(itlmax)

      common /tall10/ itaxn(itlmax), itaxs(itlmax,6)
      common /tall11/ itfln(itlmax), itfll(itlmax,6), ctfln(itlmax,6)
      character ctfln*100

      common /tall14/ ittll(itlmax), ittle(itlmax)
      character ittle*80

      common /tall15/ itanl(itlmax), itang(itlmax)
      character itang*200

      common /tall27/ itaxl(itlmax), itaxt(itlmax),
     &                itayl(itlmax), itayt(itlmax),
     &                itazl(itlmax), itazt(itlmax)
      character itaxt*200, itayt*200, itazt*200

      common /tall17/ itndy(itlmax)

      common /tall19/ itsmn(itlmax), itstm(itlmax)

      common /tall21/ rtfac(itlmax)
      common /tall22/ itmcn(itlmax), itmtn(itlmax), itmtt(itlmax)

      common /tall28/ itgsh(itlmax)
      common /tall29/ itrsh(itlmax)
      common /tall31/ iterl(itlmax)

      common /tall32/ itelc(itlmax)
      common /tall34/ itvm(itlmax)
      common /tall35/ iteps(itlmax)
      common /tall36/ itdpo(itlmax)
      common /tall37/ itcnt(9,itlmax)

      common /tall38/ itres(itlmax)
      common /tall39/ rtwid(itlmax)
      common /tall46/ itmtr(itlmax,4), rtmtr(itlmax,13)

      common /tall49/ itglt(itlmax)

      common /tall58/ iterr(itlmax)

!OBINATA: for resfile
      common /tall59/ irfll(itlmax), crfln(itlmax), itrff(itlmax)
      character crfln*100
      character irfile*100

      common /tall60/ itger(itlmax)
      common /tall63/ itbmp(itlmax)
      common /tall64/ itvtk(itlmax),itvtkfmt(itlmax)

      common /tall67/ itstd(itlmax), rtstd(itlmax)

      common /tall82/ itcnth(9,itlmax)
      dimension icounth(9)

! 20230106 nais samepage
      common /tall90/ itpgn(itlmax), itpgs(itlmax,6)

      dimension idas(1)
      equivalence ( das, idas )

*-----------------------------------------------------------------------

      character m_err*200
      common /error/ m_err, l_err, k_err

*-----------------------------------------------------------------------

      character title*80
      character angelp*200
      character cxtxt*200
      character cytxt*200
      character cztxt*200

*-----------------------------------------------------------------------

      dimension lschn(icsu), ischn(icsu)
      character schan(icsu)*8


      data ( schan(i), i = 1, icsu ) /
     &    'mesh    ','part    ','output  ','unit    ','axis    ',
     &    'file    ','title   ','angel   ','2d-type ','factor  ',
     &    'material','x-txt   ','y-txt   ','z-txt   ','gshow   ',
     &    'rshow   ','iechrl  ','electron','volmat  ','epsout  ',
     &    'e-type  ','deposit ','ctmin(1)','ctmax(1)','ctmin(2)',
     &    'ctmax(2)','ctmin(3)','ctmax(3)','resol   ','width   ',
     &    'trcl    ','*trcl   ','gslat   ','err2d'   ,'resfile ',
     &    'ginfo   ','bmpout  ','vtkout  ','vtkfmt  ','stdcut  ',
     &    'sangel  ','chmin(1)','chmax(1)','chmin(2)','chmax(2)',
     &    'chmin(3)','chmax(3)','maxangel','samepage'/

      data ( lschn(i), i = 1, icsu ) /
     &     4,         4,         6,         4,         4,
     &     4,         5,         5,         7,         6,
     &     8,         5,         5,         5,         5,
     &     5,         6,         8,         6,         6,
     &     6,         7,         8,         8,         8,
     &     8,         8,         8,         5,         5,
     &     4,         5,         5,         5,         7,
     &     5,         6,         6,         6,         6,
     &     6,         8,         8,         8,         8,
     &     8,         8,         8,         8/

*-----------------------------------------------------------------------

cfrtati 2021/10/05 6 -> mxpart
      dimension iptyp(mxpart), ipnkf(mxpart)
      dimension imtyp(mxpart,mxpart), imnkf(mxpart,mxpart)
      dimension jstyp(mxpart), jnkf0(mxpart)

      common /subtra/ isubt, ipsub(mxpart)  ! kitamura22/03/31

      dimension iaxis(6)
      character ifile(6)*100
      dimension lfile(6)

      dimension ipgis(6)   ! samepage nais 2023/01/06



*-----------------------------------------------------------------------

      logical deqn4

*-----------------------------------------------------------------------

      character chin*200, chlw*200, chcm*200
      character chlc*200

      character dsin(0:9)*200
      dimension idsi(0:9)

      dimension ill(0:9), ilf(0:9)

      character dkam*9

      character tname*8
      data      tname /'[t-heat]'/

      dimension icount(9)
      dimension vtrs(13)

      integer isumtalRead

*-----------------------------------------------------------------------

            ierr  = 0

            iout  = 2
            iunt  = 1
            imate = 0
            jmate = 1
            inpat = 0
            inaxi = 0
            infil = 0
            idtyp = 3

            langel = 0
            itsanf = 0
            lxtxt  = 0
            lytxt  = 0
            lztxt  = 0
            lgshow = 0
            lrshow = 0
            iechrl = 72
            matvol = 9
            ieps   = 0
            ibmp   = 0
            ivtk   = 0
            ivtkfmt= 0
            idepo  = 0
            igkst  = 0
            idtt   = 0
            ktrs   = 0
            igslt  = -1
            iter2  = 0
            lrfile = 0 !OBINATA
            irfflg = 0 !OBINATA
            imxang = 0 ! frtati 2021/10/05

            icount(1) = 0
            icount(2) = 0
            icount(3) = 0
            icount(4) = -9999
            icount(5) =  9999
            icount(6) = -9999
            icount(7) =  9999
            icount(8) = -9999
            icount(9) =  9999
            icounth(1) = 0
            icounth(2) = 0
            icounth(3) = 0
            icounth(4) = -9999
            icounth(5) =  9999
            icounth(6) = -9999
            icounth(7) =  9999
            icounth(8) = -9999
            icounth(9) =  9999

            ielct  = 0
            imesh  = 0

            ireso = 1
            width = 0.5

            rfact = 1.0

         do i = 1, icsu

            ischn(i) = 0

         end do

            infog = 0

         inpgi = 0   ! samepage 2023/01/06

       isumtalRead = 0

            stdcut = -1.0

*-----------------------------------------------------------------------
*     read one line from jsi
*-----------------------------------------------------------------------

  140 continue

            call readl(jsn,jsi,dsin,idsi,ill,ilf,'#!$',
     &                 jpn,chin,chlw,chcm,i1,i2,i3,i4,iskip,ierr)

               if( ierr .ne. 0 ) return
               if( jpn  .eq. 3 ) goto 800

               if( iskip .ne. 0 ) goto 140

  150 continue

               if( ierr .ne. 0 ) return
               if( jpn  .eq. 3 ) goto 800

*-----------------------------------------------------------------------
*        end of the section
*-----------------------------------------------------------------------

            if( chlw(i1:i1) .eq. '[' ) then

               jpn = 1
               goto 800

            end if

*-----------------------------------------------------------------------
*        identify the parameters
*-----------------------------------------------------------------------

            icl = i1

!-----------------------------------------------------------------------
!        sumtally sub section
!-----------------------------------------------------------------------
      if ( chlw(i1:i3) .eq. 'sumtally start' ) then
       isumtalRead = 1
       call read_sumtal(jsn,jsi,dsin,idsi,ill,ilf,
     &                 jpn,chin,chlw,chcm,i1,i2,i3,i4,iskip,ierr)
       if( ierr .ne. 0 ) return
       if( jpn == 3 ) goto 800   ! 'q:'
       if( jpn == 1 ) goto 800   ! end of the section
       go to 140
      end if

  200    continue

            chlc = chlw
            call chcomp(chlc,icl,i3,i5)

         do i = 1, icsu

            il = icl + lschn(i) - 1

            if( chlc(icl:il) .eq. schan(i)(1:lschn(i)) ) goto 100

         end do

               goto 987

*-----------------------------------------------------------------------
*        read value of parameters
*-----------------------------------------------------------------------

  100    continue

               ipm = i

               ischn( ipm ) = ischn( ipm ) + 1

            if( ipm .ne. 5 .and. ipm .ne. 6 .and.
     &          ipm .ne. 2 .and. ipm .ne. 35 .and.
     &          ischn( ipm ) .gt. 1 ) goto 989

               ic = inumc(chlw,il+1,i3,'=') + 1
               ic = jnumc(chlw,ic,i3)

               if( ic .gt. i3 ) goto 997

               icl = inumc(chlw,ic,i3,';') - 1

*-----------------------------------------------------------------------
*        mesh = region, r-z, or xyz
*-----------------------------------------------------------------------

         if( ipm .eq. 1 ) then

            if( chlw(ic:ic+2) .eq. 'reg' ) then

               imesh = 1

            else if( chlw(ic:ic+2) .eq. 'r-z' ) then

               imesh = 2

            else if( chlw(ic:ic+2) .eq. 'xyz' ) then

               imesh = 3

            else

               goto 998

            end if

            if( chlw(icl+1:icl+1) .eq. ';' ) goto 993

            if( imesh .eq. 1 ) then

               call moddas_allocate_int(
     &                 MAX_NUM_ITREG, idas_itreg_temporary)

               ndsm = 1
               call tregion(1,jsn,jsi,dsin,idsi,ill,ilf,
     &                      jpn,chin,chlw,chcm,i1,i2,i3,i4,ierr,
     &                      ntrn,mtrn,ndsm,nvol,ivl,irvl,0
     &                      ,MAX_NUM_ITREG,idas_itreg_temporary)

               if( mtrn > MAX_NUM_ITREG ) then
                  write(ErrCha,'(a,a,i5,a,a,i5,a)')
     &                 'sub.theat@tallsm2.f'
     &                    //' ?dimension over idas_itreg_temporary?'
     &                    //' mtrn > MAX_NUM_ITREG'
     &                 ,' (mtrn=',mtrn,')'
     &                 ,' (MAX_NUM_ITREG@moddas.f=',MAX_NUM_ITREG,')'
                  ErrID = 'L:26136/R:theat/F:tallsm2.f'
                  call ErrWrite(ErrID,ErrCha)
               endif

                  if( ierr .ne. 0 ) return
                  if( jpn  .eq. 3 ) goto 800
                  if( ntrn .lt. -1 ) goto 996

            else if( imesh .eq. 2 ) then

               call trzmesh(jsn,jsi,dsin,idsi,ill,ilf,
     &                      jpn,chin,chlw,chcm,i1,i2,i3,i4,ierr,
     &                      rzx0,rzy0,
     &                      irtp,inr,rmin,rmax,rdel,istrg,
     &                      iztp,inz,zmin,zmax,zdel,istzg)

                  if( ierr .ne. 0 ) return
                  if( jpn  .eq. 3 ) goto 800
                  if( irtp .lt. 0 ) goto 996
                  if( iztp .lt. 0 ) goto 996

            else if( imesh .eq. 3 ) then

               call txymesh(jsn,jsi,dsin,idsi,ill,ilf,
     &                      jpn,chin,chlw,chcm,i1,i2,i3,i4,ierr,
     &                      ixtp,inx,xmin,xmax,xdel,istxg,
     &                      iytp,iny,ymin,ymax,ydel,istyg,
     &                      iztp,inz,zmin,zmax,zdel,istzg)

                  if( ierr .ne. 0 ) return
                  if( jpn  .eq. 3 ) goto 800
                  if( ixtp .lt. 0 ) goto 996
                  if( iytp .lt. 0 ) goto 996
                  if( iztp .lt. 0 ) goto 996

            end if

                  goto 150

*-----------------------------------------------------------------------
*        particle name
*-----------------------------------------------------------------------

         else if( ipm .eq. 2 ) then

  400       continue

               ic = jnumc(chlw,ic,icl)

               if( ic .gt. icl ) then

                  icl = jnumc(chlw,icl+2,i3)

                  if( icl .le. i3 ) goto 200

                  goto 140

               end if

*-----------------------------------------------------------------------

            call rdpname(ic,icl,chlw,istyp,inkf0,jstyp,jnkf0,ierr)

               if( ierr .eq. 994 ) goto 994
               if( ierr .eq. 998 ) goto 997

*-----------------------------------------------------------------------

               inpat = inpat + 1

               if( inpat .gt. mxpart ) goto 995

                  iptyp(inpat) = istyp
                  ipnkf(inpat) = inkf0
                  ipsub(inpat) = isubt  ! kitamura22/03/31

               if( istyp .lt. 0 ) then

                  do i = 1, -istyp

                     imtyp(inpat,i) = jstyp(i)
                     imnkf(inpat,i) = jnkf0(i)

                  end do

               end if

               goto 400

*-----------------------------------------------------------------------
*        material
*-----------------------------------------------------------------------

         else if( ipm .eq. 11 ) then

            if( chlw(ic:ic+2) .eq. 'all' ) then

                  imate = 0

            else if( deqn4( chlw(ic:ic) ) ) then

               call onum(chlw,ic,icl,cvvv,ierr)

               if( ierr .ne. 0 ) goto 979

                  imate = nint( cvvv )

               if( imate .lt. 0 ) then

                  imate = -imate
                  jmate = -1

               end if

               if( imate .eq. 0 ) goto 979

                  nsmte = itmtt(itnm+1)
                  call moddas_reallocate_int(
