            ErrID = 'L:27200/R:theat/F:tallsm2.f'
            goto 999

         else if( ( iaxis(i) .eq. 7 .or. iaxis(i) .eq. 8 ) .and.
     &           ( iytp .ne. 2 .and. iytp .ne. 4 ) ) then

            m_err = 'Axis is xy or yz,'//
     &              ' but y mesh type is not 2 or 4 in tally '//tname
            ErrCha = ''
            ErrID = 'L:27209/R:theat/F:tallsm2.f'
            goto 999

         end if

      end do

*-----------------------------------------------------------------------

      if ( ibmp .ne. 0 ) then

         if ( imesh .ne. 3 ) then

            m_err = 'Mesh should be xyz on bmpout in tally '//tname
            ErrCha = ''
            ErrID = 'L:27224/R:theat/F:tallsm2.f'
            goto 999

         end if

         do i = 1, inaxi

            if ( iaxis(i) .ne. 7 .and.
     &           iaxis(i) .ne. 8 .and.
     &           iaxis(i) .ne. 9 ) then

               m_err = 'Axis should be xy, yz or xz on bmpout'//
     &                 ' in tally '//tname
               ErrCha = ''
               ErrID = 'L:27238/R:theat/F:tallsm2.f'
               goto 999

            end if

         end do

      end if

*-----------------------------------------------------------------------

      if ( ivtk .ne. 0 ) then

         if ( imesh .ne. 3 ) then

            m_err = 'Mesh should be xyz on bmpout in tally '//tname
            ErrCha = ''
            ErrID = 'L:27255/R:theat/F:tallsm2.f'
            goto 999

         end if

         do i = 1, inaxi

            if ( iaxis(i) .ne. 7 .and.
     &           iaxis(i) .ne. 8 .and.
     &           iaxis(i) .ne. 9 ) then

               m_err = 'Axis should be xy, yz or xz on bmpout'//
     &                 ' in tally '//tname
               ErrCha = ''
               ErrID = 'L:27269/R:theat/F:tallsm2.f'
               goto 999

            end if

         end do

      end if

*-----------------------------------------------------------------------
*     summary
*-----------------------------------------------------------------------

                  itnm = itnm + 1

                  if( itnm .gt. itlmax ) goto 986

                  ital( itnm ) = 4

                  itsmn(itnm) = 0
                  itstm(itnm) = 0

                  itxnm(itnm) = 0
                  itynm(itnm) = 0
                  itznm(itnm) = 0

*-----------------------------------------------------------------------
*        title
*-----------------------------------------------------------------------

                  ittll(itnm) = titll
                  ittle(itnm) = title

*-----------------------------------------------------------------------
*        angel parameter
*-----------------------------------------------------------------------

               if( langel .gt. 0 ) then

                  itanl(itnm) = langel
                  itang(itnm) = angelp

               else

                  itanl(itnm) = 0

               end if

*-----------------------------------------------------------------------
*        x-txt parameter
*-----------------------------------------------------------------------

               if( lxtxt .gt. 0 ) then

                  itaxl(itnm) = lxtxt
                  itaxt(itnm) = cxtxt

               else

                  itaxl(itnm) = 0

               end if

*-----------------------------------------------------------------------
*        y-txt parameter
*-----------------------------------------------------------------------

               if( lytxt .gt. 0 ) then

                  itayl(itnm) = lytxt
                  itayt(itnm) = cytxt

               else

                  itayl(itnm) = 0

               end if

*-----------------------------------------------------------------------
*        z-txt parameter
*-----------------------------------------------------------------------

               if( lztxt .gt. 0 ) then

                  itazl(itnm) = lztxt
                  itazt(itnm) = cztxt

               else

                  itazl(itnm) = 0

               end if

*-----------------------------------------------------------------------
*        gshow parameter
*-----------------------------------------------------------------------

               if( lgshow .gt. 0 ) then

                  itgsh(itnm) = min(5,lgshow)  ! T.Sato 2019/02/20

               else

                  itgsh(itnm) = 0

               end if

*-----------------------------------------------------------------------
*        gslat parameter
*-----------------------------------------------------------------------
                  itglt(itnm) = igslt

*-----------------------------------------------------------------------
*        rshow parameter
*-----------------------------------------------------------------------

                  itrsh(itnm) = min(4,lrshow)

*-----------------------------------------------------------------------
*        mesh
*-----------------------------------------------------------------------

                  itmsh(itnm) = imesh

         if( imesh .eq. 1 ) then

                  itrgn(itnm) = ntrn
                  itrgm(itnm) = mtrn
                  itrnv(itnm) = nvol

            if( ntrn .gt. 0 ) then

                  call moddas_reallocate_int(
     &                    itlmax, itnm, mtrn, itreg, idas_itreg)
                  idas_itreg(itreg(itnm):itreg(itnm)+mtrn-1)
     &                      = idas_itreg_temporary(1:mtrn)
                  call moddas_deallocate_int(idas_itreg_temporary)
                  itsmn(itnm) = itsmn(itnm)
     &                        + ( mtrn + mod(mtrn,2) ) / 2

            end if

            if( nvol .gt. 0 ) then

                  itriv(itnm) = ivl
                  itsmn(itnm) = itsmn(itnm)
     &                        + ( nvol + mod(nvol,2) ) / 2

                  itrrv(itnm) = irvl
                  itsmn(itnm) = itsmn(itnm) + nvol

            end if

         end if

         if( imesh .eq. 2 ) then

                  rtrx0(itnm) = rzx0
                  rtry0(itnm) = rzy0

                  itrty(itnm) = irtp
                  itrnm(itnm) = inr
                  rtrdl(itnm) = rdel
                  rtrmi(itnm) = rmin
                  rtrma(itnm) = rmax
                  call moddas_reallocate_dbl(
     &                    itlmax, itnm, inr+1, itrrg, das_itrrg)
                  das_itrrg(itrrg(itnm):itrrg(itnm)+inr)
     &                     = gmsh(istrg:istrg+inr)
                  itsmn(itnm) = itsmn(itnm) + inr + 1

                  itzty(itnm) = iztp
                  itznm(itnm) = inz
                  rtzdl(itnm) = zdel
                  rtzmi(itnm) = zmin
                  rtzma(itnm) = zmax
                  call moddas_reallocate_dbl(
     &                    itlmax, itnm, inz+1, itzrg, das_itzrg)
                  das_itzrg(itzrg(itnm):itzrg(itnm)+inz)
     &                     = gmsh(istzg:istzg+inz)
                  itsmn(itnm) = itsmn(itnm) + inz + 1

         else if( imesh .eq. 3 .or. lrshow .gt. 0 ) then

                  itxty(itnm) = ixtp
                  itxnm(itnm) = inx
                  rtxdl(itnm) = xdel
                  rtxmi(itnm) = xmin
                  rtxma(itnm) = xmax
                  call moddas_reallocate_dbl(
     &                    itlmax, itnm, inx+1, itxrg, das_itxrg)
                  das_itxrg(itxrg(itnm):itxrg(itnm)+inx)
     &                     = gmsh(istxg:istxg+inx)
                  itsmn(itnm) = itsmn(itnm) + inx + 1

                  ityty(itnm) = iytp
                  itynm(itnm) = iny
                  rtydl(itnm) = ydel
                  rtymi(itnm) = ymin
                  rtyma(itnm) = ymax
                  call moddas_reallocate_dbl(
     &                    itlmax, itnm, iny+1, ityrg, das_ityrg)
                  das_ityrg(ityrg(itnm):ityrg(itnm)+iny)
     &                     = gmsh(istyg:istyg+iny)
                  itsmn(itnm) = itsmn(itnm) + iny + 1

                  itzty(itnm) = iztp
                  itznm(itnm) = inz
                  rtzdl(itnm) = zdel
                  rtzmi(itnm) = zmin
                  rtzma(itnm) = zmax
                  call moddas_reallocate_dbl(
     &                    itlmax, itnm, inz+1, itzrg, das_itzrg)
                  das_itzrg(itzrg(itnm):itzrg(itnm)+inz)
     &                     = gmsh(istzg:istzg+inz)
                  itsmn(itnm) = itsmn(itnm) + inz + 1

         end if

*-----------------------------------------------------------------------
*        energy mesh
*-----------------------------------------------------------------------

            if( iout .ge. 4 ) then

                  itety(itnm) = ietp
                  itenm(itnm) = ine
                  rtedl(itnm) = edel
                  rtemi(itnm) = emin
                  rtema(itnm) = emax

                  call moddas_reallocate_dbl(
     &                    itlmax, itnm, ine+1, iterg, das_iterg)
                  das_iterg(iterg(itnm):iterg(itnm)+ine)
     &                     = gmsh(isteg:isteg+ine)
                  itsmn(itnm) = itsmn(itnm) + ine + 1

            else

                  itenm(itnm) = 0

                  call moddas_reallocate_dbl(
     &                    itlmax, itnm, 1, iterg, das_iterg)

                  itsmn(itnm) = itsmn(itnm) + 1

                  call moddas_reallocate_dbl(
     &                    3, icurrent_gmsh, 1, iaddress_gmsh, gmsh)
                  iaddress_gmsh(2) = iaddress_gmsh(3)
                  icurrent_gmsh = 2

            end if

*-----------------------------------------------------------------------
*        transformation
*-----------------------------------------------------------------------

                     itmtr(itnm,1) = igkst
                     itmtr(itnm,2) = ktrs
                     itmtr(itnm,3) = idtt
                     itmtr(itnm,4) = 0

               if( igkst .gt. 1 ) then

                  do k = 1, 13

                     rtmtr(itnm,k) = vtrs(k)

                  end do

               end if

*-----------------------------------------------------------------------
*        material
*-----------------------------------------------------------------------

                  itmtn(itnm) = imate
                  itmcn(itnm) = jmate

            if( imate .gt. 0 ) then

                  itsmn(itnm) = itsmn(itnm)
     &                        + ( imate + mod(imate,2) ) / 2

            end if

*-----------------------------------------------------------------------
*        particles
*-----------------------------------------------------------------------

            itmxptt = inpat
            itmxgpt = 1
            do i = 1, inpat
              if ( iptyp(i).lt.0 .and. -iptyp(i).gt.itmxgpt ) then
                itmxgpt = -iptyp(i)
              end if
            end do
            call ALLOCATE_PART_TEMP

            if( iout .eq. 1 .or. iout .eq. 4 ) then

                  itpan(itnm) = inpat

            else

                  itpan(itnm) = 0

            end if

            if( inpat .gt. 0 ) then

               do i = 1, inpat

                  itpat(itnm,i,1) = iptyp(i)
                  itpat(itnm,i,2) = ipnkf(i)
                  itpat(itnm,i,3) = ipsub(i)  ! kitamura22/03/31

                  if( itpat(itnm,i,1) .lt. 0 ) then

                     do k = 1, -itpat(itnm,i,1)

                        jtpat(itnm,i,k,1) = imtyp(i,k)
                        jtpat(itnm,i,k,2) = imnkf(i,k)

                     end do

                  end if

               end do

            end if

*-----------------------------------------------------------------------
*        reg echo length
*-----------------------------------------------------------------------

                  iterl(itnm) = iechrl

*-----------------------------------------------------------------------
*        unit
*-----------------------------------------------------------------------

                  itunt(itnm) = iunt

*-----------------------------------------------------------------------
*        2d-type
*-----------------------------------------------------------------------

                  ittwo(itnm) = idtyp

*-----------------------------------------------------------------------
*        factor
*-----------------------------------------------------------------------

                  rtfac(itnm) = rfact

*-----------------------------------------------------------------------
*        volmat
*-----------------------------------------------------------------------

                  itvm(itnm) = matvol

*-----------------------------------------------------------------------
*        epsout
*-----------------------------------------------------------------------

                  iteps(itnm) = ieps

*-----------------------------------------------------------------------
*        bmpout
*-----------------------------------------------------------------------

                  itbmp(itnm) = ibmp

*-----------------------------------------------------------------------
*        vtkout
*-----------------------------------------------------------------------

                  itvtk(itnm) = ivtk

*-----------------------------------------------------------------------
*        vtkfmt
*-----------------------------------------------------------------------

                  itvtkfmt(itnm) = ivtkfmt

*-----------------------------------------------------------------------
*        resolution
*-----------------------------------------------------------------------

                  itres(itnm) = max( 1, ireso )

*-----------------------------------------------------------------------
*        width
*-----------------------------------------------------------------------

                  rtwid(itnm) = width

*-----------------------------------------------------------------------
*        electron heat
*-----------------------------------------------------------------------

                  itelc(itnm) = ielct

*-----------------------------------------------------------------------
*        deposit option
*-----------------------------------------------------------------------

                  itdpo(itnm) = idepo

*-----------------------------------------------------------------------
*        counter
*-----------------------------------------------------------------------

               do i = 1, 9

                  itcnt(i,itnm) = icount(i)
                  itcnth(i,itnm) = icounth(i) !frtati 2021/04/06

               end do

*-----------------------------------------------------------------------
*        axis
*-----------------------------------------------------------------------

                  itaxn(itnm) = inaxi

               do i = 1, inaxi

                  itaxs(itnm,i) = iaxis(i)

               end do

*-----------------------------------------------------------------------
*        infog
*-----------------------------------------------------------------------

                  itger(itnm) = infog

*-----------------------------------------------------------------------
*        stdcut
*-----------------------------------------------------------------------
                  rtstd(itnm) = stdcut

*-----------------------------------------------------------------------
*        maxangel
*-----------------------------------------------------------------------
                  itmxang(itnm) = imxang

*-----------------------------------------------------------------------
*        samepage
*-----------------------------------------------------------------------
                  itpgn(itnm) = inpgi

               do i = 1, inpgi

                  itpgs(itnm,i) = ipgis(i)

               end do

*-----------------------------------------------------------------------
*        file
*-----------------------------------------------------------------------

                  itfln(itnm) = infil

               do i = 1, infil

                  itfll(itnm,i) = lfile(i)

                  ctfln(itnm,i)(1:lfile(i)) = ifile(i)(1:lfile(i))

                  do k = lfile(i) + 1, 100

                     ctfln(itnm,i)(k:k) = ' '

                  end do

               end do

*-----------------------------------------------------------------------
*       restart file
*-----------------------------------------------------------------------
               call summary_param_resfile(itnm,irfflg,lrfile,irfile)

*-----------------------------------------------------------------------
*        output and dimension
*-----------------------------------------------------------------------

                  itout(itnm) = iout

               if( iout .eq. 1 .or. iout .eq. 4 ) then

                  itndy(itnm) = 29 + inpat * 2

               else if( iout .eq. 2 .or. iout .eq. 5 ) then

                  itndy(itnm) = 11

               else if( iout .eq. 3 .or. iout .eq. 6 ) then

                  itndy(itnm) = 1

               end if

*-----------------------------------------------------------------------
*        err2d
*-----------------------------------------------------------------------

                  iterr(itnm) = iter2

*-----------------------------------------------------------------------

      return

*-----------------------------------------------------------------------
*     errors
*-----------------------------------------------------------------------

  950    write(dkam,'(i9)') mdas
         m_err = 'Total tally storage number exceeds mdas ='//dkam
         ErrCha = ''
         ErrID = 'L:27791/R:theat/F:tallsm2.f'
         goto 999

  978    m_err = 'counter should be from -9999 to 9999'
         ErrCha = ''
         ErrID = 'L:27796/R:theat/F:tallsm2.f'
         goto 999

  979    m_err = 'Description of material parameter is wrong in tally '
     &            //tname
         ErrCha = ''
         ErrID = 'L:27802/R:theat/F:tallsm2.f'
         goto 999

  982    m_err = 'all particle is not available in tally '//tname
         ErrCha = ''
         ErrID = 'L:27807/R:theat/F:tallsm2.f'
         goto 999

  983    m_err = '2D-type should be 1-7 in tally '//tname
         ErrCha = ''
         ErrID = 'L:27812/R:theat/F:tallsm2.f'
         goto 999

  984    m_err = 'Unknown output parameter in tally '//tname
         ErrCha = ''
         ErrID = 'L:27817/R:theat/F:tallsm2.f'
         goto 999

  986    write(dkam,'(i5)') itlmax
         m_err = 'Total tally number exceeds itlmax = '//dkam
         ErrCha = ''
         ErrID = 'L:27823/R:theat/F:tallsm2.f'
         goto 999

  987    m_err = 'Unknown parameter in tally '//tname
         ErrCha = ''
         ErrID = 'L:27828/R:theat/F:tallsm2.f'
         goto 999
  988    m_err = 'Unit should be 0, 1, 2, 3 in tally '//tname
         ErrCha = ''
         ErrID = 'L:27832/R:theat/F:tallsm2.f'
         goto 999

  989    m_err = 'Double definition of the parameter in tally '//tname
         ErrCha = ''
         ErrID = 'L:27837/R:theat/F:tallsm2.f'
         goto 999

  990    m_err = 'Too many file name in tally '//tname
         ErrCha = ''
         ErrID = 'L:27842/R:theat/F:tallsm2.f'
         goto 999

  991    m_err = 'Too many axis in tally '//tname
         ErrCha = ''
         ErrID = 'L:27847/R:theat/F:tallsm2.f'
         goto 999

  992    m_err = 'Unknown axis name in tally '//tname
         ErrCha = ''
         ErrID = 'L:27852/R:theat/F:tallsm2.f'
         goto 999

  993    m_err = 'In this line, [ ; ] cannot be used.'
         ErrCha = ''
         ErrID = 'L:27857/R:theat/F:tallsm2.f'
         goto 999

  994    m_err = 'Name of particle is wrong in tally '//tname
         ErrCha = ''
         ErrID = 'L:27862/R:theat/F:tallsm2.f'
         goto 999

cfrtati 2021/10/05 6 -> mxpart
  995    m_err = 'Number of particles is larger than mxpart in '//tname
         ErrCha = ''
         ErrID = 'L:27868/R:theat/F:tallsm2.f'
         goto 999

  996    m_err = 'Description of mesh is wrong in tally '//tname
         ErrCha = ''
         ErrID = 'L:27873/R:theat/F:tallsm2.f'
         goto 999

  997    m_err = 'Description of parameter is wrong in tally '//tname
         ErrCha = ''
         ErrID = 'L:27878/R:theat/F:tallsm2.f'
         goto 999

  998    m_err = 'Unknown mesh parameter in tally '//tname
         ErrCha = ''
         ErrID = 'L:27883/R:theat/F:tallsm2.f'
         goto 999

 1045    m_err = 'Too many samepage in tally '//tname
         ErrCha = ''
         ErrID = 'L:27888/R:theat/F:tallsm2.f'
         goto 999

 1046    m_err = 'samepage should be wwg, reg,eng,t,xy,yz,zx,x,y,z'
     &           //' in tally '//tname
         ErrCha = ''
         ErrID = 'L:27894/R:theat/F:tallsm2.f'
         goto 999

*-----------------------------------------------------------------------

  999 continue

         l_err = ill(jsn)
         k_err = jsn
         ierr  = 1

*-----------------------------------------------------------------------

      return
      end


************************************************************************
*                                                                      *
      subroutine tstar(jsn,jsi,dsin,idsi,ill,ilf,
     &                 jpn,chin,chlw,chcm,i1,i2,i3,i4,itnam,ierr)
*                                                                      *
*       read [t-star] section of input files                           *
*       modified by K.Niita on 2008/01/29                              *
*                                                                      *
************************************************************************
      use sangelmod, only: itsanf
      use anatallymod, only: nanatalRead
      use partmod ! frtati 2021/10/05
      use moddas
      use moddas_mesh
      use moddas_region
      use moddas_tally

      implicit real*8 (a-h,o-z)

       parameter(icsu=53) ! nais 2023/01/06  ! hirata 20230420

      include 'param.inc'
      include 'param01.inc'
      include 'err.inc'

*-----------------------------------------------------------------------

      common /tall00/ itnm, ital(itlmax), itals(itlmax), italm(itlmax)
      common /tall01/ itmsh(itlmax), itunt(itlmax), itspc(itlmax),
     &                itout(itlmax), ittwo(itlmax)

      common /tall02/ itrgn(itlmax), itrgm(itlmax), itreg(itlmax)
      common /tall25/ itrnv(itlmax), itriv(itlmax), itrrv(itlmax)

      common /tall03/ itrty(itlmax), itrnm(itlmax), itrrg(itlmax),
     &                rtrmi(itlmax), rtrma(itlmax), rtrdl(itlmax)
      common /tall04/ itxty(itlmax), itxnm(itlmax), itxrg(itlmax),
     &                rtxmi(itlmax), rtxma(itlmax), rtxdl(itlmax)
      common /tall05/ ityty(itlmax), itynm(itlmax), ityrg(itlmax),
     &                rtymi(itlmax), rtyma(itlmax), rtydl(itlmax)
      common /tall06/ itzty(itlmax), itznm(itlmax), itzrg(itlmax),
     &                rtzmi(itlmax), rtzma(itlmax), rtzdl(itlmax)
      common /tall07/ itety(itlmax), itenm(itlmax), iterg(itlmax),
     &                rtemi(itlmax), rtema(itlmax), rtedl(itlmax)


      common /tall08/ rtrx0(itlmax), rtry0(itlmax)

      common /tall10/ itaxn(itlmax), itaxs(itlmax,6)
      common /tall11/ itfln(itlmax), itfll(itlmax,6), ctfln(itlmax,6)
      character ctfln*100

      common /tall12/ itman(itlmax), itmat(itlmax), itmct(itlmax),
     &                itnun(itlmax), itnuc(itlmax),
     &                itndz(itlmax), itndn(itlmax),
     &                itnkz(itlmax), itnkn(itlmax)

      common /tall16/ itnfr(itlmax), itnfz(itlmax), itnfn(itlmax)

      common /tall14/ ittll(itlmax), ittle(itlmax)
      character ittle*80

      common /tall15/ itanl(itlmax), itang(itlmax)
      character itang*200

      common /tall27/ itaxl(itlmax), itaxt(itlmax),
     &                itayl(itlmax), itayt(itlmax),
     &                itazl(itlmax), itazt(itlmax)
      character itaxt*200, itayt*200, itazt*200

      common /tall19/ itsmn(itlmax), itstm(itlmax)

      common /tall20/ ittty(itlmax), ittnm(itlmax), ittrg(itlmax),
     &                rttmi(itlmax), rttma(itlmax), rttdl(itlmax)
      common /tall21/ rtfac(itlmax)
      common /tall22/ itmcn(itlmax), itmtn(itlmax), itmtt(itlmax)

      common /tall28/ itgsh(itlmax)
      common /tall29/ itrsh(itlmax)
      common /tall31/ iterl(itlmax)
      common /tall34/ itvm(itlmax)
      common /tall35/ iteps(itlmax)
      common /tall37/ itcnt(9,itlmax)

      common /tall38/ itres(itlmax)
      common /tall39/ rtwid(itlmax)
      common /tall46/ itmtr(itlmax,4), rtmtr(itlmax,13)

      common /tall48/ itmdp(itlmax,0:30), itmdf(itlmax)
      common /tall49/ itglt(itlmax)

!OBINATA: for resfile
      common /tall59/ irfll(itlmax), crfln(itlmax), itrff(itlmax)
      character crfln*100
      character irfile*100

      common /tall60/ itger(itlmax)
      common /tall63/ itbmp(itlmax)
      common /tall64/ itvtk(itlmax),itvtkfmt(itlmax)

      common /tall67/ itstd(itlmax), rtstd(itlmax)
      common /paraj/  mstz(300), parz(300) ! S.H. 2022.1.21

      common /tall71/ itmorp(itlmax),itname(itlmax)
      common /tall72/ itactnm(itlmax), itactrg(itlmax), itactmax(itlmax)

      common /tall75/ itnlatcel(itlmax), itnlatmem(itlmax)

      common /tall82/ itcnth(9,itlmax)
      dimension icounth(9)

! 20230106 nais samepage
      common /tall90/ itpgn(itlmax), itpgs(itlmax,6)

      dimension idas(1)
      equivalence ( das, idas )

*-----------------------------------------------------------------------

      character m_err*200
      common /error/ m_err, l_err, k_err

*-----------------------------------------------------------------------

      character title*80
      character angelp*200
      character cxtxt*200
      character cytxt*200
      character cztxt*200

*-----------------------------------------------------------------------

      dimension lschn(icsu), ischn(icsu)      ! S.Abe 2018/02/15, 41 -> 43
      character schan(icsu)*8


      data ( schan(i), i = 1, icsu ) /
     &    'mesh    ','part    ','mother  ','axis    ','file    ',
     &    'title   ','angel   ','unit    ','2d-type ','e-type  ',
     &    'output  ','factor  ','material','x-txt   ','y-txt   ',
     &    'z-txt   ','gshow   ','rshow   ','iechrl  ','volmat  ',
     &    'epsout  ','ctmin(1)','ctmax(1)','ctmin(2)','ctmax(2)',
     &    'ctmin(3)','ctmax(3)','resol   ','width   ','t-type  ',
     &    'trcl    ','*trcl   ','gslat   ','dump    ','resfile ',
     &    'ginfo   ','bmpout  ','vtkout  ','vtkfmt  ','stdcut  ',
     &    'sangel  ','morp    ','maxact  ','chmin(1)','chmax(1)',
     &    'chmin(2)','chmax(2)','chmin(3)','chmax(3)','maxangel',
     &    'samepage','nlatcel ','nlatmem '/

      data ( lschn(i), i = 1, icsu ) /
     &     4,         4,         6,         4,         4,
     &     5,         5,         4,         7,         6,
     &     6,         6,         8,         5,         5,
     &     5,         5,         5,         6,         6,
     &     6,         8,         8,         8,         8,
     &     8,         8,         5,         5,         6,
     &     4,         5,         5,         4,         7,
     &     5,         6,         6,         6,         6,
     &     6,         4,         6,         8,         8,
     &     8,         8,         8,         8,         8,
     &     8,         7,         7/
! hirata nlatcel for t-interact

*-----------------------------------------------------------------------


*-----------------------------------------------------------------------

cfrtati 2021/10/05 6 -> mxpart
      dimension iptyp(mxpart), ipnkf(mxpart)
      dimension imtyp(mxpart,mxpart), imnkf(mxpart,mxpart)
      dimension jstyp(mxpart), jnkf0(mxpart)

      common /subtra/ isubt, ipsub(mxpart)  ! kitamura22/03/31

      dimension iaxis(6)
      character ifile(6)*100
      dimension lfile(6)

      dimension ipgis(6)   ! samepage nais 2023/01/06

*-----------------------------------------------------------------------

      character chin*200, chlw*200, chcm*200
      character chlc*200

      character dsin(0:9)*200
      dimension idsi(0:9)

      dimension ill(0:9), ilf(0:9)

      character dkam*9

      character tname*12
      data      tname /'[t-interact]'/

      logical deqn1
      logical deqn4
      logical dcom2

      dimension icount(9)
      dimension vtrs(13)

      dimension jdump(30)

      integer isumtalRead

*-----------------------------------------------------------------------

      character element(104)*3,cnuc*3

      data element/
     & 'h  ','he ','li ','be ','b  ','c  ','n  ','o  ',
     & 'f  ','ne ','na ','mg ','al ','si ','p  ','s  ',
     & 'cl ','ar ','k  ','ca ','sc ','ti ','v  ','cr ',
     & 'mn ','fe ','co ','ni ','cu ','zn ','ga ','ge ',
     & 'as ','se ','br ','kr ','rb ','sr ','y  ','zr ',
     & 'nb ','mo ','tc ','ru ','rh ','pd ','ag ','cd ',
     & 'in ','sn ','sb ','te ','i  ','xe ','cs ','ba ',
     & 'la ','ce ','pr ','nd ','pm ','sm ','eu ','gd ',
     & 'tb ','dy ','ho ','er ','tm ','yb ','lu ','hf ',
     & 'ta ','w  ','re ','os ','ir ','pt ','au ','hg ',
     & 'tl ','pb ','bi ','po ','at ','rn ','fr ','ra ',
     & 'ac ','th ','pa ','u  ','np ','pu ','am ','cm ',
     & 'bk ','cf ','es ','fm ','md ','no ','lr ','ku '/

*-----------------------------------------------------------------------

            ierr  = 0

            inmat = 0
            inpat = 0
            inaxi = 0
            infil = 0
            imate = 0
            jmate = 1
            imoth = 0
            jmoth = 1
            iunt  = 1
            iout  = 4
            idtyp = 3

            langel = 0
            itsanf = 0
            lxtxt  = 0
            lytxt  = 0
            lztxt  = 0
            lgshow = 0
            lrshow = 0
            iechrl = 72
            matvol = 9
            ieps   = 0
            ibmp   = 0
            ivtk   = 0
            ivtkfmt= 0
            ittp   = 0
            igkst  = 0
            idtt   = 0
            ktrs   = 0
            idump  = 0
            igslt  = -1
            imxang = 0 ! frtati 2021/10/05
            nlatcel = 0      ! hirata 2023/04/20
            nlatmem = 1000   ! hirata 2023/04/20
            lrfile = 0 !OBINATA
            irfflg = 0 !OBINATA

            icount(1) = 0
            icount(2) = 0
            icount(3) = 0
            icount(4) = -9999
            icount(5) =  9999
            icount(6) = -9999
            icount(7) =  9999
            icount(8) = -9999
            icount(9) =  9999
            icounth(1) = 0
            icounth(2) = 0
            icounth(3) = 0
            icounth(4) = -9999
            icounth(5) =  9999
            icounth(6) = -9999
            icounth(7) =  9999
            icounth(8) = -9999
            icounth(9) =  9999

            ireso = 1
            width = 0.5

            rfact = 1.0

         do i = 1, icsu

            ischn(i) = 0

         end do

         do i = 1, 30
            jdump(i) = 0
         end do

            infog = 0

         inpgi = 0   ! samepage 2023/01/06

       isumtalRead = 0

            stdcut = -1.0

            morp = 0
            maxact = -1

*-----------------------------------------------------------------------
*     read one line from jsi
*-----------------------------------------------------------------------

  140 continue

            call readl(jsn,jsi,dsin,idsi,ill,ilf,'#!$',
     &                 jpn,chin,chlw,chcm,i1,i2,i3,i4,iskip,ierr)

               if( ierr .ne. 0 ) return
               if( jpn  .eq. 3 ) goto 800

               if( iskip .ne. 0 ) goto 140

  150 continue

               if( ierr .ne. 0 ) return
               if( jpn  .eq. 3 ) goto 800

*-----------------------------------------------------------------------
*        end of the section
*-----------------------------------------------------------------------

            if( chlw(i1:i1) .eq. '[' ) then

               jpn = 1
               goto 800

            end if

*-----------------------------------------------------------------------
*        identify the parameters
*-----------------------------------------------------------------------

            icl = i1

!-----------------------------------------------------------------------
!        sumtally sub section
!-----------------------------------------------------------------------
      if ( chlw(i1:i3) .eq. 'sumtally start' ) then
       isumtalRead = 1
       call read_sumtal(jsn,jsi,dsin,idsi,ill,ilf,
     &                 jpn,chin,chlw,chcm,i1,i2,i3,i4,iskip,ierr)
       if( ierr .ne. 0 ) return
       if( jpn == 3 ) goto 800   ! 'q:'
       if( jpn == 1 ) goto 800   ! end of the section
       go to 140
      end if

*-----------------------------------------------------------------------
*        anatally
*-----------------------------------------------------------------------

      if ( chlw(i1:i3) .eq. 'anatally start' ) then

         if (  mstz(1) .eq. 17 ) then
            nanatalRead(1+itnm) = 1
            call readl(jsn,jsi,dsin,idsi,ill,ilf,'#!$',
     &           jpn,chin,chlw,chcm,i1,i2,i3,i4,iskip,ierr)
            if ( chlw(i1:i3) .ne. 'anatally end' ) then
               ierr = 1
            end if
         else

            istbat = 1

            call stbatm(jsn,jsi,dsin,idsi,ill,ilf,
     &                  jpn,chin,chlw,chcm,i1,i2,i3,i4,ierr,
     &                  ist_nm,isd_nm,kst_nm)

            if( ierr .ne. 0 ) return
            if( jpn == 3 ) goto 800   ! 'q:'
            if( jpn == 1 ) goto 800   ! end of the section

         end if ! S.H. (2020.2.25)
            goto 140

      end if

*-----------------------------------------------------------------------

  200    continue

            chlc = chlw
            call chcomp(chlc,icl,i3,i5)

         do i = 1, icsu

            il = icl + lschn(i) - 1

            if( chlc(icl:il) .eq. schan(i)(1:lschn(i)) ) goto 100

         end do

               goto 987

*-----------------------------------------------------------------------
*        read value of parameters
*-----------------------------------------------------------------------

  100    continue

               ipm = i

               ischn( ipm ) = ischn( ipm ) + 1

            if( ipm .ne. 4 .and. ipm .ne. 5 .and.
     &          ipm .ne. 2 .and.
     &          ischn( ipm ) .gt. 1 ) goto 989 ! frtati 2021/10/05

               ic = inumc(chlw,il+1,i3,'=') + 1
               ic = jnumc(chlw,ic,i3)

               if( ic .gt. i3 ) goto 997

               icl = inumc(chlw,ic,i3,';') - 1

*-----------------------------------------------------------------------
*        mesh = region, r-z, or xyz
*-----------------------------------------------------------------------

         if( ipm .eq. 1 ) then

            if( chlw(ic:ic+2) .eq. 'reg' ) then

               imesh = 1

            else if( chlw(ic:ic+2) .eq. 'r-z' ) then

               imesh = 2

            else if( chlw(ic:ic+2) .eq. 'xyz' ) then

               imesh = 3

            else

               goto 998

            end if

            if( chlw(icl+1:icl+1) .eq. ';' ) goto 993

            if( imesh .eq. 1 ) then

               call moddas_allocate_int(
     &                 MAX_NUM_ITREG, idas_itreg_temporary)

               ndsm = 1
               call tregion(1,jsn,jsi,dsin,idsi,ill,ilf,
     &                      jpn,chin,chlw,chcm,i1,i2,i3,i4,ierr,
     &                      ntrn,mtrn,ndsm,nvol,ivl,irvl,0
     &                      ,MAX_NUM_ITREG,idas_itreg_temporary)

               if( mtrn > MAX_NUM_ITREG ) then
                  write(ErrCha,'(a,a,i5,a,a,i5,a)')
     &                 'sub.tstar@tallsm2.f'
     &                    //' ?dimension over idas_itreg_temporary?'
     &                    //' mtrn > MAX_NUM_ITREG'
     &                 ,' (mtrn=',mtrn,')'
     &                 ,' (MAX_NUM_ITREG@moddas.f=',MAX_NUM_ITREG,')'
                  ErrID = 'L:28384/R:tstar/F:tallsm2.f'
                  call ErrWrite(ErrID,ErrCha)
               endif

                  if( ierr .ne. 0 ) return
                  if( jpn  .eq. 3 ) goto 800
                  if( ntrn .lt. -1 ) goto 996

            else if( imesh .eq. 2 ) then

               call trzmesh(jsn,jsi,dsin,idsi,ill,ilf,
     &                      jpn,chin,chlw,chcm,i1,i2,i3,i4,ierr,
     &                      rzx0,rzy0,
     &                      irtp,inr,rmin,rmax,rdel,istrg,
     &                      iztp,inz,zmin,zmax,zdel,istzg)

                  if( ierr .ne. 0 ) return
                  if( jpn  .eq. 3 ) goto 800
                  if( irtp .lt. 0 ) goto 996
                  if( iztp .lt. 0 ) goto 996

            else if( imesh .eq. 3 ) then

               call txymesh(jsn,jsi,dsin,idsi,ill,ilf,
     &                      jpn,chin,chlw,chcm,i1,i2,i3,i4,ierr,
     &                      ixtp,inx,xmin,xmax,xdel,istxg,
     &                      iytp,iny,ymin,ymax,ydel,istyg,
     &                      iztp,inz,zmin,zmax,zdel,istzg)

                  if( ierr .ne. 0 ) return
                  if( jpn  .eq. 3 ) goto 800
                  if( ixtp .lt. 0 ) goto 996
                  if( iytp .lt. 0 ) goto 996
                  if( iztp .lt. 0 ) goto 996

            end if

                  goto 150

*-----------------------------------------------------------------------
*        energy mesh
*-----------------------------------------------------------------------

         else if( ipm .eq. 10 ) then

               call onum(chlw,ic,icl,cvvv,ierr)

               if( ierr .ne. 0 ) goto 997

               if( chlw(icl+1:icl+1) .eq. ';' ) goto 993

               ietp = nint( cvvv )

               call getmsh(jsn,jsi,dsin,idsi,ill,ilf,
     &                     jpn,chin,chlw,chcm,i1,i2,i3,i4,ierr,
     &                     'e',ietp,ine,emin,emax,edel,isteg)

               if( ierr .ne. 0 ) return

               goto 150

*-----------------------------------------------------------------------
*        time mesh
*-----------------------------------------------------------------------

         else if( ipm .eq. 30 ) then

               call onum(chlw,ic,icl,cvvv,ierr)

               if( ierr .ne. 0 ) goto 997

               if( chlw(icl+1:icl+1) .eq. ';' ) goto 993

               ittp = nint( cvvv )

               call getmsh(jsn,jsi,dsin,idsi,ill,ilf,
     &                     jpn,chin,chlw,chcm,i1,i2,i3,i4,ierr,
     &                     't',ittp,int,tmin,tmax,tdel,isttg)

               if( ierr .ne. 0 ) return

               goto 150

*-----------------------------------------------------------------------
*        transform
*-----------------------------------------------------------------------

         else if( ipm .eq. 31 .or. ipm .eq. 32 ) then

                  if( ipm .eq. 32 ) ktrs = 1

               call ttrans(jsn,jsi,dsin,idsi,ill,ilf,
     &                     jpn,chin,chlw,chcm,i1,i2,i3,i4,ierr,
     &                     ic,ktrs,igkst,idtt,vtrs)

               if( ierr .ne. 0 ) return

               goto 150

*-----------------------------------------------------------------------
*        particle name
*-----------------------------------------------------------------------

         else if( ipm .eq. 2 ) then

  400       continue

               ic = jnumc(chlw,ic,icl)

               if( ic .gt. icl ) then

                  icl = jnumc(chlw,icl+2,i3)

                  if( icl .le. i3 ) goto 200

                  goto 140

               end if

*-----------------------------------------------------------------------

            call rdpname(ic,icl,chlw,istyp,inkf0,jstyp,jnkf0,ierr)

               if( ierr .eq. 994 ) goto 994
               if( ierr .eq. 998 ) goto 997

*-----------------------------------------------------------------------

               inpat = inpat + 1

               if( inpat .gt. mxpart ) goto 995

                  iptyp(inpat) = istyp
                  ipnkf(inpat) = inkf0
                  ipsub(inpat) = isubt  ! kitamura22/03/31

               if( istyp .lt. 0 ) then

                  do i = 1, -istyp

                     imtyp(inpat,i) = jstyp(i)
                     imnkf(inpat,i) = jnkf0(i)

                  end do

               end if

               goto 400

*-----------------------------------------------------------------------
*        material
*-----------------------------------------------------------------------

         else if( ipm .eq. 13 ) then

            if( chlw(ic:ic+2) .eq. 'all' ) then

                  imate = 0

            else if( deqn4( chlw(ic:ic) ) ) then

               call onum(chlw,ic,icl,cvvv,ierr)

               if( ierr .ne. 0 ) goto 981

                  imate = nint( cvvv )

               if( imate .lt. 0 ) then

                  imate = -imate
                  jmate = -1

               end if

               if( imate .eq. 0 ) goto 981

                  nsmte = itmtt(itnm+1)
                  call moddas_reallocate_int(
     &                    itlmax, itnm+1, imate, itmtt, ismte)
                  if( mmmax .gt. mdas ) goto 950

  151                call readl(jsn,jsi,dsin,idsi,ill,ilf,'#!$',
     &                    jpn,chin,chlw,chcm,i1,i2,i3,i4,iskip,ierr)

                        if( ierr .ne. 0 ) return
                        if( jpn  .eq. 3 ) goto 981

                        if( iskip .ne. 0 ) goto 151

                  ic = i1

               do k = 1, imate

                  if( ic .gt. i3 ) then

  152                call readl(jsn,jsi,dsin,idsi,ill,ilf,'#!$',
     &                    jpn,chin,chlw,chcm,i1,i2,i3,i4,iskip,ierr)

                     if( ierr .ne. 0 ) return
                     if( jpn  .eq. 3 ) goto 981

                     if( iskip .ne. 0 ) goto 152

                     ic = i1

                  end if

                     ic = jnumc(chlw,ic,i3)

                     call snum(chlw,ic,i3,ic2,cvvv,ierr)

                     if( ierr .ne. 0 ) goto 981

                     matei = nint( cvvv )

                     ic = ic2

                     ismte(nsmte-1+k) = matei

               end do

            else

               goto 981

            end if

*-----------------------------------------------------------------------
*        mother
*-----------------------------------------------------------------------

         else if( ipm .eq. 3 ) then

            if( chlw(ic:ic+2) .eq. 'all' ) then

               imoth = 0

            else if( deqn4( chlw(ic:ic) ) ) then

               call onum(chlw,ic,icl,cvvv,ierr)

               if( ierr .ne. 0 ) goto 997

               imoth = nint( cvvv )

               if( imoth .lt. 0 ) then

                  imoth = -imoth
                  jmoth = -1

               end if

               if( imoth .eq. 0 ) goto 982

                  nsmat = itmat(itnm+1)
                  call moddas_reallocate_int(
     &                    itlmax, itnm+1, imoth, itmat, ismat)
                  if( mmmax .gt. mdas ) goto 950

  145                call readl(jsn,jsi,dsin,idsi,ill,ilf,'#!$',
     &                    jpn,chin,chlw,chcm,i1,i2,i3,i4,iskip,ierr)

                        if( ierr .ne. 0 ) return
                        if( jpn  .eq. 3 ) goto 982

                        if( iskip .ne. 0 ) goto 145

                  ic = i1

               do k = 1, imoth

                  if( ic .gt. i3 ) then

  146                call readl(jsn,jsi,dsin,idsi,ill,ilf,'#!$',
     &                    jpn,chin,chlw,chcm,i1,i2,i3,i4,iskip,ierr)

                     if( ierr .ne. 0 ) return
                     if( jpn  .eq. 3 ) goto 982

                     if( iskip .ne. 0 ) goto 146

                     ic = i1

                  end if

                        ic = jnumc(chlw,ic,i3)

                        isa = 0
                        isn = 0

                        ica = 0
                        icb = 0
                        icm = 0
                        icn = 0

                     do i = ic, i3

                        if( chlw(i:i) .ge. 'a' .and.
     &                      chlw(i:i) .le. 'z' ) then

                           isa = isa + 1

                           if( isa .eq. 1 ) ica = i

                           icb = i

                        else if( deqn1( chlw(i:i) ) ) then

                           isn = isn + 1

                           if( isn .eq. 1 ) icm = i

                           icn = i

                        else if( dcom2( chlw(i:i) ) .or.
     &                           i .eq. i3 ) then

                           icd = i
                           goto 502

                        else

                           goto 982

                        end if

                     end do

                        icd = i3

  502                continue

                     if( ica .eq. 0 .or. icb .eq. 0 ) goto 982
                     if( icb-ica .lt. 0 .or. icb-ica .gt. 1 ) goto 982

                     cnuc = chlw(ica:icb)//'  '

                     do j = 1, 104

                        if( cnuc(1:3) .eq. element(j)(1:3) ) then

                           icha = j

                           goto 452

                        end if

                     end do

                           goto 982

  452                continue

                     if( icha .gt. 104 )  goto 982

                  if( icm .eq. 0 .or. icn .eq. 0 ) then

                     ismat(nsmat-1+k) = icha * 1000

                  else

                     if( isn .gt. 3 ) goto 982

                     read(chlw(icm:icn),'(i5)') masi

                     if( masi .lt. icha ) goto 982
                     if( masi-icha .gt. maxnt ) goto 982

                     ismat(nsmat-1+k) = icha * 1000 + masi

                  end if

                     ic = icd + 1

               end do

            else

               goto 982

            end if

*-----------------------------------------------------------------------
*        axis
*-----------------------------------------------------------------------

         else if( ipm .eq. 4 ) then

  600       inaxi = inaxi + 1

            if( inaxi .gt. 6 ) goto 991

            if( chlw(ic:ic+2) .eq. 'eng' ) then

               iaxis(inaxi) = 1
               ic =jnumc(chlw,ic+4,icl)

            else if( chlw(ic:ic+2) .eq. 'reg' ) then

               iaxis(inaxi) = 2
               ic =jnumc(chlw,ic+4,icl)

            else if( chlw(ic:ic+1) .eq. 'xy' .or.
     &               chlw(ic:ic+1) .eq. 'yx' ) then

               iaxis(inaxi) = 7
               ic =jnumc(chlw,ic+3,icl)

            else if( chlw(ic:ic+1) .eq. 'yz' .or.
     &               chlw(ic:ic+1) .eq. 'zy' ) then

               iaxis(inaxi) = 8
               ic =jnumc(chlw,ic+3,icl)

            else if( chlw(ic:ic+1) .eq. 'zx' .or.
     &               chlw(ic:ic+1) .eq. 'xz' ) then

               iaxis(inaxi) = 9
               ic =jnumc(chlw,ic+3,icl)

            else if( chlw(ic:ic+1) .eq. 'zr' .or.
     &               chlw(ic:ic+1) .eq. 'rz' ) then

               iaxis(inaxi) = 10
               ic =jnumc(chlw,ic+3,icl)

            else if( chlw(ic:ic) .eq. 'x' ) then

               iaxis(inaxi) = 3
               ic =jnumc(chlw,ic+2,icl)

            else if( chlw(ic:ic) .eq. 'y' ) then

               iaxis(inaxi) = 4
               ic =jnumc(chlw,ic+2,icl)

            else if( chlw(ic:ic) .eq. 'z' ) then

               iaxis(inaxi) = 5
               ic =jnumc(chlw,ic+2,icl)

            else if( chlw(ic:ic) .eq. 'r' ) then

               iaxis(inaxi) = 6
               ic =jnumc(chlw,ic+2,icl)

            else if( chlw(ic:ic) .eq. 't' ) then

               iaxis(inaxi) = 11
               ic =jnumc(chlw,ic+2,icl)

            else if( chlw(ic:ic+2) .eq. 'act' ) then

               iaxis(inaxi) = 12
               ic =jnumc(chlw,ic+4,icl)

            else

               goto 992

            end if

               if( ic .le. icl ) goto 600

               icl = jnumc(chlw,icl+2,i3)

               if( icl .le. i3 ) goto 200

*-----------------------------------------------------------------------
*        output
*-----------------------------------------------------------------------

         else if( ipm .eq. 11 ) then

            if( chlw(ic:ic+2) .eq. 'all' ) then

               iout = 1

            else if( chlw(ic:ic+4) .eq. 'decay' ) then

               iout = 2

            else if( chlw(ic:ic+6) .eq. 'elastic' ) then

               iout = 3

            else if( chlw(ic:ic+6) .eq. 'nuclear' ) then

               iout = 4

            else if( chlw(ic:ic+6) .eq. 'fission' ) then

               iout = 5

            else if( chlw(ic:ic+9) .eq. 'absorption' ) then

               iout = 6

            else if( chlw(ic:ic+7) .eq. 'heavyion' ) then

               iout = 7

            else if( chlw(ic:ic+7) .eq. 'transmut' ) then

               iout = 8

            else if( chlw(ic:ic+5) .eq. 'atomic' ) then

               iout = 9

            else if( chlw(ic:ic+7) .eq. 'deltaray' ) then

               iout = 19   ! S.Abe 2018/02/27

            else if( chlw(ic:ic+8) .eq. 'knockelec' ) then   ! S.Abe 2018/02/27

               iout = 20

            else if( chlw(ic:ic+5) .eq. 'atmflu' ) then

               iout = 21

            else if( chlw(ic:ic+4) .eq. 'auger' ) then

               iout = 22

            else if( chlw(ic:ic+4) .eq. 'brems' ) then

               iout = 23

            else if( chlw(ic:ic+8) .eq. 'photoelec' ) then

               iout = 24

            else if( chlw(ic:ic+6) .eq. 'compton' ) then

               iout = 25

            else if( chlw(ic:ic+7) .eq. 'pairprod' ) then

               iout = 26

            else if( chlw(ic:ic+4) .eq. 'annih' ) then

               iout = 27

c Ogawa (2021/10/12) renumber up to 99
            else if( chlw(ic:ic+14) .eq. 'ets_ioniz_e-exc' ) then ! T.Sato 2018/2/22, check this first

               iout = 38

            else if( chlw(ic:ic+7) .eq. 'ets_elas' ) then

               iout = 30

            else if( chlw(ic:ic+8) .eq. 'ets_ioniz' ) then

               iout = 31

            else if( chlw(ic:ic+8) .eq. 'ets_e-exc' ) then

               iout = 32

            else if( chlw(ic:ic+6) .eq. 'ets_dea' ) then

               iout = 33

            else if( chlw(ic:ic+8) .eq. 'ets_v-exc' ) then

               iout = 34

            else if( chlw(ic:ic+8) .eq. 'ets_p-exc' ) then

               iout = 35

            else if( chlw(ic:ic+8) .eq. 'ets_r-exc' ) then

               iout = 36

            else if( chlw(ic:ic+10) .eq. 'ets_plasmon' ) then

               iout = 37

            else if( chlw(ic:ic+6) .eq. 'ets_hit' ) then ! T.Sato 2018/2/22, check this first

               iout = 39

