     &                 'sub.ttrack@tallsm2.f'
     &                    //' ?dimension over idas_itreg_temporary?'
     &                    //' mtrn > MAX_NUM_ITREG'
     &                 ,' (mtrn=',mtrn,')'
     &                 ,' (MAX_NUM_ITREG@moddas.f=',MAX_NUM_ITREG,')'
                  ErrID = 'L:33470/R:tdpa/F:tallsm2.f'
