     &       ( amin .lt. -1.0 .or. amax .gt. 1.0 ) ) then

         m_err = 'cos mesh should be -1 < cos < 1 in tally '//tname
         ErrCha = ''
         ErrID = 'L:37170/R:tprodct/F:tallsm2.f'
         goto 999

      else if( iatp .lt. 0 .and.
     &       ( amin .lt. 0.0 .or. amax .gt. 180.0 ) ) then

         m_err = 'the mesh should be 0 < the < 180 in tally '//tname
         ErrCha = ''
         ErrID = 'L:37178/R:tprodct/F:tallsm2.f'
         goto 999

      else if( jatp .eq. 3 .or. jatp .eq. 4 .or. jatp .eq. 5 ) then

         m_err = 'Angle mesh type should be 1, 2 in tally '//tname
         ErrCha = ''
         ErrID = 'L:37185/R:tprodct/F:tallsm2.f'
         goto 999

      else if( itsanf > 1 ) then

         m_err = 'Double definition of sangel is found in tally '//tname
         ErrCha = ''
         ErrID = 'L:37192/R:tprodct/F:tallsm2.f'
         goto 999

CCSE added for LET parameter (2022.08.31) >>>>>
      else if ( letmat .eq. 0 .and. ieng2let .eq. 1 ) then

         m_err = 'letmat should not be 0 in '//tname
         ErrCha = ''
         ErrID = 'L:37200/R:tprodct/F:tallsm2.f'
         goto 999

      end if

      do i = 1, inaxi

         if( lrshow .eq. 0 ) then

            if( ( iaxis(i) .eq. 7 .or. iaxis(i) .eq. 8 .or.
     &            iaxis(i) .eq. 9 ) .and. imesh .ne. 3 ) then

               m_err = 'Axis is xy, yz, or zx, '//
     &                 'but mesh is not xyz in tally '//tname
               ErrCha = ''
               ErrID = 'L:37215/R:tprodct/F:tallsm2.f'
               goto 999

            end if

         end if

         if( iaxis(i) .eq. 11 .and. ittp .eq. 0 ) then

            m_err = 'T-type is not defined in tally '//tname
            ErrCha = ''
            ErrID = 'L:37226/R:tprodct/F:tallsm2.f'
            goto 999

         else if( iaxis(i) .eq. 2 .and. imesh .ne. 1 ) then

            m_err = 'Axis is reg but mesh is not reg in tally '//tname
            ErrCha = ''
            ErrID = 'L:37233/R:tprodct/F:tallsm2.f'
            goto 999

         else if( iaxis(i) .eq. 14 .and. imesh .ne. 4 ) then
            m_err = 'Axis is tet but mesh is not tet in tally '//tname
            ErrCha = ''
            ErrID = 'L:37239/R:tprodct/F:tallsm2.f'
            goto 999

         else if( iaxis(i) .eq. 3 .and. imesh .ne. 3 ) then

            m_err = 'Axis is x but mesh is not xyz in tally '//tname
            ErrCha = ''
            ErrID = 'L:37246/R:tprodct/F:tallsm2.f'
            goto 999

         else if( iaxis(i) .eq. 4 .and. imesh .ne. 3 ) then

            m_err = 'Axis is y but mesh is not xyz in tally '//tname
            ErrCha = ''
            ErrID = 'L:37253/R:tprodct/F:tallsm2.f'
            goto 999

         else if( iaxis(i) .eq. 5 .and. imesh .eq. 1 ) then

            m_err = 'Axis is z but mesh is reg in tally '//tname
            ErrCha = ''
            ErrID = 'L:37260/R:tprodct/F:tallsm2.f'
            goto 999

         else if( iaxis(i) .eq. 6 .and. imesh .ne. 2 ) then

            m_err = 'Axis is r but mesh is not r-z in tally '//tname
            ErrCha = ''
            ErrID = 'L:37267/R:tprodct/F:tallsm2.f'
            goto 999

         else if( iaxis(i) .eq. 10 .and. imesh .ne. 2 ) then

            m_err = 'Axis is rz,'//
     &              ' but mesh is not r-z in tally '//tname
            ErrCha = ''
            ErrID = 'L:37275/R:tprodct/F:tallsm2.f'
            goto 999

         else if( iaxis(i) .eq. 10 .and.
     &           ( irtp .ne. 2 .and. irtp .ne. 4 ) ) then

            m_err = 'Axis is rz,'//
     &              ' but r mesh type is not 2 or 4 in tally '//tname
            ErrCha = ''
            ErrID = 'L:37284/R:tprodct/F:tallsm2.f'
            goto 999

         else if( iaxis(i) .eq. 10 .and.
     &           ( iztp .ne. 2 .and. iztp .ne. 4 ) ) then

            m_err = 'Axis is rz,'//
     &              ' but z mesh type is not 2 or 4 in tally '//tname
            ErrCha = ''
            ErrID = 'L:37293/R:tprodct/F:tallsm2.f'
            goto 999

         else if( ( iaxis(i) .eq. 7 .or. iaxis(i) .eq. 9 ) .and.
     &           ( ixtp .ne. 2 .and. ixtp .ne. 4 ) ) then

            m_err = 'Axis is xy or zx,'//
     &              ' but x mesh type is not 2 or 4 in tally '//tname
            ErrCha = ''
            ErrID = 'L:37302/R:tprodct/F:tallsm2.f'
            goto 999

         else if( ( iaxis(i) .eq. 8 .or. iaxis(i) .eq. 9 ) .and.
     &           ( iztp .ne. 2 .and. iztp .ne. 4 ) ) then

            m_err = 'Axis is yz or zx,'//
     &              ' but z mesh type is not 2 or 4 in tally '//tname
            ErrCha = ''
            ErrID = 'L:37311/R:tprodct/F:tallsm2.f'
            goto 999

         else if( ( iaxis(i) .eq. 7 .or. iaxis(i) .eq. 8 ) .and.
     &           ( iytp .ne. 2 .and. iytp .ne. 4 ) ) then

            m_err = 'Axis is xy or yz,'//
     &              ' but y mesh type is not 2 or 4 in tally '//tname
            ErrCha = ''
            ErrID = 'L:37320/R:tprodct/F:tallsm2.f'

         else if( ( iaxis(i) .eq. 12 .or. iaxis(i) .eq. 13 ) .and.
     &            ischn(35) .eq. 0 ) then

            m_err = 'Axis is ang but angle mesh is not defined'//
     &              ' in tally '//tname
            ErrCha = ''
            ErrID = 'L:37328/R:tprodct/F:tallsm2.f'
            goto 999

CCSE added for LET parameter (2022.12.09) >>>>>
         else if ( ieng2let.eq.1 .and. iaxis(inaxi).eq.1 ) then  ! if axis=eng
            write(6,'(a73)') 'Warning: axis of eng in '// tname //
     &                         ' is changed to let because eng2let = 1'
            iaxis(inaxi) = 15

         else if ( ieng2let.eq.0 .and. iaxis(inaxi).eq.15 ) then ! if axis=let
            write(6,'(a73)') 'Warning: axis of let in '// tname //
     &                         ' is changed to eng because eng2let = 0'
            iaxis(inaxi) = 1

         end if

      end do

*-----------------------------------------------------------------------

      if ( ibmp .ne. 0 ) then

         if ( imesh .ne. 3 ) then

            m_err = 'Mesh should be xyz on bmpout in tally '//tname
            ErrCha = ''
            ErrID = 'L:37354/R:tprodct/F:tallsm2.f'
            goto 999

         end if

         do i = 1, inaxi

            if ( iaxis(i) .ne. 7 .and.
     &           iaxis(i) .ne. 8 .and.
     &           iaxis(i) .ne. 9 ) then

               m_err = 'Axis should be xy, yz or xz on bmpout'//
     &                 ' in tally '//tname
               ErrCha = ''
               ErrID = 'L:37368/R:tprodct/F:tallsm2.f'
               goto 999

            end if

         end do

      end if

*-----------------------------------------------------------------------

      if ( ivtk .ne. 0 ) then

         if ( imesh .ne. 3 ) then

            m_err = 'Mesh should be xyz on bmpout in tally '//tname
            ErrCha = ''
            ErrID = 'L:37385/R:tprodct/F:tallsm2.f'
            goto 999

         end if

         do i = 1, inaxi

            if ( iaxis(i) .ne. 7 .and.
     &           iaxis(i) .ne. 8 .and.
     &           iaxis(i) .ne. 9 ) then

               m_err = 'Axis should be xy, yz or xz on bmpout'//
     &                 ' in tally '//tname
               ErrCha = ''
               ErrID = 'L:37399/R:tprodct/F:tallsm2.f'
               goto 999

            end if

         end do

      end if

*-----------------------------------------------------------------------

      if( iout .eq. 9 ) then

         if( imoth .ne. 0 ) then

               m_err = 'Only mother=all is allowed for output=atomic'//
     &                 ' in tally '//tname
               ErrCha = ''
               ErrID = 'L:37417/R:tprodct/F:tallsm2.f'
               goto 999

         endif

      endif

*-----------------------------------------------------------------------

      if( iout .ne. 2 .or. iout .ne. 5 .or. iout .ne. 7 ) then

         if( ipri .eq. 0 ) then

               m_err = 'Warning. primary particles are disregarded '//
     &                 'unless output = elastic, atomic, or nuclear '//
     &                  tname
               ErrCha = ''
               ErrID = 'L:37434/R:tprodct/F:tallsm2.f'

         endif

      elseif( iout .eq. 7 ) then

         if( ipri .eq. 1 ) then

               m_err = 'Warning! primary is 1 but output = atomic '//
     &                 'Be sure that primary particles are also scored.'
     &          //tname
               ErrCha = ''
               ErrID = 'L:37446/R:tprodct/F:tallsm2.f'

         endif

      endif

*-----------------------------------------------------------------------
      if ( ifoam .ne. 0 ) then

         if ( imesh .ne. 4 ) then

            m_err = 'Mesh should be tet on foamout in tally '//tname
            ErrCha = ''
            ErrID = 'L:37459/R:tprodct/F:tallsm2.f'
            goto 999

         end if

         do i = 1, inaxi

            if ( iaxis(i) .ne. 14 ) then

               m_err = 'Axis should be tet on foamout'//
     &                 ' in tally '//tname
               ErrCha = ''
               ErrID = 'L:37471/R:tprodct/F:tallsm2.f'
               goto 999

            end if

         end do

      end if

*-----------------------------------------------------------------------
*        for dump
*-----------------------------------------------------------------------

         if( idump .ne. 0 ) then

            infil = 1
            inaxi = 1
            iunt  = 1

         end if

*-----------------------------------------------------------------------
*     summary
*-----------------------------------------------------------------------

                  itnm = itnm + 1

                  if( itnm .gt. itlmax ) goto 986

                  ital( itnm ) = 8

                  itsmn(itnm) = 0
                  itstm(itnm) = 0

                  itxnm(itnm) = 0
                  itynm(itnm) = 0
                  itznm(itnm) = 0

*-----------------------------------------------------------------------
*        title
*-----------------------------------------------------------------------

                  ittll(itnm) = titll
                  ittle(itnm) = title

*-----------------------------------------------------------------------
*        angel parameter
*-----------------------------------------------------------------------

               if( langel .gt. 0 ) then

                  itanl(itnm) = langel
                  itang(itnm) = angelp

               else

                  itanl(itnm) = 0

               end if

*-----------------------------------------------------------------------
*        x-txt parameter
*-----------------------------------------------------------------------

               if( lxtxt .gt. 0 ) then

                  itaxl(itnm) = lxtxt
                  itaxt(itnm) = cxtxt

               else

                  itaxl(itnm) = 0

               end if

*-----------------------------------------------------------------------
*        y-txt parameter
*-----------------------------------------------------------------------

               if( lytxt .gt. 0 ) then

                  itayl(itnm) = lytxt
                  itayt(itnm) = cytxt

               else

                  itayl(itnm) = 0

               end if

*-----------------------------------------------------------------------
*        z-txt parameter
*-----------------------------------------------------------------------

               if( lztxt .gt. 0 ) then

                  itazl(itnm) = lztxt
                  itazt(itnm) = cztxt

               else

                  itazl(itnm) = 0

               end if

*-----------------------------------------------------------------------
*        gshow parameter
*-----------------------------------------------------------------------

               if( lgshow .gt. 0 ) then

                  itgsh(itnm) = min(5,lgshow)  ! T.Sato 2019/02/20

               else

                  itgsh(itnm) = 0

               end if

*-----------------------------------------------------------------------
*        gslat parameter
*-----------------------------------------------------------------------
                  itglt(itnm) = igslt

*-----------------------------------------------------------------------
*        rshow parameter
*-----------------------------------------------------------------------

                  itrsh(itnm) = min(4,lrshow)

*-----------------------------------------------------------------------
*        material
*-----------------------------------------------------------------------

                  itmtn(itnm) = imate
                  itmcn(itnm) = jmate

            if( imate .gt. 0 ) then

                  itsmn(itnm) = itsmn(itnm)
     &                        + ( imate + mod(imate,2) ) / 2

            end if

*-----------------------------------------------------------------------
*        mother
*-----------------------------------------------------------------------

                  itman(itnm) = imoth
                  itmct(itnm) = jmoth

               if( imoth .gt. 0 ) then

                  itsmn(itnm) = itsmn(itnm)
     &                        + ( imoth + mod(imoth,2) ) / 2

               end if

*-----------------------------------------------------------------------
*        mesh
*-----------------------------------------------------------------------

                  itmsh(itnm) = imesh

         if( imesh .eq. 1 ) then

                  itrgn(itnm) = ntrn
                  itrgm(itnm) = mtrn
                  itrnv(itnm) = nvol

            if( ntrn .gt. 0 ) then

                  call moddas_reallocate_int(
     &                    itlmax, itnm, mtrn, itreg, idas_itreg)
                  idas_itreg(itreg(itnm):itreg(itnm)+mtrn-1)
     &                      = idas_itreg_temporary(1:mtrn)
                  call moddas_deallocate_int(idas_itreg_temporary)
                  itsmn(itnm) = itsmn(itnm)
     &                        + ( mtrn + mod(mtrn,2) ) / 2

            end if

            if( nvol .gt. 0 ) then

                  itriv(itnm) = ivl
                  itsmn(itnm) = itsmn(itnm)
     &                        + ( nvol + mod(nvol,2) ) / 2

                  itrrv(itnm) = irvl
                  itsmn(itnm) = itsmn(itnm) + nvol

            end if

         else if( imesh .eq. 4 ) then

                  itrgn(itnm) = ntrn
                  itrgm(itnm) = mtrn
                  itrnv(itnm) = 0

            if( ntrn .gt. 0 ) then

                  call moddas_reallocate_int(
     &                    itlmax, itnm, mtrn, itreg, idas_itreg)
                  idas_itreg(itreg(itnm):itreg(itnm)+mtrn-1)
     &                      = idas_itreg_temporary(1:mtrn)

            end if

         end if

         if( imesh .eq. 2 ) then

                  rtrx0(itnm) = rzx0
                  rtry0(itnm) = rzy0

                  itrty(itnm) = irtp
                  itrnm(itnm) = inr
                  rtrdl(itnm) = rdel
                  rtrmi(itnm) = rmin
                  rtrma(itnm) = rmax
                  call moddas_reallocate_dbl(
     &                    itlmax, itnm, inr+1, itrrg, das_itrrg)
                  das_itrrg(itrrg(itnm):itrrg(itnm)+inr)
     &                     = gmsh(istrg:istrg+inr)
                  itsmn(itnm) = itsmn(itnm) + inr + 1

                  itzty(itnm) = iztp
                  itznm(itnm) = inz
                  rtzdl(itnm) = zdel
                  rtzmi(itnm) = zmin
                  rtzma(itnm) = zmax
                  call moddas_reallocate_dbl(
     &                    itlmax, itnm, inz+1, itzrg, das_itzrg)
                  das_itzrg(itzrg(itnm):itzrg(itnm)+inz)
     &                     = gmsh(istzg:istzg+inz)
                  itsmn(itnm) = itsmn(itnm) + inz + 1

         else if( imesh .eq. 3 .or. lrshow .gt. 0 ) then

                  itxty(itnm) = ixtp
                  itxnm(itnm) = inx
                  rtxdl(itnm) = xdel
                  rtxmi(itnm) = xmin
                  rtxma(itnm) = xmax
                  call moddas_reallocate_dbl(
     &                    itlmax, itnm, inx+1, itxrg, das_itxrg)
                  das_itxrg(itxrg(itnm):itxrg(itnm)+inx)
     &                     = gmsh(istxg:istxg+inx)
                  itsmn(itnm) = itsmn(itnm) + inx + 1

                  ityty(itnm) = iytp
                  itynm(itnm) = iny
                  rtydl(itnm) = ydel
                  rtymi(itnm) = ymin
                  rtyma(itnm) = ymax
                  call moddas_reallocate_dbl(
     &                    itlmax, itnm, iny+1, ityrg, das_ityrg)
                  das_ityrg(ityrg(itnm):ityrg(itnm)+iny)
     &                     = gmsh(istyg:istyg+iny)
                  itsmn(itnm) = itsmn(itnm) + iny + 1

                  itzty(itnm) = iztp
                  itznm(itnm) = inz
                  rtzdl(itnm) = zdel
                  rtzmi(itnm) = zmin
                  rtzma(itnm) = zmax
                  call moddas_reallocate_dbl(
     &                    itlmax, itnm, inz+1, itzrg, das_itzrg)
                  das_itzrg(itzrg(itnm):itzrg(itnm)+inz)
     &                     = gmsh(istzg:istzg+inz)
                  itsmn(itnm) = itsmn(itnm) + inz + 1

         end if

*-----------------------------------------------------------------------
*        axis
*-----------------------------------------------------------------------

                  itaxn(itnm) = inaxi

               do i = 1, inaxi

                  itaxs(itnm,i) = iaxis(i)

               end do

*-----------------------------------------------------------------------
*        file
*-----------------------------------------------------------------------

                  itfln(itnm) = infil

               do i = 1, infil

                  itfll(itnm,i) = lfile(i)

                  ctfln(itnm,i)(1:lfile(i)) = ifile(i)(1:lfile(i))

                  do k = lfile(i) + 1, 100

                     ctfln(itnm,i)(k:k) = ' '

                  end do

               end do

*-----------------------------------------------------------------------
*       restart file
*-----------------------------------------------------------------------
               call summary_param_resfile(itnm,irfflg,lrfile,irfile)

*-----------------------------------------------------------------------
*        particles
*-----------------------------------------------------------------------

            itmxptt = inpat
            itmxgpt = 1
            do i = 1, inpat
              if ( iptyp(i).lt.0 .and. -iptyp(i).gt.itmxgpt ) then
                itmxgpt = -iptyp(i)
              end if
            end do
            call ALLOCATE_PART_TEMP

            if( inpat .gt. 0 ) then

                  itpan(itnm) = inpat

               do i = 1, inpat

                  itpat(itnm,i,1) = iptyp(i)
                  itpat(itnm,i,2) = ipnkf(i)
                  itpat(itnm,i,3) = ipsub(i)  ! kitamura22/03/31

                  if( itpat(itnm,i,1) .lt. 0 ) then

                     do k = 1, -itpat(itnm,i,1)

                        jtpat(itnm,i,k,1) = imtyp(i,k)
                        jtpat(itnm,i,k,2) = imnkf(i,k)

                     end do

                  end if

               end do

            else if( inpat .eq. 0 ) then

                  itpan(itnm) = 1
                  itpat(itnm,1,1) = 20
                  itpat(itnm,1,2) = 0
                  itpat(itnm,1,3) = 0  ! kitamura22/03/31

            end if

*-----------------------------------------------------------------------
*        energy mesh
*-----------------------------------------------------------------------

                  itety(itnm) = ietp
                  itenm(itnm) = ine
                  rtedl(itnm) = edel
                  rtemi(itnm) = emin
                  rtema(itnm) = emax

                  call moddas_reallocate_dbl(
     &                    itlmax, itnm, ine+1, iterg, das_iterg)
                  das_iterg(iterg(itnm):iterg(itnm)+ine)
     &                     = gmsh(isteg:isteg+ine)
                  itsmn(itnm) = itsmn(itnm) + ine + 1

*-----------------------------------------------------------------------
*        angle mesh
*        and for without angle mesh
*-----------------------------------------------------------------------

               if( ischn(35) .ne. 0 ) then

                  call moddas_reallocate_dbl(
     &                    itlmax, itnm, ina+1, itarg, das_itarg)
                  das_itarg(itarg(itnm):itarg(itnm)+ina)
     &                     = gmsh(istag:istag+ina)
                  itsmn(itnm) = itsmn(itnm) + ina + 1

               else

                  iatp = 0
                  ina  = 1

                  istag = iaddress_gmsh(icurrent_gmsh)
                  call moddas_reallocate_dbl(
     &                    3, icurrent_gmsh, 2, iaddress_gmsh, gmsh)
                  iaddress_gmsh(2) = iaddress_gmsh(3)
                  icurrent_gmsh = 2

                  call moddas_reallocate_dbl(
     &                    itlmax, itnm, 2, itarg, das_itarg)
                  itsmn(itnm) = itsmn(itnm) + 2

                  gmsh(istag-1+1) = -1.0
                  gmsh(istag-1+2) =  1.0
                  das_itarg(itarg(itnm)-1+1) = -1.0
                  das_itarg(itarg(itnm)-1+2) =  1.0

               end if

                  itaty(itnm) = iatp
                  itanm(itnm) = ina
                  rtadl(itnm) = adel
                  rtami(itnm) = amin
                  rtama(itnm) = amax

*-----------------------------------------------------------------------
*        time mesh
*-----------------------------------------------------------------------

               if( ittp .ne. 0 ) then

                  ittty(itnm) = ittp
                  ittnm(itnm) = int
                  rttdl(itnm) = tdel
                  rttmi(itnm) = tmin
                  rttma(itnm) = tmax

                  call moddas_reallocate_dbl(
     &                    itlmax, itnm, int+1, ittrg, das_ittrg)
                  das_ittrg(ittrg(itnm):ittrg(itnm)+int)
     &                     = gmsh(isttg:isttg+int)
                  itsmn(itnm) = itsmn(itnm) + int + 1

               else

                  ittty(itnm) = ittp
                  ittnm(itnm) = 1
                  rttdl(itnm) = 0.d0
                  rttmi(itnm) = 0.d0
                  rttma(itnm) = 0.d0

                  call moddas_reallocate_dbl(
     &                    itlmax, itnm, 2, ittrg, das_ittrg)
                  itsmn(itnm) = itsmn(itnm) + 2

                  das_ittrg(ittrg(itnm)  ) = -1.d+30
                  das_ittrg(ittrg(itnm)+1) =  1.d+30

                  call moddas_reallocate_dbl(
     &                    3, icurrent_gmsh, 2, iaddress_gmsh, gmsh)
                  gmsh(iaddress_gmsh(icurrent_gmsh)  ) = -1.d+30
                  gmsh(iaddress_gmsh(icurrent_gmsh)+1) =  1.d+30
                  iaddress_gmsh(2) = iaddress_gmsh(3)
                  icurrent_gmsh = 2

               end if

*-----------------------------------------------------------------------
*        transformation
*-----------------------------------------------------------------------

                     itmtr(itnm,1) = igkst
                     itmtr(itnm,2) = ktrs
                     itmtr(itnm,3) = idtt
                     itmtr(itnm,4) = 0

               if( igkst .gt. 1 ) then

                  do k = 1, 13

                     rtmtr(itnm,k) = vtrs(k)

                  end do

               end if

*-----------------------------------------------------------------------
*        output
*-----------------------------------------------------------------------

                  itout(itnm) = iout

*-----------------------------------------------------------------------
*        include primary or not
*-----------------------------------------------------------------------

                  iprim(itnm) = ipri

*-----------------------------------------------------------------------
*        reg echo length
*-----------------------------------------------------------------------

                  iterl(itnm) = iechrl

*-----------------------------------------------------------------------
*        unit
*-----------------------------------------------------------------------

                  itunt(itnm) = iunt

*-----------------------------------------------------------------------
*        2D-type
*-----------------------------------------------------------------------

                  ittwo(itnm) = idtyp

*-----------------------------------------------------------------------
*        factor
*-----------------------------------------------------------------------

                  rtfac(itnm) = rfact

*-----------------------------------------------------------------------
*        volmat
*-----------------------------------------------------------------------

                  itvm(itnm) = matvol

*-----------------------------------------------------------------------
*        epsout
*-----------------------------------------------------------------------

                  iteps(itnm) = ieps

*-----------------------------------------------------------------------
*        bmpout
*-----------------------------------------------------------------------

                  itbmp(itnm) = ibmp

*-----------------------------------------------------------------------
*        vtkout
*-----------------------------------------------------------------------

                  itvtk(itnm) = ivtk

*-----------------------------------------------------------------------
*        vtkfmt
*-----------------------------------------------------------------------

                  itvtkfmt(itnm) = ivtkfmt

*-----------------------------------------------------------------------
*        resolution
*-----------------------------------------------------------------------

                  itres(itnm) = max( 1, ireso )

*-----------------------------------------------------------------------
*        width
*-----------------------------------------------------------------------

                  rtwid(itnm) = width

*-----------------------------------------------------------------------
*        letmat
*-----------------------------------------------------------------------

                  itlmt(itnm) = letmat

*-----------------------------------------------------------------------
*        eng2let
*-----------------------------------------------------------------------

                  ite2l(itnm) = ieng2let

*-----------------------------------------------------------------------
*        counter
*-----------------------------------------------------------------------

               do i = 1, 9

                  itcnt(i,itnm) = icount(i)
                  itcnth(i,itnm) = icounth(i) !frtati 2021/04/06

               end do

*-----------------------------------------------------------------------
*        infog
*-----------------------------------------------------------------------

                  itger(itnm) = infog

*-----------------------------------------------------------------------
*        stdcut
*-----------------------------------------------------------------------
                  rtstd(itnm) = stdcut

*-----------------------------------------------------------------------
*        bmpout
*-----------------------------------------------------------------------
                  itfoam(itnm) = ifoam

*-----------------------------------------------------------------------
*        maxangel
*-----------------------------------------------------------------------
                  itmxang(itnm) = imxang

*-----------------------------------------------------------------------
*        samepage
*-----------------------------------------------------------------------
                  itpgn(itnm) = inpgi

               do i = 1, inpgi

                  itpgs(itnm,i) = ipgis(i)

               end do

*-----------------------------------------------------------------------
*        xy, yz, zx, rz storage region
*-----------------------------------------------------------------------

                     mxyz = 1
                     mrzr = 1
                     mrzz = 1

                  do i = 1, inaxi

                     if( iaxis(i) .eq. 7 ) then

                        if( inx .gt. mxyz ) mxyz = inx
                        if( iny .gt. mxyz ) mxyz = iny

                     else if( iaxis(i) .eq. 8 ) then

                        if( iny .gt. mxyz ) mxyz = iny
                        if( inz .gt. mxyz ) mxyz = inz

                     else if( iaxis(i) .eq. 9 ) then

                        if( inx .gt. mxyz ) mxyz = inx
                        if( inz .gt. mxyz ) mxyz = inz

                     else if( iaxis(i) .eq. 10 ) then

                        mrzr = inr
                        mrzz = inz

                     end if

                  end do

                     itnfn(itnm) = mxyz
                     itnfr(itnm) = mrzr
                     itnfz(itnm) = mrzz

*-----------------------------------------------------------------------
*        dump
*-----------------------------------------------------------------------

                  itmdp(itnm,0) = idump

               if( idump .ne. 0 ) then

                  do i = 1, abs( idump )

                     itmdp(itnm,i) = jdump(i)

                  end do

               end if

*-----------------------------------------------------------------------
*     summary for anatally
*-----------------------------------------------------------------------

         if ( mstz(26) .ne. 3 ) istbat = 0 ! S.H. 2021.8.31
         if( istbat .eq. 0 ) then

                  itism(itnm) = istbat

         else if( istbat .gt. 0 ) then

            if( imesh .eq. 1 ) then
               if( ist_nm(1) .gt. 1 ) then
                  if( ist_nm(1) .gt. ntrn ) goto 967
               else if( ist_nm(1) .le. 0 ) then
                     ist_nm(1) = ntrn
                  do j = 1, ntrn
                     isd_nm(1,j) = j
                  end do
               end if
                     ist_nm(2) = 1
                     isd_nm(2,1) = 1
                     ist_nm(3) = 1
                     isd_nm(3,1) = 1
                     ist_nm(4) = 1
                     isd_nm(4,1) = 1
                     ist_nm(5) = 1
                     isd_nm(5,1) = 1
            else if( imesh .eq. 2 ) then
               if( ist_nm(4) .gt. 1 ) then
                  if( ist_nm(1) .gt. inz ) goto 967
               else if( ist_nm(4) .le. 0 ) then
                     ist_nm(4) = inz
                  do j = 1, inz
                     isd_nm(4,j) = j
                  end do
               end if
               if( ist_nm(5) .gt. 1 ) then
                  if( ist_nm(5) .gt. inr ) goto 967
               else if( ist_nm(5) .le. 0 ) then
                     ist_nm(5) = inr
                  do j = 1, inz
                     isd_nm(5,j) = j
                  end do
               end if
                     ist_nm(1) = 1
                     isd_nm(1,1) = 1
                     ist_nm(2) = 1
                     isd_nm(2,1) = 1
                     ist_nm(3) = 1
                     isd_nm(3,1) = 1
            else if( imesh .eq. 3 ) then
               if( ist_nm(2) .gt. 1 ) then
                  if( ist_nm(2) .gt. inx ) goto 967
               else if( ist_nm(2) .le. 0 ) then
                     ist_nm(2) = inx
                  do j = 1, inx
                     isd_nm(2,j) = j
                  end do
               end if
               if( ist_nm(3) .gt. 1 ) then
                  if( ist_nm(3) .gt. iny ) goto 967
               else if( ist_nm(3) .le. 0 ) then
                     ist_nm(3) = iny
                  do j = 1, iny
                     isd_nm(3,j) = j
                  end do
               end if
               if( ist_nm(4) .gt. 1 ) then
                  if( ist_nm(4) .gt. inz ) goto 967
               else if( ist_nm(4) .le. 0 ) then
                     ist_nm(4) = inz
                  do j = 1, inz
                     isd_nm(4,j) = j
                  end do
               end if
                     ist_nm(1) = 1
                     isd_nm(1,1) = 1
                     ist_nm(5) = 1
                     isd_nm(5,1) = 1
            end if

*-----------------------------------------------------------------------

               if( ist_nm(6) .gt. 1 ) then
                  if( ist_nm(6) .gt. ine ) goto 967
               else if( ist_nm(6) .le. 0 ) then
                     ist_nm(6) = ine
                  do j = 1, ine
                     isd_nm(6,j) = j
                  end do
               end if

               if( ist_nm(7) .gt. 1 ) then
                  if( ist_nm(7) .gt. ittnm(itnm) ) goto 967
               else if( ist_nm(7) .le. 0 ) then
                     ist_nm(7) = ittnm(itnm)
                  do j = 1, ittnm(itnm)
                     isd_nm(7,j) = j
                  end do
               end if

               if( ist_nm(8) .gt. 1 ) then
                  if( ist_nm(8) .gt. ina ) goto 967
               else if( ist_nm(8) .le. 0 ) then
                     ist_nm(8) = ina
                  do j = 1, ina
                     isd_nm(8,j) = j
                  end do
               end if

               if( ist_nm(9) .gt. 1 ) then
                  if( ist_nm(9) .gt. itpan(itnm) ) goto 967
               else if( ist_nm(9) .le. 0 ) then
                     ist_nm(9) = itpan(itnm)
                  do j = 1, itpan(itnm)
                     isd_nm(9,j) = j
                  end do
               end if

               if( ist_nm(10) .gt. 1 ) then
                  if( ist_nm(10) .gt. kmst(1) ) goto 967
               else if( ist_nm(10) .le. 0 ) then
                     if( kmst(1) .le. 0 ) then
                        ist_nm(10) = 1
                     else
                        ist_nm(10) = kmst(1)
                     end if
                  do j = 1, ist_nm(10)
                     isd_nm(10,j) = j
                  end do
               end if

*-----------------------------------------------------------------------

                iall = 1
            do i = 1, 10
                iall = iall * ist_nm(i)
            end do

                istbat = iall

            if( istbat .gt. kvlmax ) goto 966

*-----------------------------------------------------------------------

                jst_nm(1)  = 0
                jst_nm(2)  = jst_nm(1) + ist_nm(1)
                jst_nm(3)  = jst_nm(2) + ist_nm(2)
                jst_nm(4)  = jst_nm(3) + ist_nm(3)
                jst_nm(5)  = jst_nm(4) + ist_nm(4)
                jst_nm(6)  = jst_nm(5) + ist_nm(5)
                jst_nm(7)  = jst_nm(6) + ist_nm(6)
                jst_nm(8)  = jst_nm(7) + ist_nm(7)
                jst_nm(9)  = jst_nm(8) + ist_nm(8)
                jst_nm(10) = jst_nm(9) + ist_nm(9)
                jst_al     = jst_nm(10) + ist_nm(10)

*-----------------------------------------------------------------------

                  istbmm = ( mmmax - 1 ) * 2 + 1
                  mmmax = mmmax + ( jst_al + mod(jst_al,2) ) / 2
                  if( mmmax .gt. mdas ) goto 950

                  itstt(itnm) = istbmm
                  itsmn(itnm) = itsmn(itnm)
     &                        + ( jst_al + mod(jst_al,2) ) / 2

                  itism(itnm) = istbat

            do i = 1, 10
                  itist(i,itnm) = ist_nm(i)
                  itjst(i,itnm) = jst_nm(i)
                  itkst(i,itnm) = kst_nm(i)
            end do

            do i = 1, 10
               do k = 1, itist(i,itnm)
                  idas( itstt(itnm) + itjst(i,itnm) + k ) = isd_nm(i,k)
               end do
            end do

         end if

*-----------------------------------------------------------------------

      return

*-----------------------------------------------------------------------
*     errors
*-----------------------------------------------------------------------

  950    write(dkam,'(i9)') mdas
         m_err = 'Total tally storage number exceeds mdas ='//dkam
         ErrCha = ''
         ErrID = 'L:38327/R:tprodct/F:tallsm2.f'
         goto 999

  966    m_err = 'total # of points exceeds kvlmax in anatally.'//tname
         ErrCha = ''
         ErrID = 'L:38332/R:tprodct/F:tallsm2.f'
         goto 999

  967    m_err = 'something wrong in anatally parameters.'//tname
         ErrCha = ''
         ErrID = 'L:38337/R:tprodct/F:tallsm2.f'
         goto 999

  977    m_err = 'dump id should be 1 - 20.'
         ErrCha = ''
         ErrID = 'L:38342/R:tprodct/F:tallsm2.f'
         goto 999

  976    m_err = 'Description of dump parameter is wrong in tally '
     &            //tname
         ErrCha = ''
         ErrID = 'L:38348/R:tprodct/F:tallsm2.f'
         goto 999

  978    m_err = 'counter should be from -9999 to 9999'
         ErrCha = ''
         ErrID = 'L:38353/R:tprodct/F:tallsm2.f'
         goto 999

  980    m_err = 'unit should be 1-6,11-16,21-26,31-36 in tally '//tname
         ErrCha = ''
         ErrID = 'L:38358/R:tprodct/F:tallsm2.f'
         goto 999

  981    m_err = 'Description of material parameter is wrong in tally '
     &            //tname
         ErrCha = ''
         ErrID = 'L:38364/R:tprodct/F:tallsm2.f'
         goto 999

  982    m_err = 'Description of mother parameter is wrong in tally '
     &            //tname
         ErrCha = ''
         ErrID = 'L:38370/R:tprodct/F:tallsm2.f'
         goto 999

  983    m_err = '2D-type should be 1-7 in tally '//tname
         ErrCha = ''
         ErrID = 'L:38375/R:tprodct/F:tallsm2.f'
         goto 999

  984    m_err = 'Unknown output parameter in tally '//tname
         ErrCha = ''
         ErrID = 'L:38380/R:tprodct/F:tallsm2.f'
         goto 999

  985    m_err = 'iprimary is 0 or 1 '//tname
         ErrCha = ''
         ErrID = 'L:38385/R:tprodct/F:tallsm2.f'
         goto 999

  986    write(dkam,'(i5)') itlmax
         m_err = 'Total tally number exceeds itlmax = '//dkam
         ErrCha = ''
         ErrID = 'L:38391/R:tprodct/F:tallsm2.f'
         goto 999

  987    m_err = 'Unknown parameter in tally '//tname
         ErrCha = ''
         ErrID = 'L:38396/R:tprodct/F:tallsm2.f'
         goto 999

  989    m_err = 'Double definition of the parameter in tally '//tname
         ErrCha = ''
         ErrID = 'L:38401/R:tprodct/F:tallsm2.f'
         goto 999

  990    m_err = 'Too many file name in tally '//tname
         ErrCha = ''
         ErrID = 'L:38406/R:tprodct/F:tallsm2.f'
         goto 999

  991    m_err = 'Too many axis in tally '//tname
         ErrCha = ''
         ErrID = 'L:38411/R:tprodct/F:tallsm2.f'
         goto 999

  992    m_err = 'Unknown axis name in tally '//tname
         ErrCha = ''
         ErrID = 'L:38416/R:tprodct/F:tallsm2.f'
         goto 999

  993    m_err = 'In this line, [ ; ] cannot be used.'
         ErrCha = ''
         ErrID = 'L:38421/R:tprodct/F:tallsm2.f'
         goto 999

  994    m_err = 'Name of particle is wrong in tally '//tname
         ErrCha = ''
         ErrID = 'L:38426/R:tprodct/F:tallsm2.f'
         goto 999

cfrtati 2021/10/05 6 -> mxpart
  995    m_err = 'Number of particles is larger than mxpart in '//tname
         ErrCha = ''
         ErrID = 'L:38432/R:tprodct/F:tallsm2.f'
         goto 999

  996    m_err = 'Description of mesh is wrong in tally '//tname
         ErrCha = ''
         ErrID = 'L:38437/R:tprodct/F:tallsm2.f'
         goto 999

  997    m_err = 'Description of parameter is wrong in tally '//tname
         ErrCha = ''
         ErrID = 'L:38442/R:tprodct/F:tallsm2.f'
         goto 999

  998    m_err = 'Unknown mesh parameter in tally '//tname
         ErrCha = ''
         ErrID = 'L:38447/R:tprodct/F:tallsm2.f'
         goto 999

 1045    m_err = 'Too many samepage in tally '//tname
         ErrCha = ''
         ErrID = 'L:38452/R:tprodct/F:tallsm2.f'
         goto 999

 1046    m_err = 'samepage should be wwg, reg,eng,t,xy,yz,zx,x,y,z'
     &           //' in tally '//tname
         ErrCha = ''
         ErrID = 'L:38458/R:tprodct/F:tallsm2.f'
         goto 999

*-----------------------------------------------------------------------

  999 continue

         l_err = ill(jsn)
         k_err = jsn
         ierr  = 1

*-----------------------------------------------------------------------

      return
      end


************************************************************************
*                                                                      *
      subroutine tgshow(jsn,jsi,dsin,idsi,ill,ilf,
     &                  jpn,chin,chlw,chcm,i1,i2,i3,i4,ierr)
*                                                                      *
*       read [t-gshow] section of input files                          *
*       modified by K.Niita on 2013/12/13                              *
*                                                                      *
************************************************************************
      use sangelmod, only: itsanf
      use moddas
      use moddas_mesh

      implicit real*8 (a-h,o-z)

      include 'param.inc'
      include 'err.inc'

*-----------------------------------------------------------------------

      common /tall00/ itnm, ital(itlmax), itals(itlmax), italm(itlmax)
      common /tall01/ itmsh(itlmax), itunt(itlmax), itspc(itlmax),
     &                itout(itlmax), ittwo(itlmax)

      common /tall04/ itxty(itlmax), itxnm(itlmax), itxrg(itlmax),
     &                rtxmi(itlmax), rtxma(itlmax), rtxdl(itlmax)
      common /tall05/ ityty(itlmax), itynm(itlmax), ityrg(itlmax),
     &                rtymi(itlmax), rtyma(itlmax), rtydl(itlmax)
      common /tall06/ itzty(itlmax), itznm(itlmax), itzrg(itlmax),
     &                rtzmi(itlmax), rtzma(itlmax), rtzdl(itlmax)

      common /tall10/ itaxn(itlmax), itaxs(itlmax,6)
      common /tall11/ itfln(itlmax), itfll(itlmax,6), ctfln(itlmax,6)
      character ctfln*100

      common /tall14/ ittll(itlmax), ittle(itlmax)
      character ittle*80

      common /tall15/ itanl(itlmax), itang(itlmax)
      character itang*200

      common /tall27/ itaxl(itlmax), itaxt(itlmax),
     &                itayl(itlmax), itayt(itlmax),
     &                itazl(itlmax), itazt(itlmax)
      character itaxt*200, itayt*200, itazt*200

      common /tall19/ itsmn(itlmax), itstm(itlmax)
      common /tall21/ rtfac(itlmax)
      common /tall35/ iteps(itlmax)

      common /tall38/ itres(itlmax)
      common /tall39/ rtwid(itlmax)
      common /tall46/ itmtr(itlmax,4), rtmtr(itlmax,13)

      common /tall49/ itglt(itlmax)

      common /tall60/ itger(itlmax)
      common /tall63/ itbmp(itlmax)
      common /tall64/ itvtk(itlmax),itvtkfmt(itlmax)

      dimension idas(1)
      equivalence ( das, idas )

*-----------------------------------------------------------------------

      character m_err*200
      common /error/ m_err, l_err, k_err

*-----------------------------------------------------------------------

      character title*80
      character angelp*200
      character cxtxt*200
      character cytxt*200
      character cztxt*200

*-----------------------------------------------------------------------

      dimension lschn(21), ischn(21)
      character schan(21)*8

      data icsu / 21 /

      data ( schan(i), i = 1, 21 ) /
     &    'mesh    ','axis    ','file    ','title   ','angel   ',
     &    'factor  ','x-txt   ','y-txt   ','z-txt   ','output  ',
     &    'epsout  ','resol   ','width   ','trcl    ','*trcl   ',
     &    'gslat   ','ginfo   ','bmpout  ','vtkout  ','vtkfmt  ',
     &    'sangel  '/

      data ( lschn(i), i = 1, 21 ) /
     &     4,         4,         4,         5,         5,
     &     6,         5,         5,         5,         6,
     &     6,         5,         5,         4,         5,
     &     5,         5,         6,         6,         6,
     &     6/

*-----------------------------------------------------------------------

      dimension iaxis(6)
      character ifile(6)*100
      dimension lfile(6)
      dimension vtrs(13)

*-----------------------------------------------------------------------

      character chin*200, chlw*200, chcm*200
      character chlc*200

      character dsin(0:9)*200
      dimension idsi(0:9)

      dimension ill(0:9), ilf(0:9)

      character dkam*9

      character tname*9
      data      tname /'[t-gshow]'/

*-----------------------------------------------------------------------

            ierr  = 0

            inaxi = 0
            infil = 0

            langel = 0
            itsanf = 0
            lxtxt  = 0
            lytxt  = 0
            lztxt  = 0
            iout   = 2
            ieps   = 0
            ibmp   = 0
            ivtk   = 0
            ivtkfmt= 0
            igkst  = 0
            idtt   = 0
            ktrs   = 0
            igslt  = -1

            ireso = 1
            width = 0.5

            rfact = 0.5

         do i = 1, icsu

            ischn(i) = 0

         end do

            infog = 2

*-----------------------------------------------------------------------
*     read one line from jsi
*-----------------------------------------------------------------------

  140 continue

            call readl(jsn,jsi,dsin,idsi,ill,ilf,'#!$',
     &                 jpn,chin,chlw,chcm,i1,i2,i3,i4,iskip,ierr)

               if( ierr .ne. 0 ) return
               if( jpn  .eq. 3 ) goto 800

               if( iskip .ne. 0 ) goto 140

  150 continue

               if( ierr .ne. 0 ) return
               if( jpn  .eq. 3 ) goto 800

*-----------------------------------------------------------------------
*        end of the section
*-----------------------------------------------------------------------

            if( chlw(i1:i1) .eq. '[' ) then

               jpn = 1
               goto 800

            end if

*-----------------------------------------------------------------------
*        identify the parameters
*-----------------------------------------------------------------------

            icl = i1

  200    continue

            chlc = chlw
            call chcomp(chlc,icl,i3,i5)

         do i = 1, icsu

            il = icl + lschn(i) - 1

            if( chlc(icl:il) .eq. schan(i)(1:lschn(i)) ) goto 100

         end do

               goto 987

*-----------------------------------------------------------------------
*        read value of parameters
*-----------------------------------------------------------------------

  100    continue

               ipm = i

               ischn( ipm ) = ischn( ipm ) + 1

            if( ipm .ne. 2 .and. ipm .ne. 3 .and.
     &          ischn( ipm ) .gt. 1 ) goto 989

               ic = inumc(chlw,il+1,i3,'=') + 1
               ic = jnumc(chlw,ic,i3)

               if( ic .gt. i3 ) goto 997

               icl = inumc(chlw,ic,i3,';') - 1

*-----------------------------------------------------------------------
*        mesh = xyz only
*-----------------------------------------------------------------------

         if( ipm .eq. 1 ) then

            if( chlw(ic:ic+2) .eq. 'xyz' ) then

               imesh = 3

            else

               goto 998

            end if

            if( chlw(icl+1:icl+1) .eq. ';' ) goto 993

            if( imesh .eq. 3 ) then

               call txymesh(jsn,jsi,dsin,idsi,ill,ilf,
     &                      jpn,chin,chlw,chcm,i1,i2,i3,i4,ierr,
     &                      ixtp,inx,xmin,xmax,xdel,istxg,
     &                      iytp,iny,ymin,ymax,ydel,istyg,
     &                      iztp,inz,zmin,zmax,zdel,istzg)

                  if( ierr .ne. 0 ) return
                  if( jpn  .eq. 3 ) goto 800
                  if( ixtp .lt. 0 ) goto 996
                  if( iytp .lt. 0 ) goto 996
                  if( iztp .lt. 0 ) goto 996

            end if

                  goto 150

*-----------------------------------------------------------------------
*        transform
*-----------------------------------------------------------------------

         else if( ipm .eq. 14 .or. ipm .eq. 15 ) then

                  if( ipm .eq. 15 ) ktrs = 1

               call ttrans(jsn,jsi,dsin,idsi,ill,ilf,
     &                     jpn,chin,chlw,chcm,i1,i2,i3,i4,ierr,
     &                     ic,ktrs,igkst,idtt,vtrs)

               if( ierr .ne. 0 ) return

               goto 150

*-----------------------------------------------------------------------
*        axis
*-----------------------------------------------------------------------

         else if( ipm .eq. 2 ) then

  600       inaxi = inaxi + 1

            if( inaxi .gt. 1 ) goto 991

            if( chlw(ic:ic+1) .eq. 'xy' .or.
     &          chlw(ic:ic+1) .eq. 'yx' ) then

               iaxis(inaxi) = 1
               ic =jnumc(chlw,ic+3,icl)

            else if( chlw(ic:ic+1) .eq. 'yz' .or.
     &               chlw(ic:ic+1) .eq. 'zy' ) then

               iaxis(inaxi) = 2
               ic =jnumc(chlw,ic+3,icl)

            else if( chlw(ic:ic+1) .eq. 'zx' .or.
     &               chlw(ic:ic+1) .eq. 'xz' ) then

               iaxis(inaxi) = 3
               ic =jnumc(chlw,ic+3,icl)

            else

               goto 992

            end if

               if( ic .le. icl ) goto 600

               icl = jnumc(chlw,icl+2,i3)

               if( icl .le. i3 ) goto 200

*-----------------------------------------------------------------------
*        file name
*-----------------------------------------------------------------------

         else if( ipm .eq. 3 ) then

  700          infil = infil + 1

               if( infil .gt. 6 ) goto 990

               icf = min( inumc(chlw,ic,icl,' ') - 1, icl )

               lfile(infil) = icf - ic + 1
               ifile(infil)(1:icf-ic+1) = chin(ic:icf)

               ic = jnumc(chlw,icf+2,icl)

               if( ic .le. icl ) goto 700

               icl = jnumc(chlw,icl+2,i3)

               if( icl .le. i3 ) goto 200

*-----------------------------------------------------------------------
*        title
*-----------------------------------------------------------------------

         else if( ipm .eq. 4 ) then

               ict = min( ic + 79, i2 )

               title = chin(ic:ict)

               titll = ict - ic + 1

*-----------------------------------------------------------------------
*        angel parameters
*-----------------------------------------------------------------------

         else if( ipm .eq. 5 ) then

               ict = min( ic + 199, i3 )

               angelp = chin(ic:ict)

               langel = ict - ic + 1

!-----------------------------------------------------------------------
!        sangel parameters
!-----------------------------------------------------------------------

         else if( ipm .eq. 21 ) then

            itsanf = itsanf + 1

            call read_sangel(jsn,jsi,dsin,idsi,ill,ilf,
     &                       jpn,chin,chlw,chcm,i1,i2,i3,i4,iskip,ierr
     &                      ,ic ,icl ,tname)
            if( ierr .ne. 0 ) return

*-----------------------------------------------------------------------
*        x-txt
*-----------------------------------------------------------------------

         else if( ipm .eq. 7 ) then

               ict = min( ic + 199, i2 )

               cxtxt = chin(ic:ict)

               lxtxt = ict - ic + 1

*-----------------------------------------------------------------------
*        y-txt
*-----------------------------------------------------------------------

         else if( ipm .eq. 8 ) then

               ict = min( ic + 199, i2 )

               cytxt = chin(ic:ict)

               lytxt = ict - ic + 1

*-----------------------------------------------------------------------
*        z-txt
*-----------------------------------------------------------------------

         else if( ipm .eq. 9 ) then

               ict = min( ic + 199, i2 )

               cztxt = chin(ic:ict)

               lztxt = ict - ic + 1

*-----------------------------------------------------------------------
*        factor
*-----------------------------------------------------------------------

         else if( ipm .eq. 6 ) then

               call onum(chlw,ic,icl,cvvv,ierr)

               if( ierr .ne. 0 ) goto 997

               rfact = cvvv

               icl = jnumc(chlw,icl+2,i3)

               if( icl .le. i3 ) goto 200

*-----------------------------------------------------------------------
*        output
*-----------------------------------------------------------------------

         else if( ipm .eq. 10 ) then

               call onum(chlw,ic,icl,cvvv,ierr)

               if( ierr .ne. 0 ) goto 997

               iout = nint( cvvv )

               if( iout .lt. 1 .or. iout .gt. 10 ) goto 980 ! T.Sato 2019/02/20

               icl = jnumc(chlw,icl+2,i3)

               if( icl .le. i3 ) goto 200

*-----------------------------------------------------------------------
*        infog
*-----------------------------------------------------------------------

         else if( ipm .eq. 17 ) then

               call onum(chlw,ic,icl,cvvv,ierr)

               if( ierr .ne. 0 ) goto 997

               infog = nint( cvvv )

               icl = jnumc(chlw,icl+2,i3)

               if( icl .le. i3 ) goto 200

*-----------------------------------------------------------------------
*        gslat
*-----------------------------------------------------------------------

         else if( ipm .eq. 16 ) then

               call onum(chlw,ic,icl,cvvv,ierr)

               if( ierr .ne. 0 ) goto 997

               igslt = nint( cvvv )

               icl = jnumc(chlw,icl+2,i3)

               if( icl .le. i3 ) goto 200

*-----------------------------------------------------------------------
*        epsout
*-----------------------------------------------------------------------

         else if( ipm .eq. 11 ) then

               call onum(chlw,ic,icl,cvvv,ierr)

               if( ierr .ne. 0 ) goto 997

               ieps = nint( cvvv )

               icl = jnumc(chlw,icl+2,i3)

               if( icl .le. i3 ) goto 200

*-----------------------------------------------------------------------
*        bmpout
*-----------------------------------------------------------------------

         else if( ipm .eq. 18 ) then

               call onum(chlw,ic,icl,cvvv,ierr)

               if( ierr .ne. 0 ) goto 997

               ibmp = nint( cvvv )

               icl = jnumc(chlw,icl+2,i3)

               if( icl .le. i3 ) goto 200

*-----------------------------------------------------------------------
*        vtkout
*-----------------------------------------------------------------------

         else if( ipm .eq. 19 ) then

               call onum(chlw,ic,icl,cvvv,ierr)

               if( ierr .ne. 0 ) goto 997

               ivtk = nint( cvvv )

               icl = jnumc(chlw,icl+2,i3)

               if( icl .le. i3 ) goto 200

*-----------------------------------------------------------------------
*        vtkfmt
*-----------------------------------------------------------------------

         else if( ipm .eq. 20 ) then

               call onum(chlw,ic,icl,cvvv,ierr)

               if( ierr .ne. 0 ) goto 997

               ivtkfmt = nint( cvvv )

               icl = jnumc(chlw,icl+2,i3)

               if( icl .le. i3 ) goto 200

*-----------------------------------------------------------------------
*        resolution
*-----------------------------------------------------------------------

         else if( ipm .eq. 12 ) then

               call onum(chlw,ic,icl,cvvv,ierr)

               if( ierr .ne. 0 ) goto 997

               ireso = nint( cvvv )

               icl = jnumc(chlw,icl+2,i3)

               if( icl .le. i3 ) goto 200

*-----------------------------------------------------------------------
*        width
*-----------------------------------------------------------------------

         else if( ipm .eq. 13 ) then

               call onum(chlw,ic,icl,cvvv,ierr)

               if( ierr .ne. 0 ) goto 997

               width = cvvv

               icl = jnumc(chlw,icl+2,i3)

               if( icl .le. i3 ) goto 200

*-----------------------------------------------------------------------

         end if

            goto 140

*-----------------------------------------------------------------------
*     check
*-----------------------------------------------------------------------

  800 continue

      if( ischn(4) .eq. 0 ) then

            title = '[t-gshow] in xyz mesh'
            titll = 21

      end if

      if( ischn(1) .eq. 0 ) then

         m_err = 'Mesh is not defined in tally '//tname
         ErrCha = ''
         ErrID = 'L:39073/R:tgshow/F:tallsm2.f'
         goto 999

      else if( inaxi .eq. 0 ) then

         m_err = 'Axis is not defined in tally '//tname
         ErrCha = ''
         ErrID = 'L:39080/R:tgshow/F:tallsm2.f'
         goto 999

      else if( infil .eq. 0 ) then

         m_err = 'File is not defined in tally '//tname
         ErrCha = ''
         ErrID = 'L:39087/R:tgshow/F:tallsm2.f'
         goto 999

      else if( inaxi .ne. infil ) then

         m_err = 'Number of Axis and File is different in tally '//tname
         ErrCha = ''
         ErrID = 'L:39094/R:tgshow/F:tallsm2.f'
         goto 999

      else if( itsanf > 1 ) then

         m_err = 'Double definition of sangel is found in tally '//tname
         ErrCha = ''
         ErrID = 'L:39101/R:tgshow/F:tallsm2.f'
         goto 999

      end if

      do i = 1, inaxi

         if( ( iaxis(i) .eq. 1 .or. iaxis(i) .eq. 3 ) .and.
     &       ( ixtp .ne. 2 .and. ixtp .ne. 4 ) ) then

            m_err = 'Axis is xy or zx,'//
     &              ' but x mesh type is not 2 or 4 in tally '//tname
            ErrCha = ''
            ErrID = 'L:39114/R:tgshow/F:tallsm2.f'
            goto 999

         else if( ( iaxis(i) .eq. 2 .or. iaxis(i) .eq. 3 ) .and.
     &           ( iztp .ne. 2 .and. iztp .ne. 4 ) ) then

            m_err = 'Axis is yz or zx,'//
     &              ' but z mesh type is not 2 or 4 in tally '//tname
            ErrCha = ''
            ErrID = 'L:39123/R:tgshow/F:tallsm2.f'
            goto 999

         else if( ( iaxis(i) .eq. 1 .or. iaxis(i) .eq. 2 ) .and.
     &           ( iytp .ne. 2 .and. iytp .ne. 4 ) ) then

            m_err = 'Axis is xy or yz,'//
     &              ' but y mesh type is not 2 or 4 in tally '//tname
            ErrCha = ''
            ErrID = 'L:39132/R:tgshow/F:tallsm2.f'
            goto 999

         end if

      end do

*-----------------------------------------------------------------------

      if ( ibmp .ne. 0 ) then

         if ( imesh .ne. 3 ) then

            m_err = 'Mesh should be xyz on bmpout in tally '//tname
            ErrCha = ''
            ErrID = 'L:39147/R:tgshow/F:tallsm2.f'
            goto 999

         end if

         do i = 1, inaxi

            if ( iaxis(i) .ne. 1 .and.
     &           iaxis(i) .ne. 2 .and.
     &           iaxis(i) .ne. 3 ) then

               m_err = 'Axis should be xy, yz or xz on bmpout'//
     &                 ' in tally '//tname
               ErrCha = ''
               ErrID = 'L:39161/R:tgshow/F:tallsm2.f'
               goto 999

            end if

         end do

      end if

*-----------------------------------------------------------------------

      if ( ivtk .ne. 0 ) then

         if ( imesh .ne. 3 ) then

            m_err = 'Mesh should be xyz on bmpout in tally '//tname
            ErrCha = ''
            ErrID = 'L:39178/R:tgshow/F:tallsm2.f'
            goto 999

         end if

         do i = 1, inaxi

            if ( iaxis(i) .ne. 1 .and.
     &           iaxis(i) .ne. 2 .and.
     &           iaxis(i) .ne. 3 ) then

               m_err = 'Axis should be xy, yz or xz on bmpout'//
     &                 ' in tally '//tname
               ErrCha = ''
               ErrID = 'L:39192/R:tgshow/F:tallsm2.f'
               goto 999

            end if

         end do

      end if

*-----------------------------------------------------------------------
*     summary
*-----------------------------------------------------------------------

                  itnm = itnm + 1

                  if( itnm .gt. itlmax ) goto 986

                  ital( itnm ) = 9

                  itsmn(itnm) = 0
                  itstm(itnm) = 0

*-----------------------------------------------------------------------
*        title
*-----------------------------------------------------------------------

                  ittll(itnm) = titll
                  ittle(itnm) = title

*-----------------------------------------------------------------------
*        angel parameter
*-----------------------------------------------------------------------

               if( langel .gt. 0 ) then

                  itanl(itnm) = langel
                  itang(itnm) = angelp

               else

                  itanl(itnm) = 0

               end if

*-----------------------------------------------------------------------
*        x-txt parameter
*-----------------------------------------------------------------------

               if( lxtxt .gt. 0 ) then

                  itaxl(itnm) = lxtxt
                  itaxt(itnm) = cxtxt

               else

                  itaxl(itnm) = 0

               end if

*-----------------------------------------------------------------------
*        y-txt parameter
*-----------------------------------------------------------------------

               if( lytxt .gt. 0 ) then

                  itayl(itnm) = lytxt
                  itayt(itnm) = cytxt

               else

                  itayl(itnm) = 0

               end if

*-----------------------------------------------------------------------
*        z-txt parameter
*-----------------------------------------------------------------------

               if( lztxt .gt. 0 ) then

                  itazl(itnm) = lztxt
                  itazt(itnm) = cztxt

               else

                  itazl(itnm) = 0

               end if

*-----------------------------------------------------------------------
*        mesh
*-----------------------------------------------------------------------

                  itmsh(itnm) = imesh

         if( imesh .eq. 3 ) then

                  itxty(itnm) = ixtp
                  itxnm(itnm) = inx
                  rtxdl(itnm) = xdel
                  rtxmi(itnm) = xmin
                  rtxma(itnm) = xmax
                  call moddas_reallocate_dbl(
     &                    itlmax, itnm, inx+1, itxrg, das_itxrg)
                  das_itxrg(itxrg(itnm):itxrg(itnm)+inx)
     &                     = gmsh(istxg:istxg+inx)
                  itsmn(itnm) = itsmn(itnm) + inx + 1

                  ityty(itnm) = iytp
                  itynm(itnm) = iny
                  rtydl(itnm) = ydel
                  rtymi(itnm) = ymin
                  rtyma(itnm) = ymax
                  call moddas_reallocate_dbl(
     &                    itlmax, itnm, iny+1, ityrg, das_ityrg)
                  das_ityrg(ityrg(itnm):ityrg(itnm)+iny)
     &                     = gmsh(istyg:istyg+iny)
                  itsmn(itnm) = itsmn(itnm) + iny + 1

                  itzty(itnm) = iztp
                  itznm(itnm) = inz
                  rtzdl(itnm) = zdel
                  rtzmi(itnm) = zmin
                  rtzma(itnm) = zmax
                  call moddas_reallocate_dbl(
     &                    itlmax, itnm, inz+1, itzrg, das_itzrg)
                  das_itzrg(itzrg(itnm):itzrg(itnm)+inz)
     &                     = gmsh(istzg:istzg+inz)
                  itsmn(itnm) = itsmn(itnm) + inz + 1

         end if

*-----------------------------------------------------------------------
*        transformation
*-----------------------------------------------------------------------

                     itmtr(itnm,1) = igkst
                     itmtr(itnm,2) = ktrs
                     itmtr(itnm,3) = idtt
                     itmtr(itnm,4) = 0

               if( igkst .gt. 1 ) then

                  do k = 1, 13

                     rtmtr(itnm,k) = vtrs(k)

                  end do

               end if

*-----------------------------------------------------------------------
*        factor
*-----------------------------------------------------------------------

                  rtfac(itnm) = rfact

*-----------------------------------------------------------------------
*        output
*-----------------------------------------------------------------------

                  itout(itnm) = iout

*-----------------------------------------------------------------------
*        infog
*-----------------------------------------------------------------------

                  itger(itnm) = infog

*-----------------------------------------------------------------------
*        gslat parameter
*-----------------------------------------------------------------------
                  itglt(itnm) = igslt

*-----------------------------------------------------------------------
*        epsout
*-----------------------------------------------------------------------

                  iteps(itnm) = ieps

*-----------------------------------------------------------------------
*        bmpout
*-----------------------------------------------------------------------

                  itbmp(itnm) = ibmp

*-----------------------------------------------------------------------
*        vtkout
*-----------------------------------------------------------------------

                  itvtk(itnm) = ivtk

*-----------------------------------------------------------------------
*        vtkfmt
*-----------------------------------------------------------------------

                  itvtkfmt(itnm) = ivtkfmt

*-----------------------------------------------------------------------
*        resolution
*-----------------------------------------------------------------------

                  itres(itnm) = max( 1, ireso )

*-----------------------------------------------------------------------
*        width
*-----------------------------------------------------------------------

                  rtwid(itnm) = width

*-----------------------------------------------------------------------
*        axis
*-----------------------------------------------------------------------

                  itaxn(itnm) = inaxi

               do i = 1, inaxi

                  itaxs(itnm,i) = iaxis(i)

               end do

*-----------------------------------------------------------------------
*        file
*-----------------------------------------------------------------------

                  itfln(itnm) = infil

               do i = 1, infil

                  itfll(itnm,i) = lfile(i)

                  ctfln(itnm,i)(1:lfile(i)) = ifile(i)(1:lfile(i))

                  do k = lfile(i) + 1, 100

                     ctfln(itnm,i)(k:k) = ' '

                  end do

               end do

*-----------------------------------------------------------------------

      return

*-----------------------------------------------------------------------
*     errors
*-----------------------------------------------------------------------

  986    write(dkam,'(i5)') itlmax
         m_err = 'Total tally number exceeds itlmax = '//dkam
         ErrCha = ''
         ErrID = 'L:39445/R:tgshow/F:tallsm2.f'
         goto 999

  987    m_err = 'Unknown parameter in tally '//tname
         ErrCha = ''
         ErrID = 'L:39450/R:tgshow/F:tallsm2.f'
         goto 999

  989    m_err = 'Double definition of the parameter in tally '//tname
         ErrCha = ''
         ErrID = 'L:39455/R:tgshow/F:tallsm2.f'
         goto 999

  980    m_err = 'output should be 1 - 10 in tally '//tname
         ErrCha = ''
         ErrID = 'L:39460/R:tgshow/F:tallsm2.f'
         goto 999

  990    m_err = 'Too many file name in tally '//tname
         ErrCha = ''
         ErrID = 'L:39465/R:tgshow/F:tallsm2.f'
         goto 999

  991    m_err = 'only one axis is available in tally '//tname
         ErrCha = ''
         ErrID = 'L:39470/R:tgshow/F:tallsm2.f'
         goto 999

  992    m_err = 'Unknown axis name in tally '//tname
         ErrCha = ''
         ErrID = 'L:39475/R:tgshow/F:tallsm2.f'
         goto 999

  993    m_err = 'In this line, [ ; ] cannot be used.'
         ErrCha = ''
         ErrID = 'L:39480/R:tgshow/F:tallsm2.f'
         goto 999

  996    m_err = 'Description of mesh is wrong in tally '//tname
         ErrCha = ''
         ErrID = 'L:39485/R:tgshow/F:tallsm2.f'
         goto 999

  997    m_err = 'Description of parameter is wrong in tally '//tname
         ErrCha = ''
         ErrID = 'L:39490/R:tgshow/F:tallsm2.f'
         goto 999

  998    m_err = 'Unknown mesh parameter in tally '//tname
         ErrCha = ''
         ErrID = 'L:39495/R:tgshow/F:tallsm2.f'
         goto 999

*-----------------------------------------------------------------------

  999 continue

         l_err = ill(jsn)
         k_err = jsn
         ierr  = 1

*-----------------------------------------------------------------------

      return
      end


************************************************************************
*                                                                      *
      subroutine trshow(jsn,jsi,dsin,idsi,ill,ilf,
     &                  jpn,chin,chlw,chcm,i1,i2,i3,i4,ierr)
*                                                                      *
*       read [t-rshow] section of input files                          *
*       modified by K.Niita on 2004/09/15                              *
*                                                                      *
************************************************************************
      use sangelmod, only: itsanf
      use moddas
      use moddas_mesh
      use moddas_region

      implicit real*8 (a-h,o-z)

      include 'param.inc'
      include 'err.inc'

*-----------------------------------------------------------------------

      common /tall00/ itnm, ital(itlmax), itals(itlmax), italm(itlmax)
      common /tall01/ itmsh(itlmax), itunt(itlmax), itspc(itlmax),
     &                itout(itlmax), ittwo(itlmax)

      common /tall02/ itrgn(itlmax), itrgm(itlmax), itreg(itlmax)
      common /tall25/ itrnv(itlmax), itriv(itlmax), itrrv(itlmax)

      common /tall04/ itxty(itlmax), itxnm(itlmax), itxrg(itlmax),
     &                rtxmi(itlmax), rtxma(itlmax), rtxdl(itlmax)
      common /tall05/ ityty(itlmax), itynm(itlmax), ityrg(itlmax),
     &                rtymi(itlmax), rtyma(itlmax), rtydl(itlmax)
      common /tall06/ itzty(itlmax), itznm(itlmax), itzrg(itlmax),
     &                rtzmi(itlmax), rtzma(itlmax), rtzdl(itlmax)

      common /tall10/ itaxn(itlmax), itaxs(itlmax,6)
      common /tall11/ itfln(itlmax), itfll(itlmax,6), ctfln(itlmax,6)
      character ctfln*100

      common /tall14/ ittll(itlmax), ittle(itlmax)
      character ittle*80

      common /tall15/ itanl(itlmax), itang(itlmax)
      character itang*200

      common /tall27/ itaxl(itlmax), itaxt(itlmax),
     &                itayl(itlmax), itayt(itlmax),
     &                itazl(itlmax), itazt(itlmax)
      character itaxt*200, itayt*200, itazt*200

      common /tall19/ itsmn(itlmax), itstm(itlmax)

      common /tall21/ rtfac(itlmax)
      common /tall31/ iterl(itlmax)
      common /tall35/ iteps(itlmax)

      common /tall38/ itres(itlmax)
      common /tall39/ rtwid(itlmax)
      common /tall46/ itmtr(itlmax,4), rtmtr(itlmax,13)

      common /tall49/ itglt(itlmax)

      common /tall60/ itger(itlmax)
      common /tall63/ itbmp(itlmax)

      dimension idas(1)
      equivalence ( das, idas )

*-----------------------------------------------------------------------

      character m_err*200
      common /error/ m_err, l_err, k_err

*-----------------------------------------------------------------------

      character title*80
      character angelp*200
      character cxtxt*200
      character cytxt*200
      character cztxt*200

*-----------------------------------------------------------------------

      dimension lschn(21), ischn(21)
      character schan(21)*8

      data icsu / 21 /

      data ( schan(i), i = 1, 21 ) /
     &    'mesh    ','axis    ','file    ','title   ','angel   ',
     &    'factor  ','x-txt   ','y-txt   ','z-txt   ','output  ',
     &    'reg     ','iechrl  ','epsout  ','resol   ','width   ',
     &    'trcl    ','*trcl   ','gslat   ','ginfo   ','bmpout  ',
     &    'sangel  '/

      data ( lschn(i), i = 1, 21 ) /
     &     4,         4,         4,         5,         5,
     &     6,         5,         5,         5,         6,
     &     3,         6,         6,         5,         5,
     &     4,         5,         5,         5,         6,
     &     6/

*-----------------------------------------------------------------------

      dimension iaxis(6)
      character ifile(6)*100
      dimension lfile(6)
      dimension vtrs(13)

*-----------------------------------------------------------------------

      character chin*200, chlw*200, chcm*200
      character chlc*200

      character dsin(0:9)*200
      dimension idsi(0:9)

      dimension ill(0:9), ilf(0:9)

      character dkam*9

      character tname*9
      data      tname /'[t-rshow]'/

*-----------------------------------------------------------------------

            ierr  = 0

            inaxi = 0
            infil = 0

            langel = 0
            itsanf = 0
            lxtxt  = 0
            lytxt  = 0
            lztxt  = 0
            iout   = 1
            iechrl = 72
            ieps   = 0
            ibmp   = 0
            igkst  = 0
            idtt   = 0
            ktrs   = 0
            igslt  = -1

            ireso = 1
            width = 0.5

            rfact = 0.5

         do i = 1, icsu

            ischn(i) = 0

         end do

            ginfo = 2

*-----------------------------------------------------------------------
*     read one line from jsi
*-----------------------------------------------------------------------

  140 continue

            call readl(jsn,jsi,dsin,idsi,ill,ilf,'#!$',
     &                 jpn,chin,chlw,chcm,i1,i2,i3,i4,iskip,ierr)

               if( ierr .ne. 0 ) return
               if( jpn  .eq. 3 ) goto 800

               if( iskip .ne. 0 ) goto 140

  150 continue

               if( ierr .ne. 0 ) return
               if( jpn  .eq. 3 ) goto 800

*-----------------------------------------------------------------------
*        end of the section
*-----------------------------------------------------------------------

            if( chlw(i1:i1) .eq. '[' ) then

               jpn = 1
               goto 800

            end if

*-----------------------------------------------------------------------
*        identify the parameters
*-----------------------------------------------------------------------

            icl = i1

  200    continue

            chlc = chlw
            call chcomp(chlc,icl,i3,i5)

         do i = 1, icsu

            il = icl + lschn(i) - 1

            if( chlc(icl:il) .eq. schan(i)(1:lschn(i)) ) goto 100

         end do

               goto 987

*-----------------------------------------------------------------------
*        read value of parameters
*-----------------------------------------------------------------------

  100    continue

               ipm = i

               ischn( ipm ) = ischn( ipm ) + 1

            if( ipm .ne. 2 .and. ipm .ne. 3 .and.
     &          ischn( ipm ) .gt. 1 ) goto 989

               ic = inumc(chlw,il+1,i3,'=') + 1
               ic = jnumc(chlw,ic,i3)

               if( ic .gt. i3 ) goto 997

               icl = inumc(chlw,ic,i3,';') - 1

*-----------------------------------------------------------------------
*        mesh = xyz only
*-----------------------------------------------------------------------

         if( ipm .eq. 1 ) then

            if( chlw(ic:ic+2) .eq. 'xyz' ) then

               imesh = 3

            else

               goto 998

            end if

            if( chlw(icl+1:icl+1) .eq. ';' ) goto 993

            if( imesh .eq. 3 ) then

               call txymesh(jsn,jsi,dsin,idsi,ill,ilf,
     &                      jpn,chin,chlw,chcm,i1,i2,i3,i4,ierr,
     &                      ixtp,inx,xmin,xmax,xdel,istxg,
     &                      iytp,iny,ymin,ymax,ydel,istyg,
     &                      iztp,inz,zmin,zmax,zdel,istzg)

                  if( ierr .ne. 0 ) return
                  if( jpn  .eq. 3 ) goto 800
                  if( ixtp .lt. 0 ) goto 996
                  if( iytp .lt. 0 ) goto 996
                  if( iztp .lt. 0 ) goto 996

            end if

                  goto 150

*-----------------------------------------------------------------------
*        axis
*-----------------------------------------------------------------------

         else if( ipm .eq. 2 ) then

  600       inaxi = inaxi + 1

            if( inaxi .gt. 1 ) goto 991

            if( chlw(ic:ic+1) .eq. 'xy' .or.
     &          chlw(ic:ic+1) .eq. 'yx' ) then

               iaxis(inaxi) = 1
               ic =jnumc(chlw,ic+3,icl)

            else if( chlw(ic:ic+1) .eq. 'yz' .or.
     &               chlw(ic:ic+1) .eq. 'zy' ) then

               iaxis(inaxi) = 2
               ic =jnumc(chlw,ic+3,icl)

            else if( chlw(ic:ic+1) .eq. 'zx' .or.
     &               chlw(ic:ic+1) .eq. 'xz' ) then

               iaxis(inaxi) = 3
               ic =jnumc(chlw,ic+3,icl)

            else

               goto 992

            end if

               if( ic .le. icl ) goto 600

               icl = jnumc(chlw,icl+2,i3)

               if( icl .le. i3 ) goto 200

*-----------------------------------------------------------------------
*        region and values
*-----------------------------------------------------------------------

         else if( ipm .eq. 11 ) then

               call moddas_allocate_int(
     &                 MAX_NUM_ITREG, idas_itreg_temporary)

               ndsm = 1
               call tregion(1,jsn,jsi,dsin,idsi,ill,ilf,
     &                      jpn,chin,chlw,chcm,i1,i2,i3,i4,ierr,
     &                      ntrn,mtrn,ndsm,nvol,ivl,irvl,1
     &                      ,MAX_NUM_ITREG,idas_itreg_temporary)

               if( mtrn > MAX_NUM_ITREG ) then
                  write(ErrCha,'(a,a,i5,a,a,i5,a)')
     &                 'sub.trshow@tallsm2.f'
     &                    //' ?dimension over idas_itreg_temporary?'
     &                    //' mtrn > MAX_NUM_ITREG'
     &                 ,' (mtrn=',mtrn,')'
     &                 ,' (MAX_NUM_ITREG@moddas.f=',MAX_NUM_ITREG,')'
                  ErrID = 'L:39839/R:trshow/F:tallsm2.f'
                  call ErrWrite(ErrID,ErrCha)
               endif

                  if( ierr .ne. 0 ) return
                  if( jpn  .eq. 3 ) goto 800
                  if( ntrn .lt. -1 ) goto 996

                  goto 150

*-----------------------------------------------------------------------
*        transform
*-----------------------------------------------------------------------

         else if( ipm .eq. 16 .or. ipm .eq. 17 ) then

                  if( ipm .eq. 17 ) ktrs = 1

               call ttrans(jsn,jsi,dsin,idsi,ill,ilf,
     &                     jpn,chin,chlw,chcm,i1,i2,i3,i4,ierr,
     &                     ic,ktrs,igkst,idtt,vtrs)

               if( ierr .ne. 0 ) return

               goto 150

*-----------------------------------------------------------------------
*        file name
*-----------------------------------------------------------------------

         else if( ipm .eq. 3 ) then

  700          infil = infil + 1

               if( infil .gt. 6 ) goto 990

               icf = min( inumc(chlw,ic,icl,' ') - 1, icl )

               lfile(infil) = icf - ic + 1
               ifile(infil)(1:icf-ic+1) = chin(ic:icf)

               ic = jnumc(chlw,icf+2,icl)

               if( ic .le. icl ) goto 700

               icl = jnumc(chlw,icl+2,i3)

               if( icl .le. i3 ) goto 200

*-----------------------------------------------------------------------
*        title
*-----------------------------------------------------------------------

         else if( ipm .eq. 4 ) then

               ict = min( ic + 79, i2 )

               title = chin(ic:ict)

               titll = ict - ic + 1

*-----------------------------------------------------------------------
*        angel parameters
*-----------------------------------------------------------------------

         else if( ipm .eq. 5 ) then

               ict = min( ic + 199, i3 )

               angelp = chin(ic:ict)

               langel = ict - ic + 1

!-----------------------------------------------------------------------
!        sangel parameters
!-----------------------------------------------------------------------

         else if( ipm .eq. 21 ) then

            itsanf = itsanf + 1

            call read_sangel(jsn,jsi,dsin,idsi,ill,ilf,
     &                       jpn,chin,chlw,chcm,i1,i2,i3,i4,iskip,ierr
     &                      ,ic ,icl ,tname)
            if( ierr .ne. 0 ) return

*-----------------------------------------------------------------------
*        x-txt
*-----------------------------------------------------------------------

         else if( ipm .eq. 7 ) then

               ict = min( ic + 199, i2 )

               cxtxt = chin(ic:ict)

               lxtxt = ict - ic + 1

*-----------------------------------------------------------------------
*        y-txt
*-----------------------------------------------------------------------

         else if( ipm .eq. 8 ) then

               ict = min( ic + 199, i2 )

               cytxt = chin(ic:ict)

               lytxt = ict - ic + 1

*-----------------------------------------------------------------------
*        z-txt
*-----------------------------------------------------------------------

         else if( ipm .eq. 9 ) then

               ict = min( ic + 199, i2 )

               cztxt = chin(ic:ict)

               lztxt = ict - ic + 1

*-----------------------------------------------------------------------
*        factor
*-----------------------------------------------------------------------

         else if( ipm .eq. 6 ) then

               call onum(chlw,ic,icl,cvvv,ierr)

               if( ierr .ne. 0 ) goto 997

               rfact = cvvv

               icl = jnumc(chlw,icl+2,i3)

               if( icl .le. i3 ) goto 200

*-----------------------------------------------------------------------
*        gslat
*-----------------------------------------------------------------------

         else if( ipm .eq. 18 ) then

               call onum(chlw,ic,icl,cvvv,ierr)

               if( ierr .ne. 0 ) goto 997

               igslt = nint( cvvv )

               icl = jnumc(chlw,icl+2,i3)

               if( icl .le. i3 ) goto 200

*-----------------------------------------------------------------------
*        reg echo length
*-----------------------------------------------------------------------

         else if( ipm .eq. 12 ) then

               call onum(chlw,ic,icl,cvvv,ierr)

               if( ierr .ne. 0 ) goto 997

               iechrl = nint( cvvv )

               if( iechrl .lt. 40 ) goto 997

               icl = jnumc(chlw,icl+2,i3)

               if( icl .le. i3 ) goto 200

*-----------------------------------------------------------------------
*        output
*-----------------------------------------------------------------------

         else if( ipm .eq. 10 ) then

               call onum(chlw,ic,icl,cvvv,ierr)

               if( ierr .ne. 0 ) goto 997

               iout = nint( cvvv )

               if( iout .lt. 1 .or. iout .gt. 4 ) goto 980

               icl = jnumc(chlw,icl+2,i3)

               if( icl .le. i3 ) goto 200

*-----------------------------------------------------------------------
*        epsout
*-----------------------------------------------------------------------

         else if( ipm .eq. 13 ) then

               call onum(chlw,ic,icl,cvvv,ierr)

               if( ierr .ne. 0 ) goto 997

               ieps = nint( cvvv )

               icl = jnumc(chlw,icl+2,i3)

               if( icl .le. i3 ) goto 200

*-----------------------------------------------------------------------
*        bmpout
*-----------------------------------------------------------------------

         else if( ipm .eq. 20 ) then

               call onum(chlw,ic,icl,cvvv,ierr)

               if( ierr .ne. 0 ) goto 997

               ibmp = nint( cvvv )

               icl = jnumc(chlw,icl+2,i3)

               if( icl .le. i3 ) goto 200

*-----------------------------------------------------------------------
*        resolution
*-----------------------------------------------------------------------

         else if( ipm .eq. 14 ) then

               call onum(chlw,ic,icl,cvvv,ierr)

               if( ierr .ne. 0 ) goto 997

               ireso = nint( cvvv )

               icl = jnumc(chlw,icl+2,i3)

               if( icl .le. i3 ) goto 200

*-----------------------------------------------------------------------
*        width
*-----------------------------------------------------------------------

         else if( ipm .eq. 15 ) then

               call onum(chlw,ic,icl,cvvv,ierr)

               if( ierr .ne. 0 ) goto 997

               width = cvvv

               icl = jnumc(chlw,icl+2,i3)

               if( icl .le. i3 ) goto 200

*-----------------------------------------------------------------------
*        ginfo
*-----------------------------------------------------------------------

         else if( ipm .eq. 19 ) then

               call onum(chlw,ic,icl,cvvv,ierr)

               if( ierr .ne. 0 ) goto 997

               ginfo = nint( cvvv )

               icl = jnumc(chlw,icl+2,i3)

               if( icl .le. i3 ) goto 200

*-----------------------------------------------------------------------

         end if

            goto 140

*-----------------------------------------------------------------------
*     check
*-----------------------------------------------------------------------

  800 continue

      if( ischn(4) .eq. 0 ) then

            title = '[t-rshow] in xyz mesh'
            titll = 21

      end if

      if( ischn(11) .eq. 0 ) then

         m_err = 'reg = is not defined in tally '//tname
         ErrCha = ''
         ErrID = 'L:40132/R:trshow/F:tallsm2.f'
         goto 999

      else if( ischn(1) .eq. 0 ) then

         m_err = 'Mesh is not defined in tally '//tname
         ErrCha = ''
         ErrID = 'L:40139/R:trshow/F:tallsm2.f'
         goto 999

      else if( inaxi .eq. 0 ) then

         m_err = 'Axis is not defined in tally '//tname
         ErrCha = ''
         ErrID = 'L:40146/R:trshow/F:tallsm2.f'
         goto 999

      else if( infil .eq. 0 ) then

         m_err = 'File is not defined in tally '//tname
         ErrCha = ''
         ErrID = 'L:40153/R:trshow/F:tallsm2.f'
         goto 999

      else if( inaxi .ne. infil ) then

         m_err = 'Number of Axis and File is different in tally '//tname
         ErrCha = ''
         ErrID = 'L:40160/R:trshow/F:tallsm2.f'
         goto 999

      else if( itsanf > 1 ) then

         m_err = 'Double definition of sangel is found in tally '//tname
         ErrCha = ''
         ErrID = 'L:40167/R:trshow/F:tallsm2.f'
         goto 999

      end if

      do i = 1, inaxi

         if( ( iaxis(i) .eq. 1 .or. iaxis(i) .eq. 3 ) .and.
     &       ( ixtp .ne. 2 .and. ixtp .ne. 4 ) ) then

            m_err = 'Axis is xy or zx,'//
     &              ' but x mesh type is not 2 or 4 in tally '//tname
            ErrCha = ''
            ErrID = 'L:40180/R:trshow/F:tallsm2.f'
            goto 999

         else if( ( iaxis(i) .eq. 2 .or. iaxis(i) .eq. 3 ) .and.
     &           ( iztp .ne. 2 .and. iztp .ne. 4 ) ) then

            m_err = 'Axis is yz or zx,'//
     &              ' but z mesh type is not 2 or 4 in tally '//tname
            ErrCha = ''
            ErrID = 'L:40189/R:trshow/F:tallsm2.f'
            goto 999

         else if( ( iaxis(i) .eq. 1 .or. iaxis(i) .eq. 2 ) .and.
     &           ( iytp .ne. 2 .and. iytp .ne. 4 ) ) then

            m_err = 'Axis is xy or yz,'//
     &              ' but y mesh type is not 2 or 4 in tally '//tname
            ErrCha = ''
            ErrID = 'L:40198/R:trshow/F:tallsm2.f'
            goto 999

         end if

      end do

*-----------------------------------------------------------------------

      if ( ibmp .ne. 0 ) then

         if ( imesh .ne. 3 ) then

            m_err = 'Mesh should be xyz on bmpout in tally '//tname
            ErrCha = ''
            ErrID = 'L:40213/R:trshow/F:tallsm2.f'
            goto 999

         end if

         do i = 1, inaxi

            if ( iaxis(i) .ne. 1 .and.
     &           iaxis(i) .ne. 2 .and.
     &           iaxis(i) .ne. 3 ) then

               m_err = 'Axis should be xy, yz or xz on bmpout'//
     &                 ' in tally '//tname
               ErrCha = ''
               ErrID = 'L:40227/R:trshow/F:tallsm2.f'
               goto 999

            end if

         end do

      end if

*-----------------------------------------------------------------------
*     summary
*-----------------------------------------------------------------------

                  itnm = itnm + 1

                  if( itnm .gt. itlmax ) goto 986

                  ital( itnm ) = 10

                  itsmn(itnm) = 0
                  itstm(itnm) = 0

*-----------------------------------------------------------------------
*        title
*-----------------------------------------------------------------------

                  ittll(itnm) = titll
                  ittle(itnm) = title

*-----------------------------------------------------------------------
*        angel parameter
*-----------------------------------------------------------------------

               if( langel .gt. 0 ) then

                  itanl(itnm) = langel
                  itang(itnm) = angelp

               else

                  itanl(itnm) = 0

               end if

*-----------------------------------------------------------------------
*        x-txt parameter
*-----------------------------------------------------------------------

               if( lxtxt .gt. 0 ) then

                  itaxl(itnm) = lxtxt
                  itaxt(itnm) = cxtxt

               else

                  itaxl(itnm) = 0

               end if

*-----------------------------------------------------------------------
*        y-txt parameter
*-----------------------------------------------------------------------

               if( lytxt .gt. 0 ) then

                  itayl(itnm) = lytxt
                  itayt(itnm) = cytxt

               else

                  itayl(itnm) = 0

               end if

*-----------------------------------------------------------------------
*        z-txt parameter
*-----------------------------------------------------------------------

               if( lztxt .gt. 0 ) then

                  itazl(itnm) = lztxt
                  itazt(itnm) = cztxt

               else

                  itazl(itnm) = 0

               end if

*-----------------------------------------------------------------------
*        mesh
*-----------------------------------------------------------------------

                  itmsh(itnm) = imesh

         if( imesh .eq. 3 ) then

                  itxty(itnm) = ixtp
                  itxnm(itnm) = inx
                  rtxdl(itnm) = xdel
                  rtxmi(itnm) = xmin
                  rtxma(itnm) = xmax
                  call moddas_reallocate_dbl(
     &                    itlmax, itnm, inx+1, itxrg, das_itxrg)
                  das_itxrg(itxrg(itnm):itxrg(itnm)+inx)
     &                     = gmsh(istxg:istxg+inx)
                  itsmn(itnm) = itsmn(itnm) + inx + 1

                  ityty(itnm) = iytp
                  itynm(itnm) = iny
                  rtydl(itnm) = ydel
                  rtymi(itnm) = ymin
                  rtyma(itnm) = ymax
                  call moddas_reallocate_dbl(
     &                    itlmax, itnm, iny+1, ityrg, das_ityrg)
                  das_ityrg(ityrg(itnm):ityrg(itnm)+iny)
     &                     = gmsh(istyg:istyg+iny)
                  itsmn(itnm) = itsmn(itnm) + iny + 1

                  itzty(itnm) = iztp
                  itznm(itnm) = inz
                  rtzdl(itnm) = zdel
                  rtzmi(itnm) = zmin
                  rtzma(itnm) = zmax
                  call moddas_reallocate_dbl(
     &                    itlmax, itnm, inz+1, itzrg, das_itzrg)
                  das_itzrg(itzrg(itnm):itzrg(itnm)+inz)
     &                     = gmsh(istzg:istzg+inz)
                  itsmn(itnm) = itsmn(itnm) + inz + 1

         end if

*-----------------------------------------------------------------------
*        reg mesh and values
*-----------------------------------------------------------------------

                  itrgn(itnm) = ntrn
                  itrgm(itnm) = mtrn
                  itrnv(itnm) = nvol

            if( ntrn .gt. 0 ) then

                  call moddas_reallocate_int(
     &                    itlmax, itnm, mtrn, itreg, idas_itreg)
                  idas_itreg(itreg(itnm):itreg(itnm)+mtrn-1)
     &                      = idas_itreg_temporary(1:mtrn)
                  call moddas_deallocate_int(idas_itreg_temporary)
                  itsmn(itnm) = itsmn(itnm)
     &                        + ( mtrn + mod(mtrn,2) ) / 2

            else

               goto 985

            end if

            if( nvol .gt. 0 ) then

                  itriv(itnm) = ivl
                  itsmn(itnm) = itsmn(itnm)
     &                        + ( nvol + mod(nvol,2) ) / 2

                  itrrv(itnm) = irvl
                  itsmn(itnm) = itsmn(itnm) + nvol

            else

               goto 985

            end if

*-----------------------------------------------------------------------
*        transformation
*-----------------------------------------------------------------------

                     itmtr(itnm,1) = igkst
                     itmtr(itnm,2) = ktrs
                     itmtr(itnm,3) = idtt
                     itmtr(itnm,4) = 0

               if( igkst .gt. 1 ) then

                  do k = 1, 13

                     rtmtr(itnm,k) = vtrs(k)

                  end do

               end if

*-----------------------------------------------------------------------
*        reg echo length
*-----------------------------------------------------------------------

                  iterl(itnm) = iechrl

*-----------------------------------------------------------------------
*        factor
*-----------------------------------------------------------------------

                  rtfac(itnm) = rfact

*-----------------------------------------------------------------------
*        gslat parameter
*-----------------------------------------------------------------------
                  itglt(itnm) = igslt

*-----------------------------------------------------------------------
*        output
*-----------------------------------------------------------------------

                  itout(itnm) = iout

*-----------------------------------------------------------------------
*        epsout
*-----------------------------------------------------------------------

                  iteps(itnm) = ieps

*-----------------------------------------------------------------------
*        bmpout
*-----------------------------------------------------------------------

                  itbmp(itnm) = ibmp

*-----------------------------------------------------------------------
*        resolution
*-----------------------------------------------------------------------

                  itres(itnm) = max( 1, ireso )

*-----------------------------------------------------------------------
*        width
*-----------------------------------------------------------------------

                  rtwid(itnm) = width

*-----------------------------------------------------------------------
*        ginfo
*-----------------------------------------------------------------------

                  itger(itnm) = ginfo

*-----------------------------------------------------------------------
*        axis
*-----------------------------------------------------------------------

                  itaxn(itnm) = inaxi

               do i = 1, inaxi

                  itaxs(itnm,i) = iaxis(i)

               end do

*-----------------------------------------------------------------------
*        file
*-----------------------------------------------------------------------

                  itfln(itnm) = infil

               do i = 1, infil

                  itfll(itnm,i) = lfile(i)

                  ctfln(itnm,i)(1:lfile(i)) = ifile(i)(1:lfile(i))

                  do k = lfile(i) + 1, 100

                     ctfln(itnm,i)(k:k) = ' '

                  end do

               end do

*-----------------------------------------------------------------------

      return

*-----------------------------------------------------------------------
*     errors
*-----------------------------------------------------------------------

  985    m_err = 'reg/val is not defined in tally '//tname
         ErrCha = ''
         ErrID = 'L:40512/R:trshow/F:tallsm2.f'
         goto 999

  986    write(dkam,'(i5)') itlmax
         m_err = 'Total tally number exceeds itlmax = '//dkam
         ErrCha = ''
         ErrID = 'L:40518/R:trshow/F:tallsm2.f'
         goto 999

  987    m_err = 'Unknown parameter in tally '//tname
         ErrCha = ''
         ErrID = 'L:40523/R:trshow/F:tallsm2.f'
         goto 999

  989    m_err = 'Double definition of the parameter in tally '//tname
         ErrCha = ''
         ErrID = 'L:40528/R:trshow/F:tallsm2.f'
         goto 999

  980    m_err = 'output should be 1, 2 or 3 in tally '//tname
         ErrCha = ''
         ErrID = 'L:40533/R:trshow/F:tallsm2.f'
         goto 999

  990    m_err = 'Too many file name in tally '//tname
         ErrCha = ''
         ErrID = 'L:40538/R:trshow/F:tallsm2.f'
         goto 999

  991    m_err = 'only one axis is available in tally '//tname
         ErrCha = ''
         ErrID = 'L:40543/R:trshow/F:tallsm2.f'
         goto 999

  992    m_err = 'Unknown axis name in tally '//tname
         ErrCha = ''
         ErrID = 'L:40548/R:trshow/F:tallsm2.f'
         goto 999

  993    m_err = 'In this line, [ ; ] cannot be used.'
         ErrCha = ''
         ErrID = 'L:40553/R:trshow/F:tallsm2.f'
         goto 999

  996    m_err = 'Description of mesh is wrong in tally '//tname
         ErrCha = ''
         ErrID = 'L:40558/R:trshow/F:tallsm2.f'
         goto 999

  997    m_err = 'Description of parameter is wrong in tally '//tname
         ErrCha = ''
         ErrID = 'L:40563/R:trshow/F:tallsm2.f'
         goto 999

  998    m_err = 'Unknown mesh parameter in tally '//tname
         ErrCha = ''
         ErrID = 'L:40568/R:trshow/F:tallsm2.f'
         goto 999

*-----------------------------------------------------------------------

  999 continue

         l_err = ill(jsn)
         k_err = jsn
         ierr  = 1

*-----------------------------------------------------------------------

      return
      end


************************************************************************
*                                                                      *
      subroutine tdshow(jsn,jsi,dsin,idsi,ill,ilf,
     &                  jpn,chin,chlw,chcm,i1,i2,i3,i4,ierr)
*                                                                      *
*       read [t-3dshow] section of input files                         *
*       modified by K.Niita on 2002/10/22                              *
*                                                                      *
************************************************************************
      use sangelmod, only: itsanf
      use moddas
      use moddas_region
      use moddas_tally

      implicit real*8 (a-h,o-z)

      include 'param.inc'
      include 'err.inc'

      parameter ( pi = 3.141592653589793d0 )

*-----------------------------------------------------------------------

      common /tall00/ itnm, ital(itlmax), itals(itlmax), italm(itlmax)
      common /tall01/ itmsh(itlmax), itunt(itlmax), itspc(itlmax),
     &                itout(itlmax), ittwo(itlmax)

      common /tall11/ itfln(itlmax), itfll(itlmax,6), ctfln(itlmax,6)
      character ctfln*100

      common /tall14/ ittll(itlmax), ittle(itlmax)
      character ittle*80

      common /tall15/ itanl(itlmax), itang(itlmax)
      character itang*200

      common /tall02/ itrgn(itlmax), itrgm(itlmax), itreg(itlmax)
      common /tall25/ itrnv(itlmax), itriv(itlmax), itrrv(itlmax)

      common /tall22/ itmcn(itlmax), itmtn(itlmax), itmtt(itlmax)
      common /tall27/ itaxl(itlmax), itaxt(itlmax),
     &                itayl(itlmax), itayt(itlmax),
     &                itazl(itlmax), itazt(itlmax)
      character itaxt*200, itayt*200, itazt*200

      common /tall19/ itsmn(itlmax), itstm(itlmax)
      common /tall35/ iteps(itlmax)

      common /tall38/ itres(itlmax)
      common /tall39/ rtwid(itlmax)

      common /tall40/ rtorg(itlmax,3), rteye(itlmax,3), rtlit(itlmax,3),
     &                rtwin(itlmax,3), rtbrt(itlmax,2), ithvn(itlmax),
     &                itwin(itlmax,2), itbox(itlmax), itmir(itlmax),
     &                rtbox(itlmax,5,10), rtout(itlmax), rthet(itlmax),
     &                itlin(itlmax), itshd(itlmax), itgxs(itlmax)

      common /tall42/ itmbn(itlmax), itmbt(itlmax)
      common /tall43/ itmgn(itlmax), itmgm(itlmax), itmeg(itlmax)

      common /tall47/ itbtr(itlmax,5,4), rtbtr(itlmax,5,13)

      dimension idas(1)
      equivalence ( das, idas )

*-----------------------------------------------------------------------

      character m_err*200
      common /error/ m_err, l_err, k_err

      common /inggs/  iog, igcel, ioa, igsuf, iob, igtrs
      common /celdb/ idsn(kvlmax), idtn(kvlmax)

*-----------------------------------------------------------------------

      character title*80
      character angelp*200
      character cxtxt*200
      character cytxt*200
      character cztxt*200

*-----------------------------------------------------------------------


      dimension lschn(39), ischn(39)
      character schan(39)*8

      data icsu / 39 /

      data ( schan(i), lschn(i), i = 1, 39 ) /
     &     'material', 8,  ! 1
     &     'reginbox', 8,  ! 2
     &     'file    ', 4,  ! 3
     &     'title   ', 5,  ! 4
     &     'angel   ', 5,  ! 5
     &     'x-txt   ', 5,  ! 6
     &     'y-txt   ', 5,  ! 7
     &     'z-txt   ', 5,  ! 8
     &     'epsout  ', 6,  ! 9
     &     'resol   ', 5,  ! 10
     &     'width   ', 5,  ! 11
     &     'x0      ', 2,  ! 12
     &     'y0      ', 2,  ! 13
     &     'z0      ', 2,  ! 14
     &     'e-the   ', 5,  ! 15
     &     'e-phi   ', 5,  ! 16
     &     'e-dst   ', 5,  ! 17
     &     'l-the   ', 5,  ! 18
     &     'l-phi   ', 5,  ! 19
     &     'l-dst   ', 5,  ! 20
     &     'w-wdt   ', 5,  ! 21
     &     'w-hgt   ', 5,  ! 22
     &     'w-dst   ', 5,  ! 23
     &     'w-mnw   ', 5,  ! 24
     &     'w-mnh   ', 5,  ! 25
     &     'bright  ', 6,  ! 26
     &     'dark    ', 4,  ! 27
     &     'heaven  ', 6,  ! 28
     &     'box     ', 3,  ! 29
     &     'output  ', 6,  ! 30
     &     'r-out   ', 5,  ! 31
     &     'line    ', 4,  ! 32
     &     'shadow  ', 6,  ! 33
     &     'matinbox', 8,  ! 34
     &     'reg     ', 3,  ! 35
     &     'w-ang   ', 5,  ! 36
     &     'mirror  ', 6,  ! 37
     &     'axishow ', 7,  ! 38
     &     'sangel  ', 6/  ! 39

*-----------------------------------------------------------------------


      character ifile(6)*100
      dimension lfile(6)

      dimension org(3), eye(3), cli(3), win(3), nwn(2), brt(2)
      dimension box(5,10)

      dimension vtrs(13)
      dimension ibtr(5,3), rbtr(5,13)

*-----------------------------------------------------------------------

      character chin*200, chlw*200, chcm*200
      character chlc*200

      character dsin(0:9)*200
      dimension idsi(0:9)

      dimension ill(0:9), ilf(0:9)

      character dkam*9

      character tname*10
      data      tname /'[t-3dshow]'/

      logical deqn4

*-----------------------------------------------------------------------

            ierr  = 0

            org(1) = 0.0d0
            org(2) = 0.0d0
            org(3) = 0.0d0

            win(1) = 100.d0
            win(2) = 100.d0
            win(3) = 200.d0

            eye(1) = 80.0d0
            eye(2) = 140.0d0
            eye(3) = win(3) * 10.0

            cli(1) = eye(1)
            cli(2) = eye(2)
            cli(3) = eye(3)

            nwn(1) = 100
            nwn(2) = 100

            brt(1) = 0.8d0
            brt(2) = 0.2d0

            ihvn   = 3

            ibox   = 0

            infil = 0
            icreg = 0
            ibreg = 0

            langel = 0
            itsanf = 0
            lxtxt  = 0
            lytxt  = 0
            lztxt  = 0
            ieps   = 0

            imate = 0
            jmate = 1

            kmate = 0
            ksmte = 0 !FURUTA

            ireso = 1
            width = 0.5

            iout  = 3
            rdout = 50000
            iline = 0
            ishad = 0

            wang  = 0.d0
            mirror = 0

            iaxsh = 1

         do i = 1, icsu

            ischn(i) = 0

         end do

*-----------------------------------------------------------------------
*     read one line from jsi
*-----------------------------------------------------------------------

  140 continue

            call readl(jsn,jsi,dsin,idsi,ill,ilf,'#!$',
     &                 jpn,chin,chlw,chcm,i1,i2,i3,i4,iskip,ierr)

               if( ierr .ne. 0 ) return
               if( jpn  .eq. 3 ) goto 800

