                        vtrs( 6) = 0.0
                        vtrs( 7) = 0.0
                        vtrs( 8) = 1.0
                        vtrs( 9) = 0.0
                        vtrs(10) = 0.0
                        vtrs(11) = 0.0
                        vtrs(12) = 1.0
                        vtrs(13) = 1.0

                     if( itrs .eq. 1 ) then

                        vtrs( 4) =  0.0
                        vtrs( 5) = 90.0
                        vtrs( 6) = 90.0
                        vtrs( 7) = 90.0
                        vtrs( 8) =  0.0
                        vtrs( 9) = 90.0
                        vtrs(10) = 90.0
                        vtrs(11) = 90.0
                        vtrs(12) =  0.0

                     end if

                        ic = jnumc(chlw,ic+1,i3)
