                        goto 972

                     else if( chlw(ic:ic) .eq. ')' .and.
     &                        igkst .gt. 0 ) then

                        ibt = 0

                        ic = jnumc(chlw,ic+1,i3)
                        if( ic .gt. i3 ) goto 155

                     else

                        call unum(chlw,ic,i3,ic2,cvvv,ierr)
