                        ic = jnumc(chlw,ic2,i3)
                        goto 155

                     end if

                  else

                        call snum(chlw,ic,i3,ic2,cvvv,ierr)
                        if( ierr .ne. 0 ) goto 972

                        igkst = igkst + 1
                        if( igkst .ne. 1 ) goto 972

